window.FO_PACKS=window.FO_PACKS||{};window.FO_PACKS["KS1"]={"KS1-001":{"objectives":["Merhaba demek ve adını söylemek","'What's your name?' sorusunu sormak ve yanıtlamak","Kısa bir selamlaşma şarkısını tekrar etmek"],"dialogues":[{"title":"First day at school","setting":"Okulun ilk günü. Ada yeni arkadaşı Tom ile tanışıyor.","lines":[{"s":"Ada","en":"Hello! I'm Ada.","tr":"Merhaba! Ben Ada."},{"s":"Tom","en":"Hi, Ada! I'm Tom.","tr":"Selam Ada! Ben Tom."},{"s":"Ada","en":"Nice to meet you, Tom!","tr":"Tanıştığımıza memnun oldum Tom!"},{"s":"Tom","en":"Nice to meet you, too!","tr":"Ben de memnun oldum!"},{"s":"Ada","en":"Let's play!","tr":"Hadi oynayalım!"},{"s":"Tom","en":"Yes! Let's play!","tr":"Evet! Hadi oynayalım!"}]},{"title":"What's your name?","setting":"Öğretmen Miss Kate sınıftaki yeni kızla konuşuyor.","lines":[{"s":"Kate","en":"Good morning!","tr":"Günaydın!"},{"s":"Mia","en":"Good morning, teacher!","tr":"Günaydın öğretmenim!"},{"s":"Kate","en":"What's your name?","tr":"Adın ne?"},{"s":"Mia","en":"My name is Mia.","tr":"Benim adım Mia."},{"s":"Kate","en":"Welcome, Mia!","tr":"Hoş geldin Mia!"},{"s":"Mia","en":"Thank you!","tr":"Teşekkür ederim!"}]},{"title":"Goodbye song","setting":"Ders bitti. El salla ve şarkıyı söyle!","lines":[{"s":"Teacher","en":"Hello, hello! What's your name?","tr":"Merhaba, merhaba! Adın ne?"},{"s":"Kids","en":"Hello, hello! My name is...","tr":"Merhaba, merhaba! Benim adım..."},{"s":"Teacher","en":"Goodbye, goodbye! See you soon!","tr":"Hoşça kal, hoşça kal! Yakında görüşürüz!"},{"s":"Kids","en":"Goodbye, goodbye! See you soon!","tr":"Hoşça kal, hoşça kal! Yakında görüşürüz!"},{"s":"Teacher","en":"Wave your hand. Bye-bye!","tr":"Elini salla. Bay bay!"}]}],"reading":{"title":"Hello, I'm Ada","paras":[{"en":"Hello! I'm Ada. I'm seven. This is my friend Tom. He is seven, too. We are at school. Our teacher is Miss Kate. She is nice. In the morning, we say, \"Good morning!\" At home time, we say, \"Goodbye!\" I like my school. I like my new friend.","tr":"Merhaba! Ben Ada. Yedi yaşındayım. Bu arkadaşım Tom. O da yedi yaşında. Okuldayız. Öğretmenimiz Miss Kate. O çok tatlı. Sabahları \"Günaydın!\" deriz. Eve gitme zamanı \"Hoşça kal!\" deriz. Okulumu severim. Yeni arkadaşımı severim."}]},"vocab":[{"w":"hello","ipa":"/həˈləʊ/","pos":"👋","tr":"merhaba","ex":"Hello! I'm Ada.","exTr":"Merhaba! Ben Ada."},{"w":"goodbye","ipa":"/ɡʊdˈbaɪ/","pos":"🙋","tr":"hoşça kal","ex":"Goodbye, Tom!","exTr":"Hoşça kal Tom!"},{"w":"name","ipa":"/neɪm/","pos":"🏷️","tr":"ad, isim","ex":"My name is Mia.","exTr":"Benim adım Mia."},{"w":"friend","ipa":"/frend/","pos":"🧑‍🤝‍🧑","tr":"arkadaş","ex":"Tom is my friend.","exTr":"Tom benim arkadaşım."},{"w":"teacher","ipa":"/ˈtiːtʃə/","pos":"👩‍🏫","tr":"öğretmen","ex":"Miss Kate is my teacher.","exTr":"Miss Kate benim öğretmenim."},{"w":"school","ipa":"/skuːl/","pos":"🏫","tr":"okul","ex":"I like my school.","exTr":"Okulumu severim."},{"w":"morning","ipa":"/ˈmɔːnɪŋ/","pos":"🌅","tr":"sabah","ex":"Good morning!","exTr":"Günaydın!"},{"w":"play","ipa":"/pleɪ/","pos":"⚽","tr":"oynamak","ex":"Let's play!","exTr":"Hadi oynayalım!"}],"chunks":[{"en":"Hello! I'm…","tr":"Merhaba! Ben …"},{"en":"What's your name?","tr":"Adın ne?"},{"en":"My name is…","tr":"Benim adım …"},{"en":"Nice to meet you!","tr":"Tanıştığımıza memnun oldum!"}],"grammar":{"point":"I'm / My name is","tr":"Kendini tanıtırken 'I'm' (ben ...im) veya 'My name is' (benim adım ...) deriz. Adını sormak için 'What's your name?' deriz.","examples":["I'm Ada.","My name is Tom.","What's your name?","I'm seven."]},"questions":[{"q":"What's the teacher's name?","a":"Miss Kate."},{"q":"How old is Ada?","a":"She's seven."},{"q":"What do the kids say in the morning?","a":"Good morning!"}],"quiz":[{"q":"👋 is…","o":["goodbye","hello","school"],"a":1,"why":""},{"q":"'What's your ___?'","o":["name","friend","morning"],"a":0,"why":""},{"q":"Tom says: 'Hi, Ada! I'm ___.'","o":["Mia","Kate","Tom"],"a":2,"why":""},{"q":"At home time we say…","o":["Good morning!","Goodbye!","Welcome!"],"a":1,"why":""}],"drills":[{"type":"Yerine koyma","prompt":"I'm Ada.","cue":"Tom","answer":"I'm Tom."},{"type":"Yerine koyma","prompt":"My name is Mia.","cue":"Ada","answer":"My name is Ada."},{"type":"Soru yap","prompt":"My name is Mia.","cue":"What…?","answer":"What's your name?"}],"sounds":[{"focus":"/h/","tr":"Elini ağzının önüne tut ve hafifçe nefes ver: 'hello', 'hi'. Sıcak hava çıkmalı!","pairs":["hello / ello","hi / eye"]}],"mission":{"brief":"Oyun: Yeni bir arkadaşla tanış. Claude, sınıfa yeni gelen Sam olacak. Merhaba de, adını söyle ve onun adını sor.","persona":"Sam, a friendly 7-year-old new student. Uses very short, simple sentences and lots of encouragement. Asks one question at a time. Hidden fact: Sam's favourite colour is blue, but he only says it if the child asks 'What's your favourite colour?'.","goal":"Merhaba de, adını söyle ve Sam'in adını sor.","opener":"Hello! I'm Sam. I'm new. What's your name?"}},"KS1-002":{"objectives":["Aile bireylerini söylemek","'This is my…' kalıbını kullanmak","Kısa bir şarkı ritmiyle tekrar etmek"],"dialogues":[{"title":"Meet my family","setting":"Zeynep arkadaşı Leo'ya aile fotoğrafını gösteriyor.","lines":[{"s":"Zeynep","en":"Look, Leo! This is my family.","tr":"Bak Leo! Bu benim ailem."},{"s":"Leo","en":"Wow! Who is this?","tr":"Vay! Bu kim?"},{"s":"Zeynep","en":"This is my mum. She's funny.","tr":"Bu annem. O çok komik."},{"s":"Leo","en":"And who is he?","tr":"Peki o kim?"},{"s":"Zeynep","en":"He's my dad. He's tall!","tr":"O babam. Çok uzun!"},{"s":"Leo","en":"Is this your brother?","tr":"Bu senin erkek kardeşin mi?"},{"s":"Zeynep","en":"Yes! His name is Can. He's four.","tr":"Evet! Adı Can. Dört yaşında."},{"s":"Leo","en":"I love your family!","tr":"Aileni çok sevdim!"}]},{"title":"Grandma's cake","setting":"Hafta sonu, büyükannede.","lines":[{"s":"Grandma","en":"Hello, my little star! Do you want some cake?","tr":"Merhaba küçük yıldızım! Biraz kek ister misin?"},{"s":"Zeynep","en":"Yes, please, Grandma!","tr":"Evet lütfen, büyükanne!"},{"s":"Grandma","en":"Here you are. Where is Grandpa?","tr":"Buyur. Büyükbaba nerede?"},{"s":"Zeynep","en":"He's in the garden with Can.","tr":"Bahçede, Can'la birlikte."},{"s":"Grandma","en":"Let's take some cake to them!","tr":"Onlara da kek götürelim!"}]},{"title":"Family song","setting":"Ritimle tekrar et, alkışla!","lines":[{"s":"Teacher","en":"Mummy, Daddy, sister, brother!","tr":"Anne, baba, kız kardeş, erkek kardeş!"},{"s":"Kids","en":"Mummy, Daddy, sister, brother!","tr":"Anne, baba, kız kardeş, erkek kardeş!"},{"s":"Teacher","en":"Grandma, Grandpa, love each other!","tr":"Büyükanne, büyükbaba, birbirini sever!"},{"s":"Kids","en":"Grandma, Grandpa, love each other!","tr":"Büyükanne, büyükbaba, birbirini sever!"}]}],"reading":{"title":"Zeynep's family","paras":[{"en":"Hi! I'm Zeynep. I'm seven. I have a mum, a dad and a little brother. My brother is Can. He likes cars. My mum likes books. My dad likes football. I like drawing! We are a happy family.","tr":"Merhaba! Ben Zeynep. Yedi yaşındayım. Bir annem, bir babam ve küçük bir erkek kardeşim var. Kardeşimin adı Can. Arabaları sever. Annem kitapları sever. Babam futbolu sever. Ben resim yapmayı severim! Biz mutlu bir aileyiz."}]},"vocab":[{"w":"mum","ipa":"/mʌm/","pos":"👩","tr":"anne","ex":"This is my mum.","exTr":"Bu annem."},{"w":"dad","ipa":"/dæd/","pos":"👨","tr":"baba","ex":"My dad is tall.","exTr":"Babam uzun."},{"w":"brother","ipa":"/ˈbrʌðə/","pos":"👦","tr":"erkek kardeş","ex":"My brother is four.","exTr":"Erkek kardeşim dört yaşında."},{"w":"sister","ipa":"/ˈsɪstə/","pos":"👧","tr":"kız kardeş","ex":"I have a sister.","exTr":"Bir kız kardeşim var."},{"w":"grandma","ipa":"/ˈɡrænmɑː/","pos":"👵","tr":"büyükanne","ex":"Grandma makes cake.","exTr":"Büyükannem kek yapar."},{"w":"grandpa","ipa":"/ˈɡrænpɑː/","pos":"👴","tr":"büyükbaba","ex":"Grandpa is in the garden.","exTr":"Büyükbabam bahçede."},{"w":"family","ipa":"/ˈfæməli/","pos":"👨‍👩‍👧‍👦","tr":"aile","ex":"I love my family.","exTr":"Ailemi seviyorum."},{"w":"baby","ipa":"/ˈbeɪbi/","pos":"👶","tr":"bebek","ex":"The baby is sleeping.","exTr":"Bebek uyuyor."}],"chunks":[{"en":"This is my…","tr":"Bu benim…"},{"en":"Who is this?","tr":"Bu kim?"},{"en":"He's / She's…","tr":"O (erkek / kız)…"},{"en":"I love my family!","tr":"Ailemi seviyorum!"}],"grammar":{"point":"He / She","tr":"Erkekler için 'he', kızlar ve kadınlar için 'she'. Türkçede ikisi de 'o'.","examples":["He's my dad.","She's my mum.","He's my brother.","She's my grandma."]},"questions":[{"q":"How old is Zeynep?","a":"She's seven."},{"q":"What does Can like?","a":"Cars."},{"q":"Where is Grandpa?","a":"In the garden."}],"quiz":[{"q":"👩 is…","o":["dad","mum","brother"],"a":1,"why":""},{"q":"'He's my ___.' (👨)","o":["mum","sister","dad"],"a":2,"why":""},{"q":"Grandma ___ cake.","o":["makes","is","has got to"],"a":0,"why":""},{"q":"Can is…","o":["Zeynep's brother","Zeynep's dad","Leo's sister"],"a":0,"why":""}],"drills":[{"type":"Yerine koyma","prompt":"This is my mum.","cue":"dad","answer":"This is my dad."},{"type":"Yerine koyma","prompt":"She's my sister.","cue":"brother → He","answer":"He's my brother."}],"sounds":[{"focus":"/ð/","tr":"Dili dişlerin arasına koy ve titret: 'the', 'this', 'brother'.","pairs":["this / dis","brother / brudder"]}],"mission":{"brief":"Oyun: Ailenden birini İngilizce tanıt. Claude, arkadaşın Leo olacak ve sana basit sorular soracak.","persona":"Leo, a friendly 7-year-old. Uses very short, simple sentences and lots of encouragement. Asks one question at a time.","goal":"En az üç aile bireyini 'This is my…' ile tanıt.","opener":"Hi! I'm Leo. Do you have a photo of your family?"}},"KS1-003":{"objectives":["Temel renkleri İngilizce söylemek","'What colour is it?' sorusunu sormak ve yanıtlamak","Renkli nesneleri 'It's…' ile tarif etmek"],"dialogues":[{"title":"Paint time","setting":"Sanat dersinde Leo ve Ada boyama yapıyor.","lines":[{"s":"Leo","en":"Look, Ada! My ball is red.","tr":"Bak Ada! Benim topum kırmızı."},{"s":"Ada","en":"Wow! I like red.","tr":"Vay! Kırmızıyı severim."},{"s":"Leo","en":"What colour is your cat?","tr":"Kedinin rengi ne?"},{"s":"Ada","en":"It's yellow!","tr":"Sarı!"},{"s":"Leo","en":"A yellow cat? Funny!","tr":"Sarı bir kedi mi? Komik!"},{"s":"Ada","en":"Yes! Now paint with me.","tr":"Evet! Şimdi benimle boya."}]},{"title":"In the garden","setting":"Mia ve annesi bahçede renkli şeyleri arıyor.","lines":[{"s":"Mum","en":"What colour is the sky, Mia?","tr":"Gökyüzü ne renk Mia?"},{"s":"Mia","en":"It's blue!","tr":"Mavi!"},{"s":"Mum","en":"And the grass?","tr":"Peki çimen?"},{"s":"Mia","en":"It's green!","tr":"Yeşil!"},{"s":"Mum","en":"What colour is the flower?","tr":"Çiçek ne renk?"},{"s":"Mia","en":"It's pink. I love pink!","tr":"Pembe. Pembeyi çok severim!"},{"s":"Mum","en":"Well done, Mia!","tr":"Aferin Mia!"}]},{"title":"Rainbow song","setting":"Gökkuşağı şarkısı! Renkleri göster ve söyle.","lines":[{"s":"Teacher","en":"Red and yellow, green and blue!","tr":"Kırmızı ve sarı, yeşil ve mavi!"},{"s":"Kids","en":"Red and yellow, green and blue!","tr":"Kırmızı ve sarı, yeşil ve mavi!"},{"s":"Teacher","en":"Orange, purple, I love you!","tr":"Turuncu, mor, seni seviyorum!"},{"s":"Kids","en":"Orange, purple, I love you!","tr":"Turuncu, mor, seni seviyorum!"},{"s":"Teacher","en":"A rainbow in the sky!","tr":"Gökyüzünde bir gökkuşağı!"}]}],"reading":{"title":"My colourful day","paras":[{"en":"I'm Mia. I like colours! The sky is blue. The grass is green. The sun is yellow. My ball is red. My flower is pink. My cat is orange. It is funny! I have a box of crayons. I paint a big rainbow. I love colours.","tr":"Ben Mia. Renkleri severim! Gökyüzü mavi. Çimen yeşil. Güneş sarı. Topum kırmızı. Çiçeğim pembe. Kedim turuncu. Çok komik! Bir kutu boya kalemim var. Büyük bir gökkuşağı boyarım. Renkleri çok severim."}]},"vocab":[{"w":"red","ipa":"/red/","pos":"🔴","tr":"kırmızı","ex":"My ball is red.","exTr":"Topum kırmızı."},{"w":"blue","ipa":"/bluː/","pos":"🔵","tr":"mavi","ex":"The sky is blue.","exTr":"Gökyüzü mavi."},{"w":"green","ipa":"/ɡriːn/","pos":"🟢","tr":"yeşil","ex":"The grass is green.","exTr":"Çimen yeşil."},{"w":"yellow","ipa":"/ˈjeləʊ/","pos":"🟡","tr":"sarı","ex":"The sun is yellow.","exTr":"Güneş sarı."},{"w":"orange","ipa":"/ˈɒrɪndʒ/","pos":"🟠","tr":"turuncu","ex":"My cat is orange.","exTr":"Kedim turuncu."},{"w":"pink","ipa":"/pɪŋk/","pos":"🌸","tr":"pembe","ex":"The flower is pink.","exTr":"Çiçek pembe."},{"w":"purple","ipa":"/ˈpɜːpl/","pos":"🟣","tr":"mor","ex":"I have a purple crayon.","exTr":"Mor bir boya kalemim var."},{"w":"rainbow","ipa":"/ˈreɪnbəʊ/","pos":"🌈","tr":"gökkuşağı","ex":"I paint a big rainbow.","exTr":"Büyük bir gökkuşağı boyarım."}],"chunks":[{"en":"What colour is it?","tr":"Bu ne renk?"},{"en":"It's red!","tr":"Kırmızı!"},{"en":"I like blue.","tr":"Maviyi severim."},{"en":"Well done!","tr":"Aferin!"}],"grammar":{"point":"It's + colour","tr":"Bir şeyin rengini söylerken 'It's' ve renk kelimesini kullanırız. Rengi sormak için 'What colour is it?' deriz.","examples":["It's red.","It's green.","The sky is blue.","What colour is it?"]},"questions":[{"q":"What colour is the sky?","a":"It's blue."},{"q":"What colour is Ada's cat?","a":"It's yellow."},{"q":"What does Mia paint?","a":"A big rainbow."}],"quiz":[{"q":"🟢 is…","o":["red","blue","green"],"a":2,"why":""},{"q":"The sun is ___.","o":["yellow","purple","pink"],"a":0,"why":""},{"q":"'___ colour is it?'","o":["Who","What","Where"],"a":1,"why":""},{"q":"Mia's flower is…","o":["blue","orange","pink"],"a":2,"why":""}],"drills":[{"type":"Yerine koyma","prompt":"My ball is red.","cue":"blue","answer":"My ball is blue."},{"type":"Yerine koyma","prompt":"The sky is blue.","cue":"grass / green","answer":"The grass is green."},{"type":"Soru yap","prompt":"It's yellow.","cue":"What…?","answer":"What colour is it?"}],"sounds":[{"focus":"/r/","tr":"Türkçedeki r gibi dilini titretme. Dilini geri çek ve dokundurmadan 'rrr' de: 'red', 'green', 'rainbow'.","pairs":["red / led","right / light"]}],"mission":{"brief":"Oyun: Renk avı! Claude, arkadaşın Zoe olacak. Etrafındaki nesnelerin rengini İngilizce söyle ve Zoe'ye rengini sor.","persona":"Zoe, a cheerful 7-year-old. Uses very short, simple sentences and lots of encouragement. Asks one question at a time. Hidden fact: Zoe's secret favourite colour is purple, but she only says it if the child asks 'What's your favourite colour?'.","goal":"En az üç nesnenin rengini 'It's…' ile söyle.","opener":"Hi! I'm Zoe. Look at my bag. What colour is it?"}},"KS1-004":{"objectives":["1'den 20'ye kadar sayıları İngilizce söylemek","'How many?' sorusunu sormak ve yanıtlamak","Nesneleri sayarak ritimli bir şarkı söylemek"],"dialogues":[{"title":"Counting apples","setting":"Can ve annesi mutfakta elmaları sayıyor.","lines":[{"s":"Mum","en":"Can, how many apples?","tr":"Can, kaç tane elma var?"},{"s":"Can","en":"One, two, three, four, five!","tr":"Bir, iki, üç, dört, beş!"},{"s":"Mum","en":"Five apples. Good!","tr":"Beş elma. Aferin!"},{"s":"Can","en":"Can I have one?","tr":"Bir tane alabilir miyim?"},{"s":"Mum","en":"Yes, here you are.","tr":"Evet, buyur."},{"s":"Can","en":"Thank you, Mum!","tr":"Teşekkürler anne!"}]},{"title":"How old are you?","setting":"Doğum günü partisinde Ada ve Leo yaşlarını söylüyor.","lines":[{"s":"Leo","en":"Hi, Ada! How old are you?","tr":"Selam Ada! Kaç yaşındasın?"},{"s":"Ada","en":"I'm seven. How old are you?","tr":"Yedi yaşındayım. Sen kaç yaşındasın?"},{"s":"Leo","en":"I'm eight today!","tr":"Bugün sekiz yaşındayım!"},{"s":"Ada","en":"Happy birthday, Leo!","tr":"Doğum günün kutlu olsun Leo!"},{"s":"Leo","en":"Look! Eight candles.","tr":"Bak! Sekiz mum."},{"s":"Ada","en":"Let's count: one, two, three...","tr":"Hadi sayalım: bir, iki, üç..."}]},{"title":"Number song","setting":"Parmaklarınla say ve alkışla!","lines":[{"s":"Teacher","en":"One, two, three, four, five!","tr":"Bir, iki, üç, dört, beş!"},{"s":"Kids","en":"One, two, three, four, five!","tr":"Bir, iki, üç, dört, beş!"},{"s":"Teacher","en":"Six, seven, eight, nine, ten!","tr":"Altı, yedi, sekiz, dokuz, on!"},{"s":"Kids","en":"Six, seven, eight, nine, ten!","tr":"Altı, yedi, sekiz, dokuz, on!"},{"s":"Teacher","en":"Ten and ten make twenty!","tr":"On ile on yirmi eder!"}]}],"reading":{"title":"Counting in my room","paras":[{"en":"I'm Leo. I'm eight. Look at my room! I have two books. I have five cars. I have ten crayons. I have twelve stickers. I have twenty beads in a box. I like numbers. I count every day. One, two, three, four. Counting is fun!","tr":"Ben Leo. Sekiz yaşındayım. Odama bak! İki kitabım var. Beş arabam var. On boya kalemim var. On iki çıkartmam var. Bir kutuda yirmi boncuğum var. Sayıları severim. Her gün sayarım. Bir, iki, üç, dört. Saymak çok eğlenceli!"}]},"vocab":[{"w":"one","ipa":"/wʌn/","pos":"1️⃣","tr":"bir","ex":"I have one ball.","exTr":"Bir topum var."},{"w":"two","ipa":"/tuː/","pos":"2️⃣","tr":"iki","ex":"I have two books.","exTr":"İki kitabım var."},{"w":"five","ipa":"/faɪv/","pos":"5️⃣","tr":"beş","ex":"I have five cars.","exTr":"Beş arabam var."},{"w":"eight","ipa":"/eɪt/","pos":"8️⃣","tr":"sekiz","ex":"I'm eight today.","exTr":"Bugün sekiz yaşındayım."},{"w":"ten","ipa":"/ten/","pos":"🔟","tr":"on","ex":"I have ten crayons.","exTr":"On boya kalemim var."},{"w":"twelve","ipa":"/twelv/","pos":"🕛","tr":"on iki","ex":"I have twelve stickers.","exTr":"On iki çıkartmam var."},{"w":"twenty","ipa":"/ˈtwenti/","pos":"🧮","tr":"yirmi","ex":"Twenty beads are in the box.","exTr":"Kutuda yirmi boncuk var."},{"w":"count","ipa":"/kaʊnt/","pos":"👆","tr":"saymak","ex":"I count every day.","exTr":"Her gün sayarım."}],"chunks":[{"en":"How many?","tr":"Kaç tane?"},{"en":"How old are you?","tr":"Kaç yaşındasın?"},{"en":"I'm seven.","tr":"Yedi yaşındayım."},{"en":"Let's count!","tr":"Hadi sayalım!"}],"grammar":{"point":"I have + number","tr":"Sahip olduğumuz şeyleri sayıyla söylemek için 'I have' kullanırız. Birden fazla şey varsa kelimenin sonuna s ekleriz: one car, two cars.","examples":["I have one ball.","I have two books.","I have five cars.","How many crayons?"]},"questions":[{"q":"How many apples does Can count?","a":"Five."},{"q":"How old is Leo today?","a":"He's eight."},{"q":"How many beads are in Leo's box?","a":"Twenty."}],"quiz":[{"q":"5️⃣ is…","o":["five","eight","ten"],"a":0,"why":""},{"q":"'I have ___ books.' (2)","o":["ten","one","two"],"a":2,"why":""},{"q":"'___ many cars?'","o":["What","How","Who"],"a":1,"why":""},{"q":"Ten and ten make…","o":["twelve","twenty","two"],"a":1,"why":""}],"drills":[{"type":"Yerine koyma","prompt":"I have two books.","cue":"five / cars","answer":"I have five cars."},{"type":"Yerine koyma","prompt":"I'm seven.","cue":"eight","answer":"I'm eight."},{"type":"Soru yap","prompt":"I have ten crayons.","cue":"How many…?","answer":"How many crayons?"}],"sounds":[{"focus":"/w/","tr":"Dudaklarını yuvarla ve 'u' gibi başla: 'one', 'twenty', 'twelve'. Türkçedeki v gibi söyleme, dişin dudağa değmesin!","pairs":["west / vest","wine / vine"]}],"mission":{"brief":"Oyun: Say bakalım! Claude, arkadaşın Max olacak. Max sana oyuncaklarını gösterecek. Sen onları İngilizce say ve Max'e kaç tane olduğunu sor.","persona":"Max, a cheerful 7-year-old. Uses very short, simple sentences and lots of encouragement. Asks one question at a time. Hidden fact: Max has exactly twelve toy cars, but he only says the number if the child asks 'How many cars?'.","goal":"En az üç şeyi İngilizce say ve 'How many…?' diye sor.","opener":"Hi! I'm Max. Look at my toys. I have cars! Can you count?"}},"KS1-005":{"objectives":["Oyuncak isimlerini İngilizce söylemek","'I have a…' ve 'Do you have a…?' kalıplarını kullanmak","Oyuncaklarını arkadaşlarına tanıtmak"],"dialogues":[{"title":"My toy box","setting":"Leo yeni arkadaşı Ada'ya oyuncak kutusunu gösteriyor.","lines":[{"s":"Leo","en":"Look, Ada! This is my toy box.","tr":"Bak Ada! Bu benim oyuncak kutum."},{"s":"Ada","en":"Wow! What's this?","tr":"Vay! Bu ne?"},{"s":"Leo","en":"It's a robot. It's my favourite.","tr":"Bu bir robot. En sevdiğim."},{"s":"Ada","en":"I have a robot, too!","tr":"Benim de bir robotum var!"},{"s":"Leo","en":"Cool! Do you have a ball?","tr":"Harika! Topun var mı?"},{"s":"Ada","en":"Yes, I do. It's red.","tr":"Evet, var. Kırmızı."}]},{"title":"Let's play together","setting":"Mia ve Can parkta oyuncaklarını paylaşıyor.","lines":[{"s":"Mia","en":"Hi, Can! I have a doll.","tr":"Selam Can! Benim bir bebeğim var."},{"s":"Can","en":"I have a car. It's blue.","tr":"Benim bir arabam var. Mavi."},{"s":"Mia","en":"Can I play with your car?","tr":"Arabanla oynayabilir miyim?"},{"s":"Can","en":"Yes, sure! Here you are.","tr":"Tabii! Buyur."},{"s":"Mia","en":"Thank you! You can play with my doll.","tr":"Teşekkürler! Sen de bebeğimle oynayabilirsin."},{"s":"Can","en":"No, thanks. I like my car!","tr":"Hayır, sağ ol. Ben arabamı seviyorum!"}]},{"title":"Toy chant","setting":"Oyuncakları göster ve ritimle söyle!","lines":[{"s":"Teacher","en":"Ball, doll, teddy, car!","tr":"Top, bebek, ayıcık, araba!"},{"s":"Kids","en":"Ball, doll, teddy, car!","tr":"Top, bebek, ayıcık, araba!"},{"s":"Teacher","en":"Robot, kite, yo-yo, star!","tr":"Robot, uçurtma, yo-yo, yıldız!"},{"s":"Kids","en":"Robot, kite, yo-yo, star!","tr":"Robot, uçurtma, yo-yo, yıldız!"},{"s":"Teacher","en":"I love my toys!","tr":"Oyuncaklarımı seviyorum!"}]}],"reading":{"title":"Leo's toys","paras":[{"en":"I'm Leo. I have many toys. I have a red ball. I have a blue car. I have a big teddy bear. My robot is my favourite. It is silver. It can walk and talk! I put my toys in a box. At night I say, \"Good night, toys!\"","tr":"Ben Leo. Çok oyuncağım var. Kırmızı bir topum var. Mavi bir arabam var. Büyük bir oyuncak ayım var. En sevdiğim robotum. Gümüş renkli. Yürüyebilir ve konuşabilir! Oyuncaklarımı bir kutuya koyarım. Geceleri \"İyi geceler oyuncaklar!\" derim."}]},"vocab":[{"w":"ball","ipa":"/bɔːl/","pos":"⚽","tr":"top","ex":"I have a red ball.","exTr":"Kırmızı bir topum var."},{"w":"doll","ipa":"/dɒl/","pos":"🪆","tr":"oyuncak bebek","ex":"Mia has a doll.","exTr":"Mia'nın bir oyuncak bebeği var."},{"w":"car","ipa":"/kɑː/","pos":"🚗","tr":"araba","ex":"I have a blue car.","exTr":"Mavi bir arabam var."},{"w":"teddy bear","ipa":"/ˈtedi beə/","pos":"🧸","tr":"oyuncak ayı","ex":"I have a big teddy bear.","exTr":"Büyük bir oyuncak ayım var."},{"w":"robot","ipa":"/ˈrəʊbɒt/","pos":"🤖","tr":"robot","ex":"My robot can walk.","exTr":"Robotum yürüyebilir."},{"w":"kite","ipa":"/kaɪt/","pos":"🪁","tr":"uçurtma","ex":"The kite is in the sky.","exTr":"Uçurtma gökyüzünde."},{"w":"box","ipa":"/bɒks/","pos":"📦","tr":"kutu","ex":"My toys are in the box.","exTr":"Oyuncaklarım kutuda."},{"w":"toy","ipa":"/tɔɪ/","pos":"🎁","tr":"oyuncak","ex":"I love my toys.","exTr":"Oyuncaklarımı seviyorum."}],"chunks":[{"en":"I have a…","tr":"Benim bir … var."},{"en":"Do you have a…?","tr":"Senin bir … var mı?"},{"en":"Can I play with your…?","tr":"…inle oynayabilir miyim?"},{"en":"Here you are.","tr":"Buyur."}],"grammar":{"point":"I have a… / Do you have a…?","tr":"Sahip olduğumuz bir şeyi söylemek için 'I have a' deriz. Sormak için 'Do you have a…?' deriz. Cevap: 'Yes, I do.' veya 'No, I don't.'","examples":["I have a ball.","I have a red car.","Do you have a robot?","Yes, I do."]},"questions":[{"q":"What is Leo's favourite toy?","a":"His robot."},{"q":"What colour is Ada's ball?","a":"It's red."},{"q":"Where does Leo put his toys?","a":"In a box."}],"quiz":[{"q":"🧸 is a…","o":["teddy bear","kite","car"],"a":0,"why":""},{"q":"'Do you ___ a ball?'","o":["is","have","am"],"a":1,"why":""},{"q":"Mia has a…","o":["car","robot","doll"],"a":2,"why":""},{"q":"'Here you are' means…","o":["Buyur","Hoşça kal","Günaydın"],"a":0,"why":""}],"drills":[{"type":"Yerine koyma","prompt":"I have a ball.","cue":"doll","answer":"I have a doll."},{"type":"Yerine koyma","prompt":"I have a red car.","cue":"blue / kite","answer":"I have a blue kite."},{"type":"Soru yap","prompt":"You have a robot.","cue":"Do…?","answer":"Do you have a robot?"}],"sounds":[{"focus":"/ɒ/ – /ɔː/","tr":"'Doll' kısa ve yuvarlak, 'ball' uzun. Ağzını yuvarla: 'doll', 'box', 'ball'. Türkçedeki o gibi kısa söyleme, bazen uzat!","pairs":["doll / ball","box / bore"]}],"mission":{"brief":"Oyun: Oyuncak değişimi! Claude, arkadaşın Ella olacak. Oyuncaklarını anlat ve Ella'ya hangi oyuncakları olduğunu sor.","persona":"Ella, a cheerful 7-year-old. Uses very short, simple sentences and lots of encouragement. Asks one question at a time. Hidden fact: Ella has a secret toy, a tiny purple dinosaur, but she only talks about it if the child asks 'Do you have a dinosaur?'.","goal":"'I have a…' ile en az üç oyuncağını tanıt ve 'Do you have a…?' diye sor.","opener":"Hi! I'm Ella. I love toys! Do you have a toy?"}},"KS1-006":{"objectives":["Çiftlik hayvanlarının adlarını İngilizce söylemek","Hayvanların çıkardığı sesleri tekrar etmek","'I can see a…' kalıbını kullanmak"],"dialogues":[{"title":"At the farm","setting":"Ada ve babası hafta sonu çiftliği geziyor.","lines":[{"s":"Ada","en":"Dad, look! I can see a cow!","tr":"Baba bak! Bir inek görüyorum!"},{"s":"Dad","en":"Yes! What does a cow say?","tr":"Evet! İnek ne der?"},{"s":"Ada","en":"Moo, moo!","tr":"Möö, möö!"},{"s":"Dad","en":"Good! And what's that?","tr":"Aferin! Peki şu ne?"},{"s":"Ada","en":"It's a sheep. Baa, baa!","tr":"Bu bir koyun. Mee, mee!"},{"s":"Dad","en":"You're a farm star!","tr":"Sen bir çiftlik yıldızısın!"}]},{"title":"Feeding time","setting":"Çiftçi Mr. Green çocuklara hayvanları besletiyor.","lines":[{"s":"Mr Green","en":"Hello, kids! Do you like animals?","tr":"Merhaba çocuklar! Hayvanları sever misiniz?"},{"s":"Leo","en":"Yes, we do!","tr":"Evet, severiz!"},{"s":"Mr Green","en":"Here is food for the hens.","tr":"İşte tavuklar için yem."},{"s":"Mia","en":"Chick, chick! Come here, hens!","tr":"Cik cik! Gelin tavuklar!"},{"s":"Mr Green","en":"The duck is hungry, too.","tr":"Ördek de aç."},{"s":"Leo","en":"Quack, quack! Here you are, duck.","tr":"Vak vak! Buyur ördek."},{"s":"Mr Green","en":"Well done, kids!","tr":"Aferin çocuklar!"}]},{"title":"Farm song","setting":"Hayvan seslerini çıkar ve şarkıya katıl!","lines":[{"s":"Teacher","en":"The cow says moo!","tr":"İnek möö der!"},{"s":"Kids","en":"Moo, moo, moo!","tr":"Möö, möö, möö!"},{"s":"Teacher","en":"The duck says quack!","tr":"Ördek vak der!"},{"s":"Kids","en":"Quack, quack, quack!","tr":"Vak, vak, vak!"},{"s":"Teacher","en":"The horse says neigh!","tr":"At kişner!"},{"s":"Kids","en":"Neigh, neigh, neigh!","tr":"Hiii, hiii, hiii!"}]}],"reading":{"title":"A day at the farm","paras":[{"en":"I'm Ada. I'm at the farm today. I can see a cow. It says moo. I can see a sheep. It is white. I can see a horse. It is big and brown. The hens are in the yard. The duck is in the water. I love the farm. The animals are my friends.","tr":"Ben Ada. Bugün çiftlikteyim. Bir inek görüyorum. Möö der. Bir koyun görüyorum. Beyaz. Bir at görüyorum. Büyük ve kahverengi. Tavuklar avluda. Ördek suda. Çiftliği çok severim. Hayvanlar benim arkadaşlarım."}]},"vocab":[{"w":"cow","ipa":"/kaʊ/","pos":"🐄","tr":"inek","ex":"The cow says moo.","exTr":"İnek möö der."},{"w":"sheep","ipa":"/ʃiːp/","pos":"🐑","tr":"koyun","ex":"The sheep is white.","exTr":"Koyun beyaz."},{"w":"horse","ipa":"/hɔːs/","pos":"🐴","tr":"at","ex":"The horse is big and brown.","exTr":"At büyük ve kahverengi."},{"w":"hen","ipa":"/hen/","pos":"🐔","tr":"tavuk","ex":"The hens are in the yard.","exTr":"Tavuklar avluda."},{"w":"duck","ipa":"/dʌk/","pos":"🦆","tr":"ördek","ex":"The duck is in the water.","exTr":"Ördek suda."},{"w":"pig","ipa":"/pɪɡ/","pos":"🐖","tr":"domuz","ex":"The pig is pink.","exTr":"Domuz pembe."},{"w":"farm","ipa":"/fɑːm/","pos":"🚜","tr":"çiftlik","ex":"I love the farm.","exTr":"Çiftliği çok severim."},{"w":"animal","ipa":"/ˈænɪml/","pos":"🐾","tr":"hayvan","ex":"Do you like animals?","exTr":"Hayvanları sever misin?"}],"chunks":[{"en":"I can see a…","tr":"Bir … görüyorum."},{"en":"What does a cow say?","tr":"İnek ne der?"},{"en":"Do you like animals?","tr":"Hayvanları sever misin?"},{"en":"Well done!","tr":"Aferin!"}],"grammar":{"point":"I can see a…","tr":"Gözümüzle gördüğümüz bir şeyi söylemek için 'I can see a' deriz. Birden fazla hayvan varsa 'I can see two cows' deriz. Sormak için 'What can you see?' deriz.","examples":["I can see a cow.","I can see a horse.","I can see two ducks.","What can you see?"]},"questions":[{"q":"What does a cow say?","a":"Moo, moo."},{"q":"What colour is the sheep?","a":"It's white."},{"q":"Where is the duck?","a":"In the water."}],"quiz":[{"q":"🐄 is a…","o":["horse","cow","pig"],"a":1,"why":""},{"q":"The duck says…","o":["moo","quack","baa"],"a":1,"why":""},{"q":"'I can ___ a horse.'","o":["see","is","have"],"a":0,"why":""},{"q":"The hens are in the…","o":["water","yard","sky"],"a":1,"why":""}],"drills":[{"type":"Yerine koyma","prompt":"I can see a cow.","cue":"horse","answer":"I can see a horse."},{"type":"Yerine koyma","prompt":"The sheep is white.","cue":"pig / pink","answer":"The pig is pink."},{"type":"Soru yap","prompt":"The cow says moo.","cue":"What…?","answer":"What does the cow say?"}],"sounds":[{"focus":"/ʃ/","tr":"Türkçedeki ş gibi: dudaklarını biraz öne uzat ve 'şşş' de. 'Sheep' kelimesinde ş sesi var. 'Ship' ile 'sheep' farklı!","pairs":["sheep / ship","she / see"]}],"mission":{"brief":"Oyun: Çiftlik gezisi! Claude, çiftçi Mr. Green olacak. Gördüğün hayvanları İngilizce söyle ve Mr. Green'e bir hayvan sesini sor.","persona":"Mr. Green, a kind farmer who speaks to a 7-year-old. Uses very short, simple sentences and lots of encouragement. Asks one question at a time. Hidden fact: the farm has a baby lamb called Daisy, but he only mentions her if the child asks 'Do you have a baby animal?'.","goal":"'I can see a…' ile en az üç çiftlik hayvanı söyle.","opener":"Hello! I'm Mr Green. Welcome to my farm! What can you see?"}},"KS1-007":{"objectives":["Vahşi hayvanların adlarını söylemek","'I can see a…' kalıbını kullanmak","Hayvanları 'big', 'tall' ve 'loud' kelimeleriyle tarif etmek"],"dialogues":[{"title":"At the zoo","setting":"Ela ve Emir hayvanat bahçesinde, aslanın önünde.","lines":[{"s":"Ela","en":"Look, Emir! I can see a lion.","tr":"Bak Emir! Bir aslan görebiliyorum."},{"s":"Emir","en":"Wow! It is big. And it is loud!","tr":"Vay! Çok büyük. Bir de çok gürültülü!"},{"s":"Ela","en":"Yes! Roar! Roar!","tr":"Evet! Hırr! Hırr!"},{"s":"Emir","en":"I can see a monkey, too. It is funny!","tr":"Ben de bir maymun görebiliyorum. Çok komik!"},{"s":"Ela","en":"Look at the giraffe. It is very tall!","tr":"Zürafaya bak. Çok uzun!"},{"s":"Emir","en":"Wow! It has a long neck.","tr":"Vay! Uzun bir boynu var."},{"s":"Ela","en":"I love the zoo!","tr":"Hayvanat bahçesini çok seviyorum!"}]},{"title":"The animal book","setting":"Evde, Mina ve babası hayvan kitabına bakıyor.","lines":[{"s":"Dad","en":"Do you like animals, Mina?","tr":"Hayvanları sever misin, Mina?"},{"s":"Mina","en":"Yes! I like wild animals.","tr":"Evet! Vahşi hayvanları severim."},{"s":"Dad","en":"Look! Is this a bear?","tr":"Bak! Bu bir ayı mı?"},{"s":"Mina","en":"Yes, it is a bear. It is big and brown.","tr":"Evet, bu bir ayı. Büyük ve kahverengi."},{"s":"Dad","en":"What about this one? It is small.","tr":"Peki ya bu? Küçük."},{"s":"Mina","en":"It is a fox. It is orange!","tr":"Bu bir tilki. Turuncu!"},{"s":"Dad","en":"Well done, Mina!","tr":"Aferin, Mina!"}]},{"title":"Animal chant","setting":"Ritimle tekrar et ve zıpla!","lines":[{"s":"Teacher","en":"Lion, lion, big and loud!","tr":"Aslan, aslan, büyük ve gürültülü!"},{"s":"Kids","en":"Lion, lion, big and loud!","tr":"Aslan, aslan, büyük ve gürültülü!"},{"s":"Teacher","en":"Monkey, monkey, jump and shout!","tr":"Maymun, maymun, zıpla ve bağır!"},{"s":"Kids","en":"Monkey, monkey, jump and shout!","tr":"Maymun, maymun, zıpla ve bağır!"},{"s":"Teacher","en":"Fox, fox, orange tail!","tr":"Tilki, tilki, turuncu kuyruk!"},{"s":"Kids","en":"Fox, fox, orange tail!","tr":"Tilki, tilki, turuncu kuyruk!"}]}],"reading":{"title":"A day at the zoo","paras":[{"en":"Hi! I'm Ali. I love wild animals. Today I went to the zoo with my mum. I saw a lion. It was very big and very loud! I saw a bear, too. It was brown and it was sleeping. My favourite animal is the elephant. It is grey and it has a long trunk. I want to see it again!","tr":"Merhaba! Ben Ali. Vahşi hayvanları çok severim. Bugün annemle hayvanat bahçesine gittim. Bir aslan gördüm. Çok büyüktü ve çok gürültülüydü! Bir ayı da gördüm. Kahverengiydi ve uyuyordu. En sevdiğim hayvan fil. Gri renkli ve uzun bir hortumu var. Onu tekrar görmek istiyorum!"}]},"vocab":[{"w":"lion","ipa":"/ˈlaɪən/","pos":"🦁","tr":"aslan","ex":"I can see a lion.","exTr":"Bir aslan görebiliyorum."},{"w":"bear","ipa":"/beə/","pos":"🐻","tr":"ayı","ex":"The bear is brown.","exTr":"Ayı kahverengi."},{"w":"monkey","ipa":"/ˈmʌŋki/","pos":"🐒","tr":"maymun","ex":"The monkey is funny.","exTr":"Maymun komik."},{"w":"giraffe","ipa":"/dʒəˈrɑːf/","pos":"🦒","tr":"zürafa","ex":"The giraffe is very tall.","exTr":"Zürafa çok uzun."},{"w":"elephant","ipa":"/ˈelɪfənt/","pos":"🐘","tr":"fil","ex":"An elephant is big.","exTr":"Fil büyüktür."},{"w":"fox","ipa":"/fɒks/","pos":"🦊","tr":"tilki","ex":"The fox is orange.","exTr":"Tilki turuncu."},{"w":"tall","ipa":"/tɔːl/","pos":"📏","tr":"uzun (boy)","ex":"My dad is tall.","exTr":"Babam uzun."},{"w":"loud","ipa":"/laʊd/","pos":"📢","tr":"gürültülü, yüksek sesli","ex":"The lion is loud!","exTr":"Aslan gürültülü!"}],"chunks":[{"en":"I can see a…","tr":"Bir … görebiliyorum."},{"en":"Look at the…","tr":"…a bak."},{"en":"Roar!","tr":"Hırr!"},{"en":"It is big.","tr":"Büyük."}],"grammar":{"point":"a / an","tr":"Tek bir hayvandan söz ederken 'a' veya 'an' kullanırız. 'an' sesli bir harfle başlayan kelimenin önüne gelir, ama Türkçede bunun bir karşılığı yoktur.","examples":["I can see a lion.","I can see an elephant.","It is a fox.","It is an orange fox."]},"questions":[{"q":"What did Ali see at the zoo?","a":"A lion and a bear."},{"q":"What colour is the bear?","a":"Brown."},{"q":"What is Ali's favourite animal?","a":"The elephant."}],"quiz":[{"q":"🦁 is a ___.","o":["bear","lion","monkey"],"a":1,"why":""},{"q":"I can see ___ elephant. (🐘)","o":["a","the","an"],"a":2,"why":"Sesli harfle başlayan kelimeden önce 'an' gelir."},{"q":"The giraffe is very ___. (🦒)","o":["tall","loud","brown"],"a":0,"why":""},{"q":"The fox is ___. (🦊)","o":["loud","tall","orange"],"a":2,"why":""}],"drills":[{"type":"Yerine koyma","prompt":"I can see a lion.","cue":"bear","answer":"I can see a bear."},{"type":"Soru yap","prompt":"The bear is brown.","cue":"Ask: 'Is the bear…?'","answer":"Is the bear brown?"},{"type":"Genişletme","prompt":"I can see a lion.","cue":"add 'big'","answer":"I can see a big lion."}],"sounds":[{"focus":"/ɪ/ - /iː/","tr":"Bu iki ses birbirine çok yakın. 'big' kısa ve gevşek söylenir ('bik'), 'bee' uzun ve gergin söylenir ('bii'). Kısa ve uzun 'i' farklı kelimeler yapar, karıştırma.","pairs":["big / bee","sit / seat"]}],"mission":{"brief":"Oyun: Sevdiğin bir vahşi hayvanı İngilizce tarif et. Claude, arkadaşın Leo olacak ve senden hayvanı tahmin etmeye çalışacak.","persona":"Leo, a friendly 7-year-old who loves animals. Uses very short, simple sentences and lots of encouragement. Asks one question at a time. Hidden fact: his favourite animal is the giraffe, but he only says so if the learner asks which animal he likes best.","goal":"Leo'nun en sevdiği hayvanı üç soruda bul.","opener":"Hi! I'm Leo. Do you like wild animals?"}},"KS1-008":{"objectives":["Vücut bölümlerinin adlarını söylemek","'I have…' kalıbını kullanmak","Şarkıyla vücudumuzu hareket ettirerek tekrar etmek"],"dialogues":[{"title":"Touch and say","setting":"Sınıfta öğretmen vücut bölümlerini gösteriyor.","lines":[{"s":"Teacher","en":"Touch your head! Good. Now touch your nose.","tr":"Başına dokun! Aferin. Şimdi burnuna dokun."},{"s":"Ada","en":"Here is my nose!","tr":"İşte burnum!"},{"s":"Teacher","en":"Now touch your ears. One, two!","tr":"Şimdi kulaklarına dokun. Bir, iki!"},{"s":"Ada","en":"I have two ears.","tr":"İki kulağım var."},{"s":"Teacher","en":"Touch your hands. Clap, clap!","tr":"Ellerine dokun. Çırp, çırp!"},{"s":"Ada","en":"I have two hands. Clap, clap!","tr":"İki elim var. Çırp, çırp!"},{"s":"Teacher","en":"Super! You know your body!","tr":"Süper! Vücudunu tanıyorsun!"}]},{"title":"Ouch, my knee!","setting":"Parkta Ali dizine düşüyor ve annesi yanında.","lines":[{"s":"Ali","en":"Mum! My knee hurts!","tr":"Anne! Dizim acıyor!"},{"s":"Mum","en":"Oh no! Show me your knee. Is it red?","tr":"Eyvah! Dizini göster bakayım. Kırmızı mı?"},{"s":"Ali","en":"Yes, it is red.","tr":"Evet, kırmızı."},{"s":"Mum","en":"Don't worry. Here is a kiss!","tr":"Merak etme. İşte bir öpücük!"},{"s":"Ali","en":"Now my knee is better!","tr":"Şimdi dizim daha iyi!"},{"s":"Mum","en":"Good! Stand up, Ali.","tr":"Güzel! Kalk bakalım, Ali."}]},{"title":"Body song","setting":"Ritimle hareket et ve tekrar et!","lines":[{"s":"Teacher","en":"Hands up, feet down! Touch your tummy!","tr":"Eller yukarı, ayaklar aşağı! Karnına dokun!"},{"s":"Kids","en":"Hands up, feet down! Touch your tummy!","tr":"Eller yukarı, ayaklar aşağı! Karnına dokun!"},{"s":"Teacher","en":"Eyes open, mouth shut! Wiggle your toes!","tr":"Gözler açık, ağız kapalı! Ayak parmaklarını oynat!"},{"s":"Kids","en":"Eyes open, mouth shut! Wiggle your toes!","tr":"Gözler açık, ağız kapalı! Ayak parmaklarını oynat!"},{"s":"Teacher","en":"Super! Clap, clap!","tr":"Süper! Çırp, çırp!"},{"s":"Kids","en":"Super! Clap, clap!","tr":"Süper! Çırp, çırp!"}]}],"reading":{"title":"My body","paras":[{"en":"Hi! I'm Mina. I have two eyes and one nose. I have one mouth and two ears. I have two hands and two feet. I can wave with my hands. I have ten fingers and ten toes. I can run and jump with my legs. I like to sing with my mouth! My body is great, and I love it!","tr":"Merhaba! Ben Mina. İki gözüm ve bir burnum var. Bir ağzım ve iki kulağım var. İki elim ve iki ayağım var. Ellerimle el sallayabilirim. On parmağım ve on ayak parmağım var. Bacaklarımla koşup zıplayabilirim. Ağzımla şarkı söylemeyi severim! Vücudum harika ve onu çok seviyorum!"}]},"vocab":[{"w":"head","ipa":"/hed/","pos":"🙂","tr":"kafa","ex":"Touch your head.","exTr":"Kafana dokun."},{"w":"eye","ipa":"/aɪ/","pos":"👁","tr":"göz","ex":"I have two eyes.","exTr":"İki gözüm var."},{"w":"nose","ipa":"/nəʊz/","pos":"👃","tr":"burun","ex":"I have one nose.","exTr":"Bir burnum var."},{"w":"mouth","ipa":"/maʊθ/","pos":"👄","tr":"ağız","ex":"Eyes open, mouth shut.","exTr":"Gözler açık, ağız kapalı."},{"w":"ear","ipa":"/ɪə/","pos":"👂","tr":"kulak","ex":"I have two ears.","exTr":"İki kulağım var."},{"w":"hand","ipa":"/hænd/","pos":"✋","tr":"el","ex":"I have two hands.","exTr":"İki elim var."},{"w":"knee","ipa":"/niː/","pos":"🦵","tr":"diz","ex":"My knee hurts.","exTr":"Dizim acıyor."},{"w":"toe","ipa":"/təʊ/","pos":"🦶","tr":"ayak parmağı","ex":"I have ten toes.","exTr":"On ayak parmağım var."}],"chunks":[{"en":"Touch your…","tr":"…vücut bölümüne dokun."},{"en":"I have two…","tr":"İki … var."},{"en":"Ouch!","tr":"Ay!"},{"en":"Clap, clap!","tr":"Çırp, çırp!"}],"grammar":{"point":"I have…","tr":"'I have' Türkçedeki 'bende … var' ya da 'benim … var' anlamına gelir. Vücut bölümlerini söylerken 'I have two…' gibi sayı ekleriz.","examples":["I have two eyes.","I have one nose.","I have ten toes.","I have two hands."]},"questions":[{"q":"How many hands does Mina have?","a":"Two hands."},{"q":"How many toes does Mina have?","a":"Ten toes."},{"q":"What hurts Ali?","a":"His knee."}],"quiz":[{"q":"👃 is your ___.","o":["nose","ear","knee"],"a":0,"why":""},{"q":"I have two ___. (👂)","o":["nose","knee","ears"],"a":2,"why":""},{"q":"'Ouch! My ___ hurts!' (🦵)","o":["toes","knee","head"],"a":1,"why":""},{"q":"I have ten ___. (🦶)","o":["toes","hands","ears"],"a":0,"why":""}],"drills":[{"type":"Yerine koyma","prompt":"I have two ears.","cue":"eyes","answer":"I have two eyes."},{"type":"Soru yap","prompt":"I have two hands.","cue":"Ask: 'Do you have…?'","answer":"Do you have two hands?"},{"type":"Genişletme","prompt":"I have one nose.","cue":"add 'big'","answer":"I have one big nose."}],"sounds":[{"focus":"/θ/","tr":"Dilini üst dişlerinin arasına koy ve hafifçe üfle: 'three', 'mouth'. Türkçede bu ses yok; 'f' ya da 's' gibi söyleme.","pairs":["three / free","mouth / mouse"]}],"mission":{"brief":"Oyun: Vücudundaki bölümleri İngilizce göster ve say. Claude, arkadaşın Leo olacak ve sana vücudunla ilgili sorular soracak.","persona":"Leo, a friendly 7-year-old who is learning body parts. Uses very short, simple sentences and lots of encouragement. Asks one question at a time. Hidden fact: he hurt his toe on his bike today; he only mentions it if the learner asks how he feels or what hurts.","goal":"Leo'nun ağrıyan vücut bölümünü üç soruda bul.","opener":"Hi! I'm Leo. Can you show me your head?"}},"KS1-009":{"objectives":["Kıyafet adlarını söylemek","'I wear…' ve 'I want to wear…' kalıplarını kullanmak","Hava durumuna göre kıyafet seçmek"],"dialogues":[{"title":"Getting ready","setting":"Sabah, Ela okula giyinirken annesi yardım ediyor.","lines":[{"s":"Mum","en":"Good morning, Ela! What do you want to wear?","tr":"Günaydın, Ela! Ne giymek istiyorsun?"},{"s":"Ela","en":"I want to wear my red T-shirt.","tr":"Kırmızı tişörtümü giymek istiyorum."},{"s":"Mum","en":"It is cold today. Wear your jacket.","tr":"Bugün hava soğuk. Ceketini giy."},{"s":"Ela","en":"OK! I wear my jacket and my shoes.","tr":"Tamam! Ceketimi ve ayakkabılarımı giyiyorum."},{"s":"Mum","en":"Where are your socks?","tr":"Çoraplarını nerede?"},{"s":"Ela","en":"Here they are! Blue socks.","tr":"İşte burada! Mavi çoraplar."},{"s":"Mum","en":"Great! You look lovely.","tr":"Harika! Çok güzel görünüyorsun."}]},{"title":"New shoes","setting":"Mağazada Ali yeni bir çift ayakkabı bakıyor.","lines":[{"s":"Shopkeeper","en":"Hello! Can I help you?","tr":"Merhaba! Yardımcı olabilir miyim?"},{"s":"Ali","en":"Yes! I want new shoes.","tr":"Evet! Yeni bir ayakkabı istiyorum."},{"s":"Shopkeeper","en":"What colour?","tr":"Ne renk?"},{"s":"Ali","en":"Black, please. And a hat!","tr":"Siyah, lütfen. Bir de şapka!"},{"s":"Shopkeeper","en":"Here are black shoes and a black hat.","tr":"İşte siyah ayakkabılar ve siyah bir şapka."},{"s":"Ali","en":"Thank you! I love them.","tr":"Teşekkürler! Bunları çok sevdim."}]},{"title":"Weather song","setting":"Ritimle tekrar et, hava durumuna göre giyin!","lines":[{"s":"Teacher","en":"Sunny day, hat on! Rainy day, coat on!","tr":"Güneşli gün, şapka tak! Yağmurlu gün, mont giy!"},{"s":"Kids","en":"Sunny day, hat on! Rainy day, coat on!","tr":"Güneşli gün, şapka tak! Yağmurlu gün, mont giy!"},{"s":"Teacher","en":"Cold day, scarf on! Hot day, shorts on!","tr":"Soğuk gün, atkı tak! Sıcak gün, şort giy!"},{"s":"Kids","en":"Cold day, scarf on! Hot day, shorts on!","tr":"Soğuk gün, atkı tak! Sıcak gün, şort giy!"},{"s":"Teacher","en":"Wear, wear, wear your clothes!","tr":"Giy, giy, giy kıyafetlerini!"},{"s":"Kids","en":"Wear, wear, wear your clothes!","tr":"Giy, giy, giy kıyafetlerini!"}]}],"reading":{"title":"What I wear","paras":[{"en":"Hi! I'm Ece. In the summer I wear my blue T-shirt and my shorts. When it is cold I wear my red jacket and my scarf. I wear white socks and black shoes. My favourite thing is my yellow hat. I wear it in the sun. I look nice, don't I? Clothes are fun!","tr":"Merhaba! Ben Ece. Yazın mavi tişörtümü ve şortumu giyerim. Hava soğuk olduğunda kırmızı ceketimi ve atkımı giyerim. Beyaz çoraplar ve siyah ayakkabılar giyerim. En sevdiğim şey sarı şapkam. Onu güneşte takarım. Güzel görünüyorum, değil mi? Kıyafetler çok eğlenceli!"}]},"vocab":[{"w":"hat","ipa":"/hæt/","pos":"🧢","tr":"şapka","ex":"I wear a yellow hat.","exTr":"Sarı bir şapka takıyorum."},{"w":"jacket","ipa":"/ˈdʒækɪt/","pos":"🧥","tr":"ceket","ex":"My red jacket is warm.","exTr":"Kırmızı ceketim sıcak."},{"w":"shoes","ipa":"/ʃuːz/","pos":"👟","tr":"ayakkabı","ex":"I have black shoes.","exTr":"Siyah ayakkabılarım var."},{"w":"socks","ipa":"/sɒks/","pos":"🧦","tr":"çorap","ex":"My socks are blue.","exTr":"Çoraplarım mavi."},{"w":"T-shirt","ipa":"/ˈtiːʃɜːt/","pos":"👕","tr":"tişört","ex":"I wear a blue T-shirt.","exTr":"Mavi bir tişört giyiyorum."},{"w":"scarf","ipa":"/skɑːf/","pos":"🧣","tr":"atkı","ex":"It is cold. Wear your scarf.","exTr":"Hava soğuk. Atkını tak."},{"w":"shorts","ipa":"/ʃɔːts/","pos":"🩳","tr":"şort","ex":"Shorts are for summer.","exTr":"Şort yazlıktır."},{"w":"clothes","ipa":"/kləʊðz/","pos":"👚","tr":"kıyafetler","ex":"I like my clothes.","exTr":"Kıyafetlerimi severim."}],"chunks":[{"en":"I wear…","tr":"… giyiyorum."},{"en":"I want to wear…","tr":"… giymek istiyorum."},{"en":"Here they are!","tr":"İşte burada!"},{"en":"You look lovely.","tr":"Çok güzel görünüyorsun."}],"grammar":{"point":"my (benim)","tr":"'my' Türkçedeki 'benim' kelimesidir ve isimden önce gelir. 'my shoes' benim ayakkabılarım demektir.","examples":["I wear my red T-shirt.","This is my hat.","My socks are blue.","Where are my shoes?"]},"questions":[{"q":"What colour is Ela's T-shirt?","a":"Red."},{"q":"What does Ece wear when it is cold?","a":"Her red jacket and her scarf."},{"q":"What colour are Ela's socks?","a":"Blue."}],"quiz":[{"q":"You wear 🧦 on your ___.","o":["hands","feet","head"],"a":1,"why":""},{"q":"🧢 is a ___.","o":["scarf","shorts","hat"],"a":2,"why":""},{"q":"It is cold. Wear your ___. (🧣)","o":["scarf","shorts","socks"],"a":0,"why":""},{"q":"Ali wants black ___. (👟)","o":["jacket","shoes","clothes"],"a":1,"why":""}],"drills":[{"type":"Yerine koyma","prompt":"I wear my red T-shirt.","cue":"hat","answer":"I wear my red hat."},{"type":"Soru yap","prompt":"This is my hat.","cue":"Ask: 'Is this…?'","answer":"Is this your hat?"},{"type":"Genişletme","prompt":"I wear a jacket.","cue":"add 'red'","answer":"I wear a red jacket."}],"sounds":[{"focus":"/æ/","tr":"Ağzını geniş aç ve 'e' ile 'a' arasında bir ses çıkar: 'hat', 'cat'. 'hot' ve 'cut' gibi farklı seslerle karıştırma.","pairs":["hat / hot","cat / cut"]}],"mission":{"brief":"Oyun: Bugün ne giyeceğini İngilizce anlat. Claude, arkadaşın Leo olacak ve sana hangi kıyafetleri sevdiğini soracak.","persona":"Leo, a friendly 7-year-old who loves dressing up. Uses very short, simple sentences and lots of encouragement. Asks one question at a time. Hidden fact: his favourite clothes are a red raincoat with yellow stars, which he only mentions if the learner asks what he likes to wear when it rains.","goal":"Leo'nun en sevdiği kıyafeti üç soruda bul.","opener":"Hi! What are you wearing today?"}},"KS1-010":{"objectives":["Sınıftaki eşyaların adlarını söylemek","'There is' ve 'There are' kalıplarını kullanmak","Basit sınıf komutlarını anlamak"],"dialogues":[{"title":"Where is my pen?","setting":"Sınıfta öğretmen Ece'ye bir şey soruyor.","lines":[{"s":"Teacher","en":"Good morning, class! Look at the board.","tr":"Günaydın sınıf! Tahtaya bakın."},{"s":"Ece","en":"Good morning, teacher!","tr":"Günaydın öğretmenim!"},{"s":"Teacher","en":"Ece, where is my pen?","tr":"Ece, kalemim nerede?"},{"s":"Ece","en":"It is on the desk.","tr":"Masanın üstünde."},{"s":"Teacher","en":"Thank you! Now open your bag.","tr":"Teşekkürler! Şimdi çantanı aç."},{"s":"Ece","en":"There is a book in my bag. Look!","tr":"Çantamda bir kitap var. Bak!"},{"s":"Teacher","en":"Great! Well done.","tr":"Harika! Aferin."}]},{"title":"Lost pencil case","setting":"Teneffüste Ali kalem kutusunu arıyor.","lines":[{"s":"Ali","en":"Mina, where is my pencil case?","tr":"Mina, kalem kutum nerede?"},{"s":"Mina","en":"Is it under the chair?","tr":"Sandalyenin altında mı?"},{"s":"Ali","en":"No, it is not under the chair.","tr":"Hayır, sandalyenin altında değil."},{"s":"Mina","en":"Look! There is a pencil case on the shelf.","tr":"Bak! Rafın üstünde bir kalem kutusu var."},{"s":"Ali","en":"Oh yes! It is blue. Thank you, Mina!","tr":"Ah evet! Mavi. Teşekkürler, Mina!"}]},{"title":"Class commands","setting":"Ritimle tekrar et ve komutları yap!","lines":[{"s":"Teacher","en":"Stand up! Sit down!","tr":"Ayağa kalkın! Oturun!"},{"s":"Kids","en":"Stand up! Sit down!","tr":"Ayağa kalkın! Oturun!"},{"s":"Teacher","en":"Open your books! Close your books!","tr":"Kitaplarınızı açın! Kitaplarınızı kapatın!"},{"s":"Kids","en":"Open your books! Close your books!","tr":"Kitaplarınızı açın! Kitaplarınızı kapatın!"},{"s":"Teacher","en":"Touch the door! Clap, clap!","tr":"Kapıya dokunun! Çırpın, çırpın!"},{"s":"Kids","en":"Touch the door! Clap, clap!","tr":"Kapıya dokunun! Çırpın, çırpın!"}]}],"reading":{"title":"Our classroom","paras":[{"en":"Hi! I'm Deniz. This is my classroom. There is a big board on the wall. There are twenty chairs and ten desks. There is a clock next to the door. My bag is under my desk. There are colourful pictures on the wall. The window is open. I love my classroom!","tr":"Merhaba! Ben Deniz. Burası benim sınıfım. Duvarda büyük bir tahta var. Yirmi sandalye ve on masa var. Kapının yanında bir saat var. Çantam masamın altında. Duvarda renkli resimler var. Pencere açık. Sınıfımı çok seviyorum!"}]},"vocab":[{"w":"book","ipa":"/bʊk/","pos":"📘","tr":"kitap","ex":"There is a book on my desk.","exTr":"Masamın üstünde bir kitap var."},{"w":"pen","ipa":"/pen/","pos":"🖊","tr":"kalem (tükenmez)","ex":"I have a blue pen.","exTr":"Mavi bir kalemim var."},{"w":"bag","ipa":"/bæɡ/","pos":"🎒","tr":"çanta, okul çantası","ex":"My bag is red.","exTr":"Çantam kırmızı."},{"w":"chair","ipa":"/tʃeə/","pos":"🪑","tr":"sandalye","ex":"There are twenty chairs.","exTr":"Yirmi sandalye var."},{"w":"window","ipa":"/ˈwɪndəʊ/","pos":"🪟","tr":"pencere","ex":"The window is open.","exTr":"Pencere açık."},{"w":"door","ipa":"/dɔː/","pos":"🚪","tr":"kapı","ex":"Touch the door.","exTr":"Kapıya dokun."},{"w":"clock","ipa":"/klɒk/","pos":"🕐","tr":"saat (duvar saati)","ex":"There is a clock on the wall.","exTr":"Duvarda bir saat var."},{"w":"pencil case","ipa":"/ˈpensl keɪs/","pos":"✏️","tr":"kalem kutusu","ex":"My pencil case is blue.","exTr":"Kalem kutum mavi."}],"chunks":[{"en":"There is a…","tr":"Bir … var."},{"en":"There are…","tr":"Birden fazla … var."},{"en":"Look at the board.","tr":"Tahtaya bakın."},{"en":"Sit down, please.","tr":"Lütfen oturun."}],"grammar":{"point":"There is / There are","tr":"Tek bir şeyden söz ederken 'There is', birden fazla şeyden söz ederken 'There are' kullanırız. İkisi de Türkçedeki 'var' anlamına gelir.","examples":["There is a book on the desk.","There is a clock on the wall.","There are twenty chairs.","There are two pens in my bag."]},"questions":[{"q":"Where is Ali's pencil case?","a":"On the shelf."},{"q":"What colour is the pencil case?","a":"Blue."},{"q":"How many chairs are there in the classroom?","a":"Twenty."}],"quiz":[{"q":"🕐 is a ___. (It tells the time.)","o":["door","clock","chair"],"a":1,"why":""},{"q":"There ___ a book in my bag.","o":["is","are","am"],"a":0,"why":""},{"q":"There ___ two chairs.","o":["is","are","be"],"a":1,"why":""},{"q":"Tahtaya bak: '___ the board.'","o":["Look for","Look in","Look at"],"a":2,"why":"'Look at' bir şeye bakmak anlamına gelir."}],"drills":[{"type":"Yerine koyma","prompt":"There is a pen.","cue":"book","answer":"There is a book."},{"type":"Soru yap","prompt":"There are two chairs.","cue":"Ask: 'Are there…?'","answer":"Are there two chairs?"},{"type":"Genişletme","prompt":"There is a clock.","cue":"add 'on the wall'","answer":"There is a clock on the wall."}],"sounds":[{"focus":"/ɔː/","tr":"Dudaklarını yuvarla, ağzını biraz aç ve sesi uzun tut: 'door', 'four'. Türkçedeki kısa 'o' gibi söyleme; 'doll' ile karıştırma.","pairs":["door / doll","four / fork"]}],"mission":{"brief":"Oyun: Sınıfındaki eşyaları İngilizce tarif et ve nerede olduklarını söyle. Claude, aynı sınıftan arkadaşın Leo olacak ve sınıftaki bir oyuncağını bulmanı isteyecek.","persona":"Leo, a friendly 7-year-old in the same class. Uses very short sentences and lots of encouragement. Asks one question at a time. Hidden fact: he hid his toy car in his bag, under his books. He only says where it is if the learner asks about his bag or what is in it.","goal":"Leo'nun sakladığı oyuncak arabayı üç soruda bul.","opener":"Hi! Is there a clock in our classroom?"}},"KS1-011":{"objectives":["Meyve ve sebze adlarını söylemek","'I like' ve 'I don't like' kalıplarını kullanmak","Pazarda basit bir alışveriş yapmak"],"dialogues":[{"title":"At the market","setting":"Pazarda Ali tezgâhtan elma istiyor.","lines":[{"s":"Seller","en":"Hello! Do you want apples?","tr":"Merhaba! Elma ister misin?"},{"s":"Ali","en":"Yes, please! I like apples.","tr":"Evet lütfen! Elmayı severim."},{"s":"Seller","en":"Here are red apples and green pears.","tr":"İşte kırmızı elmalar ve yeşil armutlar."},{"s":"Ali","en":"I like red apples. Can I have two?","tr":"Kırmızı elmaları severim. İki tane alabilir miyim?"},{"s":"Seller","en":"Of course! Here you are.","tr":"Tabii! Buyur."},{"s":"Ali","en":"Thank you! I don't like pears.","tr":"Teşekkürler! Armutları sevmiyorum."},{"s":"Seller","en":"No problem. Have a nice day!","tr":"Sorun değil. İyi günler!"}]},{"title":"Dinner talk","setting":"Akşam yemeğinde Ece annesiyle konuşuyor.","lines":[{"s":"Mum","en":"What do you want for dinner, Ece?","tr":"Akşam yemeğinde ne istersin, Ece?"},{"s":"Ece","en":"I like carrots and tomatoes.","tr":"Havuç ve domatesi severim."},{"s":"Mum","en":"Great! What about broccoli?","tr":"Harika! Peki ya brokoli?"},{"s":"Ece","en":"I don't like broccoli!","tr":"Brokoliyi sevmiyorum!"},{"s":"Mum","en":"Please try one bite.","tr":"Lütfen bir lokma dene."},{"s":"Ece","en":"OK! Yummy, I like it!","tr":"Tamam! Nam, sevdim!"}]},{"title":"Fruit song","setting":"Ritimle tekrar et ve meyve ve sebzeleri say!","lines":[{"s":"Teacher","en":"Apple, banana, orange too!","tr":"Elma, muz, portakal da var!"},{"s":"Kids","en":"Apple, banana, orange too!","tr":"Elma, muz, portakal da var!"},{"s":"Teacher","en":"Carrot, tomato, yes, I do!","tr":"Havuç, domates, evet severim!"},{"s":"Kids","en":"Carrot, tomato, yes, I do!","tr":"Havuç, domates, evet severim!"},{"s":"Teacher","en":"Eat them all, one, two, three!","tr":"Hepsini ye, bir, iki, üç!"},{"s":"Kids","en":"Eat them all, one, two, three!","tr":"Hepsini ye, bir, iki, üç!"}]}],"reading":{"title":"My favourite fruit","paras":[{"en":"Hi! I'm Deniz. I love fruit! My favourite fruit is a banana. It is yellow and sweet. I eat an apple every day. Vegetables are good for me too. I like carrots and tomatoes. I don't like broccoli but I eat a little. Yum! Fruit and vegetables make me strong and they taste good!","tr":"Merhaba! Ben Deniz. Meyveyi çok seviyorum! En sevdiğim meyve muz. Sarı ve tatlı. Her gün bir elma yerim. Sebzeler de bana iyi gelir. Havuç ve domatesi severim. Brokoliyi sevmem ama biraz yerim. Nam! Meyve ve sebzeler beni güçlü yapar ve çok lezzetliler!"}]},"vocab":[{"w":"apple","ipa":"/ˈæpl/","pos":"🍎","tr":"elma","ex":"I eat an apple every day.","exTr":"Her gün bir elma yerim."},{"w":"banana","ipa":"/bəˈnɑːnə/","pos":"🍌","tr":"muz","ex":"I like bananas.","exTr":"Muzu severim."},{"w":"orange","ipa":"/ˈɒrɪndʒ/","pos":"🍊","tr":"portakal","ex":"The orange is sweet.","exTr":"Portakal tatlıdır."},{"w":"carrot","ipa":"/ˈkærət/","pos":"🥕","tr":"havuç","ex":"I like carrots.","exTr":"Havuçları severim."},{"w":"tomato","ipa":"/təˈmɑːtəʊ/","pos":"🍅","tr":"domates","ex":"Tomatoes are red.","exTr":"Domatesler kırmızıdır."},{"w":"broccoli","ipa":"/ˈbrɒkəli/","pos":"🥦","tr":"brokoli","ex":"I don't like broccoli.","exTr":"Brokoliyi sevmiyorum."},{"w":"pear","ipa":"/peə/","pos":"🍐","tr":"armut","ex":"Here are green pears.","exTr":"İşte yeşil armutlar."},{"w":"vegetable","ipa":"/ˈvedʒtəbl/","pos":"🥬","tr":"sebze","ex":"Vegetables are good for me.","exTr":"Sebzeler bana iyi gelir."}],"chunks":[{"en":"I like…","tr":"… severim."},{"en":"I don't like…","tr":"… sevmiyorum."},{"en":"Can I have…?","tr":"… alabilir miyim?"},{"en":"Here you are.","tr":"Buyur."}],"grammar":{"point":"I like / I don't like","tr":"Bir şeyi sevdiğini söylemek için 'I like' kullanılır. Sevmediğini söylemek için 'I don't like' kullanılır ve anlamı 'sevmiyorum' olur.","examples":["I like apples.","I don't like pears.","We like oranges.","I don't like broccoli."]},"questions":[{"q":"What fruit does Deniz like best?","a":"A banana."},{"q":"Does Ece like broccoli?","a":"No, she doesn't."},{"q":"How many apples does Ali want?","a":"Two apples."}],"quiz":[{"q":"🍌 is a ___.","o":["banana","pear","carrot"],"a":0,"why":""},{"q":"I ___ broccoli. (sevmiyorum)","o":["like","don't like","likes"],"a":1,"why":"'don't like' sevmemek anlamına gelir."},{"q":"Which one is a vegetable?","o":["orange","pear","tomato"],"a":2,"why":""},{"q":"Can I have two ___? (🍎)","o":["apples","pears","oranges"],"a":0,"why":""}],"drills":[{"type":"Yerine koyma","prompt":"I like apples.","cue":"bananas","answer":"I like bananas."},{"type":"Dönüştürme","prompt":"I like carrots.","cue":"→ 'I don't like…'","answer":"I don't like carrots."},{"type":"Soru yap","prompt":"I like tomatoes.","cue":"Ask: 'Do you like…?'","answer":"Do you like tomatoes?"}],"sounds":[{"focus":"/ɒ/","tr":"Ağzını biraz yuvarla ve açık tut: 'orange', 'hot'. Türkçedeki 'o' sesine benzer ama dudaklar daha az yuvarlanır. 'pet' ve 'hut' ile karıştırma.","pairs":["pot / pet","hot / hut"]}],"mission":{"brief":"Oyun: Pazarda ne aldığını ve neyi sevdiğini İngilizce anlat. Claude, arkadaşın Leo olacak ve senin favori meyveni öğrenmeye çalışacak.","persona":"Leo, a friendly 7-year-old who loves fruit. Uses very short sentences and lots of encouragement. Asks one question at a time. Hidden fact: his secret favourite is strawberries, which he only mentions if the learner asks about fruit he would like to grow or buy.","goal":"Leo'nun gizli favori meyvesini üç soruda bul.","opener":"Hi! Do you like fruit?"}},"KS1-012":{"objectives":["Yiyecek adlarını söylemek","'Can I have…?' kalıbını kullanmak","'Please' ve 'Thank you' ile nazik olmak"],"dialogues":[{"title":"Breakfast time","setting":"Sabah kahvaltısında Mina babasıyla konuşuyor.","lines":[{"s":"Dad","en":"Good morning, Mina! Do you want bread?","tr":"Günaydın, Mina! Ekmek ister misin?"},{"s":"Mina","en":"Yes, please. Can I have jam, too?","tr":"Evet lütfen. Reçel de alabilir miyim?"},{"s":"Dad","en":"Of course. Here is your jam.","tr":"Tabii. İşte reçelin."},{"s":"Mina","en":"Thank you, Dad! I love eggs, too.","tr":"Teşekkürler baba! Yumurtayı da çok severim."},{"s":"Dad","en":"Here are two eggs. Enjoy!","tr":"İşte iki yumurta. Afiyet olsun!"},{"s":"Mina","en":"Yummy! My favourite breakfast!","tr":"Nam! En sevdiğim kahvaltı!"}]},{"title":"Lunch at school","setting":"Okul kantininde Ali öğle yemeği alıyor.","lines":[{"s":"Cook","en":"What do you want for lunch?","tr":"Öğle yemeğinde ne istersin?"},{"s":"Ali","en":"Can I have soup, please?","tr":"Çorba alabilir miyim, lütfen?"},{"s":"Cook","en":"Yes! Here is your soup.","tr":"Tabii! İşte çorban."},{"s":"Ali","en":"Can I have some rice too?","tr":"Biraz pilav da alabilir miyim?"},{"s":"Cook","en":"Sure. Anything to drink?","tr":"Tabii. İçecek bir şey ister misin?"},{"s":"Ali","en":"Water, please. Thank you!","tr":"Su, lütfen. Teşekkürler!"},{"s":"Cook","en":"You are welcome, Ali.","tr":"Rica ederim, Ali."}]},{"title":"Yummy song","setting":"Ritimle tekrar et ve nazik ol!","lines":[{"s":"Teacher","en":"Pizza, pasta, yummy, yummy!","tr":"Pizza, makarna, nam, nam!"},{"s":"Kids","en":"Pizza, pasta, yummy, yummy!","tr":"Pizza, makarna, nam, nam!"},{"s":"Teacher","en":"Soup and bread, yummy, yummy!","tr":"Çorba ve ekmek, nam, nam!"},{"s":"Kids","en":"Soup and bread, yummy, yummy!","tr":"Çorba ve ekmek, nam, nam!"},{"s":"Teacher","en":"Please, please, thank you, thank you!","tr":"Lütfen, lütfen, teşekkürler, teşekkürler!"},{"s":"Kids","en":"Please, please, thank you, thank you!","tr":"Lütfen, lütfen, teşekkürler, teşekkürler!"}]}],"reading":{"title":"My favourite food","paras":[{"en":"Hi! I'm Ece. My favourite food is pasta. I eat it with cheese. For breakfast I like bread and eggs. At lunch I like warm soup. Soup is yummy! I drink water with my meals. At dinner I always say please and thank you. My mum says I am a good girl!","tr":"Merhaba! Ben Ece. En sevdiğim yemek makarna. Yanında peynirle yerim. Kahvaltıda ekmek ve yumurta severim. Öğle yemeğinde sıcak çorba severim. Çorba çok lezzetli! Yemeklerimin yanında su içerim. Akşam yemeğinde her zaman lütfen ve teşekkürler derim. Annem iyi bir kız olduğumu söyler!"}]},"vocab":[{"w":"bread","ipa":"/bred/","pos":"🍞","tr":"ekmek","ex":"Can I have some bread?","exTr":"Biraz ekmek alabilir miyim?"},{"w":"egg","ipa":"/eɡ/","pos":"🥚","tr":"yumurta","ex":"I eat an egg.","exTr":"Bir yumurta yerim."},{"w":"soup","ipa":"/suːp/","pos":"🥣","tr":"çorba","ex":"The soup is hot.","exTr":"Çorba sıcak."},{"w":"rice","ipa":"/raɪs/","pos":"🍚","tr":"pilav","ex":"I like rice.","exTr":"Pilavı severim."},{"w":"pasta","ipa":"/ˈpæstə/","pos":"🍝","tr":"makarna","ex":"My favourite food is pasta.","exTr":"En sevdiğim yemek makarna."},{"w":"cheese","ipa":"/tʃiːz/","pos":"🧀","tr":"peynir","ex":"I eat it with cheese.","exTr":"Peynirle yerim."},{"w":"water","ipa":"/ˈwɔːtə/","pos":"💧","tr":"su","ex":"Water, please.","exTr":"Su, lütfen."},{"w":"pizza","ipa":"/ˈpiːtsə/","pos":"🍕","tr":"pizza","ex":"Pizza is yummy.","exTr":"Pizza çok lezzetli."}],"chunks":[{"en":"Can I have…?","tr":"… alabilir miyim?"},{"en":"Here is your…","tr":"İşte senin …"},{"en":"You are welcome.","tr":"Rica ederim."},{"en":"Yummy!","tr":"Nam!"}],"grammar":{"point":"Can I have…?","tr":"Bir şey istediğinde nazikçe 'Can I have…?' diye sorarsın. Bu kalıp Türkçedeki 'alabilir miyim?' anlamına gelir.","examples":["Can I have some bread?","Can I have water, please?","Can I have an egg?","Can I have soup?"]},"questions":[{"q":"What else does Mina ask for?","a":"Jam."},{"q":"What is Ece's favourite food?","a":"Pasta."},{"q":"What does Ali want to drink?","a":"Water."}],"quiz":[{"q":"🍝 is ___.","o":["soup","pasta","egg"],"a":1,"why":""},{"q":"Can I have an ___? (🥚)","o":["egg","bread","soup"],"a":0,"why":"'an' sesli harfle başlayan kelimeden önce gelir."},{"q":"Someone gives you soup. You say:","o":["Hello","Goodbye","Thank you"],"a":2,"why":""},{"q":"💧 is ___.","o":["bread","water","pizza"],"a":1,"why":""}],"drills":[{"type":"Yerine koyma","prompt":"Can I have some bread?","cue":"water","answer":"Can I have some water?"},{"type":"Dönüştürme","prompt":"I like pasta.","cue":"→ 'I don't like…'","answer":"I don't like pasta."},{"type":"Genişletme","prompt":"I like soup.","cue":"add 'hot'","answer":"I like hot soup."}],"sounds":[{"focus":"/iː/","tr":"'eat' sesi uzun ve gergin söylenir, dudaklar yanlara çekilir. 'it' ise kısa ve gevşek söylenir. Uzun ve kısa 'i' farklı kelimeler yapar.","pairs":["eat / it","sheep / ship"]}],"mission":{"brief":"Oyun: En sevdiğin yemeği İngilizce anlat ve bir şey istemek için 'Can I have…?' diye sor. Claude, arkadaşın Leo olacak ve yemek masasında sana sorular soracak.","persona":"Leo, a friendly 7-year-old sitting at dinner with you. Uses very short sentences and lots of encouragement. Asks one question at a time. Hidden fact: his secret treat is ice cream, which he only mentions if the learner asks about sweets or desserts.","goal":"Leo'nun gizli tatlısını üç soruda bul.","opener":"Hi! What is your favourite food?"}},"KS1-013":{"objectives":["Hava durumunu İngilizce söylemek","'It's…' kalıbını kullanmak","Hava kelimelerini bir şarkı ritmiyle tekrar etmek"],"dialogues":[{"title":"Look outside!","setting":"Sabah, Elif pencereden dışarı bakıyor ve arkadaşı Ali'ye hava durumunu söylüyor.","lines":[{"s":"Elif","en":"Look outside, Ali! It's sunny today.","tr":"Dışarı bak Ali! Bugün hava güneşli."},{"s":"Ali","en":"Yay! Let's play in the garden.","tr":"Yaşasın! Bahçede oynayalım."},{"s":"Elif","en":"Yes! Come on, let's go!","tr":"Evet! Hadi, gidelim!"},{"s":"Ali","en":"Wait! Where is my hat?","tr":"Dur! Şapkam nerede?"},{"s":"Elif","en":"It's on your head!","tr":"Kafanda!"},{"s":"Ali","en":"Oh! Silly me!","tr":"Ah! Ne kadar dalgınım!"}]},{"title":"Rainy morning","setting":"Yağmurlu bir sabah, Defne okula gitmeye hazırlanıyor ve annesi hava durumunu soruyor.","lines":[{"s":"Mum","en":"Good morning, Defne! What's the weather like?","tr":"Günaydın Defne! Hava nasıl?"},{"s":"Defne","en":"It's rainy! Look at the rain.","tr":"Yağmurlu! Yağmura bak."},{"s":"Mum","en":"Yes, it's rainy today. Take your umbrella.","tr":"Evet, bugün yağmurlu. Şemsiyeni al."},{"s":"Defne","en":"My umbrella is red! I love it.","tr":"Şemsiyem kırmızı! Onu çok seviyorum."},{"s":"Mum","en":"Good! And a warm coat, too.","tr":"Güzel! Bir de sıcak bir mont al."},{"s":"Defne","en":"Thank you, Mum! Bye!","tr":"Teşekkürler anne! Hoşça kal!"}]},{"title":"Weather song","setting":"Ritimle tekrar et, alkışla!","lines":[{"s":"Teacher","en":"Sunny, rainy, cloudy, windy!","tr":"Güneşli, yağmurlu, bulutlu, rüzgarlı!"},{"s":"Kids","en":"Sunny, rainy, cloudy, windy!","tr":"Güneşli, yağmurlu, bulutlu, rüzgarlı!"},{"s":"Teacher","en":"Snowy, cold, hot, what is it?","tr":"Karlı, soğuk, sıcak, hangisi bu?"},{"s":"Kids","en":"It's hot! It's hot today!","tr":"Sıcak! Bugün sıcak!"},{"s":"Teacher","en":"Good! Let's clap!","tr":"Harika! Hadi alkışlayalım!"}]}],"reading":{"title":"Elif's weather diary","paras":[{"en":"Hi! I'm Elif. Today it's sunny and warm. I can play outside with my friends. Yesterday it was rainy. I stayed inside and drew a rainbow. Tomorrow it's going to be windy, I think. I like all kinds of weather! What is the weather like today? My favourite weather is sunny!","tr":"Merhaba! Ben Elif. Bugün hava güneşli ve sıcak. Dışarıda arkadaşlarımla oynayabilirim. Dün hava yağmurluydu. İçeride kaldım ve bir gökkuşağı çizdim. Yarın sanırım rüzgarlı olacak. Her hava durumunu severim! Bugün hava nasıl? En sevdiğim hava güneşli!"}]},"vocab":[{"w":"sunny","ipa":"/ˈsʌni/","pos":"☀️","tr":"güneşli","ex":"It's sunny today.","exTr":"Bugün hava güneşli."},{"w":"rainy","ipa":"/ˈreɪni/","pos":"🌧️","tr":"yağmurlu","ex":"It's rainy in the morning.","exTr":"Sabahları hava yağmurlu."},{"w":"cloudy","ipa":"/ˈklaʊdi/","pos":"☁️","tr":"bulutlu","ex":"The sky is cloudy.","exTr":"Gökyüzü bulutlu."},{"w":"windy","ipa":"/ˈwɪndi/","pos":"🌬️","tr":"rüzgarlı","ex":"It's windy and cloudy.","exTr":"Hava rüzgarlı ve bulutlu."},{"w":"snowy","ipa":"/ˈsnəʊi/","pos":"⛄","tr":"karlı","ex":"It's snowy in the mountains.","exTr":"Dağlarda hava karlı."},{"w":"cold","ipa":"/kəʊld/","pos":"🥶","tr":"soğuk","ex":"It's cold. Wear a coat.","exTr":"Hava soğuk. Bir mont giy."},{"w":"hot","ipa":"/hɒt/","pos":"🥵","tr":"sıcak","ex":"It's hot in the park.","exTr":"Parkta hava sıcak."},{"w":"umbrella","ipa":"/ʌmˈbrelə/","pos":"☂️","tr":"şemsiye","ex":"Take your umbrella.","exTr":"Şemsiyeni al."}],"chunks":[{"en":"What's the weather like?","tr":"Hava nasıl?"},{"en":"Look outside!","tr":"Dışarı bak!"},{"en":"Take your umbrella.","tr":"Şemsiyeni al."},{"en":"Let's go out!","tr":"Hadi dışarı çıkalım!"}],"grammar":{"point":"It's + weather","tr":"Hava durumunu anlatmak için 'It's' (It is) ve bir hava kelimesi kullanılır. Türkçedeki 'Hava güneşli' cümlesi gibidir.","examples":["It's sunny today.","It's rainy.","It's cold and windy.","It's hot in the park."]},"questions":[{"q":"What is the weather today in Elif's story?","a":"It's sunny and warm."},{"q":"What was the weather yesterday?","a":"It was rainy."},{"q":"What did Elif draw?","a":"A rainbow."}],"quiz":[{"q":"Which word is ☀️?","o":["rainy","sunny","cold"],"a":1,"why":""},{"q":"It's ___. Take your umbrella! ☂️","o":["hot","snowy","rainy"],"a":2,"why":"Yağmurlu havada şemsiye alınır."},{"q":"Which word means 'rüzgarlı'?","o":["windy","snowy","cloudy"],"a":0,"why":""},{"q":"Which word means 'bulutlu'?","o":["snowy","cloudy","hot"],"a":1,"why":""}],"drills":[{"type":"Yerine koyma","prompt":"It's sunny today.","cue":"rainy","answer":"It's rainy today."},{"type":"Soru yap","prompt":"It's cold today.","cue":"make a question","answer":"Is it cold today?"},{"type":"Genişletme","prompt":"It's windy.","cue":"add 'and cloudy'","answer":"It's windy and cloudy."}],"sounds":[{"focus":"/w/","tr":"Dudaklarını büyük bir 'u' gibi yuvarla ve hemen aç: 'wind', 'windy', 'water'. Alt dudağını üst dişlerine değdirme, o zaman 'v' olur.","pairs":["wet / vet","west / vest"]}],"mission":{"brief":"Oyun: Bugünkü havayı arkadaşına İngilizce anlat. Claude, arkadaşın Mia olacak ve sana hava hakkında sorular soracak.","persona":"Mia, a cheerful 7-year-old who loves talking about weather. Uses very short, simple sentences and lots of encouragement. Asks one question at a time. Hidden fact: Mia's favourite weather is snowy, and she wants to build a snowman this weekend; she only says this if the learner asks what her favourite weather is.","goal":"Hava durumunu üç kelimeyle ve 'It's…' kalıbıyla anlat.","opener":"Hi! I'm Mia. What's the weather like today?"}},"KS1-014":{"objectives":["Haftanın günlerini İngilizce söylemek","'Today is…' kalıbını kullanmak","Gün adlarını bir şarkı ritmiyle tekrar etmek"],"dialogues":[{"title":"What day is it?","setting":"Pazartesi sabahı, Can annesiyle takvime bakıyor.","lines":[{"s":"Mum","en":"Good morning, Can! What day is it today?","tr":"Günaydın Can! Bugün hangi gün?"},{"s":"Can","en":"Today is Monday! I go to school.","tr":"Bugün pazartesi! Okula gidiyorum."},{"s":"Mum","en":"Yes! Tomorrow is Tuesday.","tr":"Evet! Yarın salı."},{"s":"Can","en":"Yay! Is Friday my favourite day?","tr":"Yaşasın! Cuma benim en sevdiğim gün mü?"},{"s":"Mum","en":"Yes! Friday is fun.","tr":"Evet! Cuma çok eğlenceli."},{"s":"Can","en":"Okay! Let's go to school!","tr":"Tamam! Hadi okula gidelim!"}]},{"title":"Weekend plans","setting":"Cuma günü, Defne arkadaşı Ali'yle hafta sonu planı yapıyor.","lines":[{"s":"Defne","en":"Ali, what day is it today?","tr":"Ali, bugün hangi gün?"},{"s":"Ali","en":"It's Friday! Yay!","tr":"Cuma! Yaşasın!"},{"s":"Defne","en":"Let's play in the park on Saturday.","tr":"Cumartesi parkta oynayalım."},{"s":"Ali","en":"Great! And on Sunday?","tr":"Harika! Peki pazar günü?"},{"s":"Defne","en":"On Sunday, let's have a picnic!","tr":"Pazar günü piknik yapalım!"},{"s":"Ali","en":"Yes! I love the weekend!","tr":"Evet! Hafta sonunu çok seviyorum!"}]},{"title":"Days song","setting":"Ritimle tekrar et, alkışla!","lines":[{"s":"Teacher","en":"Monday, Tuesday, Wednesday, Thursday!","tr":"Pazartesi, salı, çarşamba, perşembe!"},{"s":"Kids","en":"Monday, Tuesday, Wednesday, Thursday!","tr":"Pazartesi, salı, çarşamba, perşembe!"},{"s":"Teacher","en":"Friday, Saturday, Sunday too!","tr":"Cuma, cumartesi, pazar da!"},{"s":"Kids","en":"Friday, Saturday, Sunday too!","tr":"Cuma, cumartesi, pazar da!"},{"s":"Teacher","en":"Seven days in a week!","tr":"Bir haftada yedi gün!"}]}],"reading":{"title":"Ali's week","paras":[{"en":"Hi! I'm Ali. I go to school on Monday, Tuesday, Wednesday, Thursday and Friday. On Saturday I play with my friends. On Sunday I help Mum in the garden. I love the weekend! My week has seven days. Today is Friday, so tomorrow is Saturday. I love Fridays too! Which day is your favourite?","tr":"Merhaba! Ben Ali. Pazartesi, salı, çarşamba, perşembe ve cuma günleri okula giderim. Cumartesi günü arkadaşlarımla oynarım. Pazar günü bahçede annemin işine yardım ederim. Hafta sonunu çok severim! Haftada yedi gün var. Bugün cuma, bu yüzden yarın cumartesi. Cumaları da severim! Senin en sevdiğin gün hangisi?"}]},"vocab":[{"w":"Monday","ipa":"/ˈmʌndeɪ/","pos":"1️⃣","tr":"pazartesi","ex":"Today is Monday.","exTr":"Bugün pazartesi."},{"w":"Friday","ipa":"/ˈfraɪdeɪ/","pos":"🎉","tr":"cuma","ex":"Friday is fun!","exTr":"Cuma çok eğlenceli!"},{"w":"Sunday","ipa":"/ˈsʌndeɪ/","pos":"☀️","tr":"pazar","ex":"We have a picnic on Sunday.","exTr":"Pazar günü piknik yaparız."},{"w":"week","ipa":"/wiːk/","pos":"📅","tr":"hafta","ex":"There are seven days in a week.","exTr":"Bir haftada yedi gün vardır."},{"w":"today","ipa":"/təˈdeɪ/","pos":"📆","tr":"bugün","ex":"Is today Friday?","exTr":"Bugün cuma mı?"},{"w":"tomorrow","ipa":"/təˈmɒrəʊ/","pos":"⏭️","tr":"yarın","ex":"Tomorrow is Tuesday.","exTr":"Yarın salı."},{"w":"school","ipa":"/skuːl/","pos":"🏫","tr":"okul","ex":"I go to school.","exTr":"Okula giderim."},{"w":"weekend","ipa":"/ˌwiːkˈend/","pos":"🎈","tr":"hafta sonu","ex":"I love the weekend!","exTr":"Hafta sonunu çok severim!"}],"chunks":[{"en":"What day is it today?","tr":"Bugün hangi gün?"},{"en":"Today is…","tr":"Bugün…"},{"en":"Yay! It's the weekend!","tr":"Yaşasın! Hafta sonu!"},{"en":"See you on Monday!","tr":"Pazartesi görüşürüz!"}],"grammar":{"point":"Today is…","tr":"Bugünün gününü söylemek için 'Today is' kalıbını kullanırız. Gün adları İngilizcede her zaman büyük harfle başlar: Monday, Friday.","examples":["Today is Monday.","Tomorrow is Tuesday.","We play on Saturday.","Is today Friday?"]},"questions":[{"q":"What day is it today in Ali's story?","a":"It's Friday."},{"q":"What does Ali do on Saturday?","a":"He plays with his friends."},{"q":"How many days are there in a week?","a":"Seven."}],"quiz":[{"q":"Tomorrow is ___. (Today is Monday.)","o":["Tuesday","Friday","Sunday"],"a":0,"why":"Pazartesiden sonra salı gelir."},{"q":"I go to ___ on Monday. 🏫","o":["weekend","week","school"],"a":2,"why":""},{"q":"Which day is 🎉?","o":["Thursday","Friday","Sunday"],"a":1,"why":""},{"q":"How many days are in a week?","o":["seven","five","nine"],"a":0,"why":""}],"drills":[{"type":"Yerine koyma","prompt":"Today is Monday.","cue":"Friday","answer":"Today is Friday."},{"type":"Soru yap","prompt":"Today is Monday.","cue":"make a question","answer":"Is today Monday?"},{"type":"Genişletme","prompt":"We play on Saturday.","cue":"add 'and Sunday'","answer":"We play on Saturday and Sunday."}],"sounds":[{"focus":"/θ/","tr":"Dilinin ucunu üst ve alt dişlerinin arasına koy, hafifçe üfle: 'Thursday', 'think'. 'Tuesday' gibi 't' ya da 's' sesiyle okuma.","pairs":["think / sink","three / tree"]}],"mission":{"brief":"Oyun: Bu hafta hangi günlerde okula gittiğini ve hafta sonu ne yaptığını İngilizce anlat. Claude, arkadaşın Mia olacak ve sana günleri soracak.","persona":"Mia, a cheerful 7-year-old who loves her school week. Uses very short, simple sentences and lots of encouragement. Asks one question at a time. Hidden fact: Mia's favourite day is Thursday because she has art class then; she only says why if the learner asks which day she likes best.","goal":"Üç gün adını İngilizce söyle ve 'Today is…' kalıbını bir kez kullan.","opener":"Hi! I'm Mia. What day is it today?"}},"KS1-015":{"objectives":["Evdeki odaları ve eşyaları söylemek","'There is / There are' kalıbını kullanmak","Ev kelimelerini bir şarkı ritmiyle tekrar etmek"],"dialogues":[{"title":"Come into my house!","setting":"Elif, arkadaşı Mert'i evine davet ediyor.","lines":[{"s":"Elif","en":"Welcome to my house, Mert!","tr":"Evime hoş geldin Mert!"},{"s":"Mert","en":"Wow! It's big! Where is the kitchen?","tr":"Vay! Çok büyük! Mutfak nerede?"},{"s":"Elif","en":"There it is! Look, there is a window.","tr":"İşte orada! Bak, bir pencere var."},{"s":"Mert","en":"Nice! And there is a table, too.","tr":"Güzel! Bir de masa var."},{"s":"Elif","en":"Yes, we eat here together.","tr":"Evet, burada birlikte yemek yeriz."},{"s":"Mert","en":"I love your house, Elif!","tr":"Senin evini çok sevdim Elif!"}]},{"title":"Where is the bathroom?","setting":"Bahçede, Can annesine evde banyonun nerede olduğunu anlatıyor.","lines":[{"s":"Mum","en":"Can, where is the bathroom?","tr":"Can, banyo nerede?"},{"s":"Can","en":"There is a door near the living room. Look!","tr":"Oturma odasının yanında bir kapı var. Bak!"},{"s":"Mum","en":"Oh, thank you! Is the garden big too?","tr":"Oh, teşekkürler! Bahçe de büyük mü?"},{"s":"Can","en":"Yes! There is a big tree in the garden.","tr":"Evet! Bahçede büyük bir ağaç var."},{"s":"Mum","en":"Nice! Let's go and play.","tr":"Güzel! Gidip oynayalım."},{"s":"Can","en":"Yay! Come on, Mum!","tr":"Yaşasın! Hadi anne!"}]},{"title":"My house song","setting":"Ritimle tekrar et, alkışla!","lines":[{"s":"Teacher","en":"Kitchen, bathroom, living room too!","tr":"Mutfak, banyo, oturma odası da!"},{"s":"Kids","en":"Kitchen, bathroom, living room too!","tr":"Mutfak, banyo, oturma odası da!"},{"s":"Teacher","en":"Door and window, table and garden!","tr":"Kapı ve pencere, masa ve bahçe!"},{"s":"Kids","en":"Door and window, table and garden!","tr":"Kapı ve pencere, masa ve bahçe!"},{"s":"Teacher","en":"My house is home, hooray!","tr":"Evim bir yuva, yaşasın!"}]}],"reading":{"title":"Elif's house","paras":[{"en":"Hi! This is my house. It is small and blue. There is a kitchen with a yellow table. There is a big window in the living room. The garden has a tree and a red bike. I love my house! Mum says it is the best house in the world! Come and see!","tr":"Merhaba! Bu benim evim. Küçük ve mavi. Sarı bir masanın olduğu bir mutfak var. Oturma odasında büyük bir pencere var. Bahçede bir ağaç ve kırmızı bir bisiklet var. Evimi çok seviyorum! Annem, dünyanın en güzel evi olduğunu söylüyor! Gel ve gör!"}]},"vocab":[{"w":"house","ipa":"/haʊs/","pos":"🏠","tr":"ev","ex":"This is my house.","exTr":"Bu benim evim."},{"w":"kitchen","ipa":"/ˈkɪtʃɪn/","pos":"🍳","tr":"mutfak","ex":"We cook in the kitchen.","exTr":"Mutfakta yemek pişiririz."},{"w":"garden","ipa":"/ˈɡɑːdn/","pos":"🌳","tr":"bahçe","ex":"There is a tree in the garden.","exTr":"Bahçede bir ağaç var."},{"w":"living room","ipa":"/ˈlɪvɪŋ ruːm/","pos":"🛋️","tr":"oturma odası","ex":"There is a window in the living room.","exTr":"Oturma odasında bir pencere var."},{"w":"door","ipa":"/dɔː/","pos":"🚪","tr":"kapı","ex":"There is a door near the living room.","exTr":"Oturma odasının yanında bir kapı var."},{"w":"window","ipa":"/ˈwɪndəʊ/","pos":"🪟","tr":"pencere","ex":"The window is big.","exTr":"Pencere büyük."},{"w":"table","ipa":"/ˈteɪbl/","pos":"🪑","tr":"masa","ex":"The table is yellow.","exTr":"Masa sarı."},{"w":"bathroom","ipa":"/ˈbɑːθruːm/","pos":"🛁","tr":"banyo","ex":"Where is the bathroom?","exTr":"Banyo nerede?"}],"chunks":[{"en":"Welcome to my house!","tr":"Evime hoş geldin!"},{"en":"Where is the…?","tr":"… nerede?"},{"en":"There is a…","tr":"… var."},{"en":"Let's go and play!","tr":"Gidip oynayalım!"}],"grammar":{"point":"There is / There are","tr":"Bir şeyin olduğunu söylemek için tek şey varsa 'There is', birden fazla şey varsa 'There are' kullanılır. Türkçedeki 'var' kelimesi gibidir.","examples":["There is a kitchen.","There is a big window.","There is a tree in the garden.","There are two chairs."]},"questions":[{"q":"What colour is the table in Elif's house?","a":"It's yellow."},{"q":"What is in the garden?","a":"A tree and a red bike."},{"q":"What does Mum say about the house?","a":"It is the best house in the world."}],"quiz":[{"q":"Which room is 🛁?","o":["kitchen","bathroom","garden"],"a":1,"why":""},{"q":"There ___ a window.","o":["is","are","have"],"a":0,"why":"Tek bir şey olduğunda 'is' kullanılır."},{"q":"Which word is 🪑 in English?","o":["window","door","table"],"a":2,"why":""},{"q":"Where do we cook? 🍳","o":["kitchen","bathroom","garden"],"a":0,"why":""}],"drills":[{"type":"Yerine koyma","prompt":"There is a window.","cue":"door","answer":"There is a door."},{"type":"Genişletme","prompt":"There is a table.","cue":"add 'in the kitchen'","answer":"There is a table in the kitchen."},{"type":"Soru yap","prompt":"There is a tree in the garden.","cue":"make a question with 'Is there'","answer":"Is there a tree in the garden?"}],"sounds":[{"focus":"/ɪ/","tr":"Kısa 'i' sesi çıkar, dudaklarını germe: 'kitchen', 'big', 'window'. Uzun 'iii' gibi uzatırsan 'bee' gibi duyulur.","pairs":["big / bee","ship / sheep"]}],"mission":{"brief":"Oyun: Evini İngilizce tarif et ve evde neyin nerede olduğunu söyle. Claude, arkadaşın Ada olacak ve evini merak edip sana sorular soracak.","persona":"Ada, a curious 7-year-old who is drawing a picture of a friend's house. Uses very short, simple sentences and lots of encouragement. Asks one question at a time. Hidden fact: Ada's house has a secret cat named Pamuk who sleeps in the kitchen; she only mentions him if the learner asks what is in the kitchen.","goal":"Evindeki üç oda veya eşyayı 'There is…' kalıbıyla anlat.","opener":"Hi! I'm Ada. I'm drawing a house. Can you tell me about your house?"}},"KS1-016":{"objectives":["Yatak odasındaki eşyaları söylemek","'my' kelimesiyle eşyaların kime ait olduğunu anlatmak","Yatak odası şarkısını ritimle tekrar etmek"],"dialogues":[{"title":"Tidy up!","setting":"Akşam, annesi Ece'ye odasını toplamasını hatırlatıyor.","lines":[{"s":"Mum","en":"Ece, look at your bedroom!","tr":"Ece, odana bak!"},{"s":"Ece","en":"Oh! My toys are on the floor.","tr":"Ah! Oyuncaklarım yerde."},{"s":"Mum","en":"Let's tidy up together.","tr":"Gel birlikte toplayalım."},{"s":"Ece","en":"Okay! This is my favourite toy!","tr":"Tamam! Bu benim en sevdiğim oyuncak!"},{"s":"Mum","en":"Great! Put the book on the bed.","tr":"Harika! Kitabı yatağın üstüne koy."},{"s":"Ece","en":"Yes! My room is clean now.","tr":"Evet! Odam şimdi temiz."}]},{"title":"Where is my shoe?","setting":"Ece sabah okula gitmeden önce ayakkabısını arıyor.","lines":[{"s":"Ece","en":"Dad, where is my shoe?","tr":"Baba, ayakkabım nerede?"},{"s":"Dad","en":"Look under the bed!","tr":"Yatağın altına bak!"},{"s":"Ece","en":"Oh, there it is! Thanks, Dad.","tr":"Ah, işte burada! Teşekkürler baba."},{"s":"Dad","en":"Look at the clock. It's eight o'clock!","tr":"Saate bak. Saat sekiz oldu!"},{"s":"Ece","en":"Oh no! Quick, let's go!","tr":"Ah olamaz! Çabuk, gidelim!"}]},{"title":"My room song","setting":"Ritimle tekrar et, alkışla!","lines":[{"s":"Teacher","en":"Bed, lamp, book and toy!","tr":"Yatak, lamba, kitap ve oyuncak!"},{"s":"Kids","en":"Bed, lamp, book and toy!","tr":"Yatak, lamba, kitap ve oyuncak!"},{"s":"Teacher","en":"Clock, box and shoe too!","tr":"Saat, kutu ve ayakkabı da!"},{"s":"Kids","en":"Clock, box and shoe too!","tr":"Saat, kutu ve ayakkabı da!"},{"s":"Teacher","en":"My bedroom, my room, I love you!","tr":"Yatak odam, benim odam, seni seviyorum!"}]}],"reading":{"title":"Ece's bedroom","paras":[{"en":"Hi! This is my bedroom. My bed is blue, and my lamp is yellow. My books are on the table, and my toys are in a big box. There is a clock on the wall. My shoe is under the bed! I like my room because it is cosy. Do you have a bedroom too?","tr":"Merhaba! Bu benim yatak odam. Yatağım mavi, lambam ise sarı. Kitaplarım masanın üstünde, oyuncaklarım ise büyük bir kutuda. Duvarda bir saat var. Ayakkabım yatağın altında! Odamı severim, çünkü sıcacık ve rahat. Senin de bir yatak odan var mı?"}]},"vocab":[{"w":"bedroom","ipa":"/ˈbedruːm/","pos":"🛌","tr":"yatak odası","ex":"This is my bedroom.","exTr":"Bu benim yatak odam."},{"w":"bed","ipa":"/bed/","pos":"🛏️","tr":"yatak","ex":"My bed is blue.","exTr":"Yatağım mavi."},{"w":"lamp","ipa":"/læmp/","pos":"💡","tr":"lamba","ex":"The lamp is yellow.","exTr":"Lamba sarı."},{"w":"book","ipa":"/bʊk/","pos":"📚","tr":"kitap","ex":"I read a book.","exTr":"Bir kitap okuyorum."},{"w":"toy","ipa":"/tɔɪ/","pos":"🧸","tr":"oyuncak","ex":"This is my favourite toy.","exTr":"Bu benim en sevdiğim oyuncak."},{"w":"clock","ipa":"/klɒk/","pos":"⏰","tr":"saat","ex":"The clock is on the wall.","exTr":"Saat duvarda."},{"w":"box","ipa":"/bɒks/","pos":"📦","tr":"kutu","ex":"My toys are in a box.","exTr":"Oyuncaklarım bir kutuda."},{"w":"shoe","ipa":"/ʃuː/","pos":"👟","tr":"ayakkabı","ex":"My shoe is under the bed.","exTr":"Ayakkabım yatağın altında."}],"chunks":[{"en":"Tidy up!","tr":"Toparla!"},{"en":"Look under the bed!","tr":"Yatağın altına bak!"},{"en":"Let's tidy up together.","tr":"Birlikte toplayalım."},{"en":"My room is clean now.","tr":"Odam şimdi temiz."}],"grammar":{"point":"my","tr":"Bir şeyin benim olduğunu söylemek için 'my' kelimesini kullanırız. 'my' her zaman isimden önce gelir. Türkçedeki 'benim' kelimesi gibidir.","examples":["This is my bed.","My bed is blue.","My toys are on the bed.","My room is small and nice."]},"questions":[{"q":"What colour is Ece's bed?","a":"It's blue."},{"q":"Where are Ece's toys?","a":"In a big box."},{"q":"What time is it in the dialogue?","a":"It's eight o'clock."}],"quiz":[{"q":"🛏️ is a…","o":["bed","box","clock"],"a":0,"why":""},{"q":"Ece says: '___ bed is blue.'","o":["Your","My","Her"],"a":1,"why":"Kendi yatağından söz ediyor: 'my' benim demek."},{"q":"⏰ means…","o":["lamp","clock","shoe"],"a":1,"why":""},{"q":"The toys are in the ___.","o":["bed","lamp","box"],"a":2,"why":""}],"drills":[{"type":"Yerine koyma","prompt":"This is my bed.","cue":"book","answer":"This is my book."},{"type":"Genişletme","prompt":"My bed is blue.","cue":"add 'and my lamp is yellow'","answer":"My bed is blue and my lamp is yellow."},{"type":"Soru yap","prompt":"My shoe is under the bed.","cue":"make a question with 'Where'","answer":"Where is my shoe?"}],"sounds":[{"focus":"/ʊ/","tr":"Dudaklarını hafifçe yuvarla ama sesi kısa tut: 'book', 'look', 'good'. Uzun 'u' sesi gibi uzatırsan 'boot' olur.","pairs":["book / boot","full / fool"]}],"mission":{"brief":"Oyun: Yatak odanı İngilizce anlat ve eşyalarının nerede olduğunu söyle. Claude, arkadaşın Kaan olacak ve senin odanı merak edip sorular soracak.","persona":"Kaan, a curious 7-year-old who is visiting his friend's house for the first time. Uses very short, simple sentences and lots of encouragement. Asks one question at a time. Hidden fact: Kaan has a teddy bear named Tomato that sleeps under his bed; he only mentions it if the learner asks what is under their bed.","goal":"Yatak odandaki üç eşyayı 'my' kalıbıyla anlat.","opener":"Hi! I'm Kaan. Can you tell me about your bedroom?"}},"KS1-017":{"objectives":["Parktaki yerleri ve nesneleri söylemek","'Let's…' kalıbıyla birlikte bir şey önermek","Park şarkısını alkışlayarak tekrar etmek"],"dialogues":[{"title":"Let's go to the park!","setting":"Hafta sonu, Kaan babasıyla parka gidiyor.","lines":[{"s":"Dad","en":"Let's go to the park, Kaan!","tr":"Hadi parka gidelim Kaan!"},{"s":"Kaan","en":"Yay! Can I take my ball?","tr":"Yaşasın! Topumu alabilir miyim?"},{"s":"Dad","en":"Yes, take your ball!","tr":"Evet, topunu al!"},{"s":"Kaan","en":"Look! The slide is big!","tr":"Bak! Kaydırak çok büyük!"},{"s":"Dad","en":"Let's play on the slide first.","tr":"Önce kaydırakta oynayalım."},{"s":"Kaan","en":"Yay! Wheee!","tr":"Yaşasın! Vuhuu!"}]},{"title":"A duck and a dog","setting":"Parkta, Ada annesiyle bir ördek ve köpek görüyor.","lines":[{"s":"Ada","en":"Mum, look! A duck!","tr":"Anne, bak! Bir ördek!"},{"s":"Mum","en":"Yes! The duck is by the tree.","tr":"Evet! Ördek ağacın yanında."},{"s":"Ada","en":"Can we say hello?","tr":"Merhaba diyebilir miyiz?"},{"s":"Mum","en":"Yes, but be gentle. Look, a dog too!","tr":"Evet, ama nazik ol. Bak, bir köpek de var!"},{"s":"Ada","en":"Hello, dog! Let's run to the bench.","tr":"Merhaba köpek! Hadi banka koşalım."},{"s":"Mum","en":"Good! Let's sit on the bench.","tr":"Güzel! Hadi bankta oturalım."}]},{"title":"Park song","setting":"Ritimle tekrar et, alkışla!","lines":[{"s":"Teacher","en":"Run, run, run to the park!","tr":"Koş, koş, koş parka!"},{"s":"Kids","en":"Run, run, run to the park!","tr":"Koş, koş, koş parka!"},{"s":"Teacher","en":"Ball, slide, tree and duck!","tr":"Top, kaydırak, ağaç ve ördek!"},{"s":"Kids","en":"Ball, slide, tree and duck!","tr":"Top, kaydırak, ağaç ve ördek!"},{"s":"Teacher","en":"Let's play all day!","tr":"Gün boyu oynayalım!"}]}],"reading":{"title":"A day at the park","paras":[{"en":"Hi! I'm Kaan. Today we are at the park. I can see a big tree and a small duck. A dog runs by the bench. I play with my ball and I go down the slide. Let's play again! At the park I always have fun. Where do you like to play?","tr":"Merhaba! Ben Kaan. Bugün parktayız. Büyük bir ağaç ve küçük bir ördek görebiliyorum. Bir köpek bankın yanında koşuyor. Topumla oynuyorum ve kaydıraktan kayıyorum. Hadi tekrar oynayalım! Park her zaman eğlencelidir. Sen nerede oynamayı seversin?"}]},"vocab":[{"w":"park","ipa":"/pɑːk/","pos":"🏞️","tr":"park","ex":"We are at the park.","exTr":"Parktayız."},{"w":"slide","ipa":"/slaɪd/","pos":"🛝","tr":"kaydırak","ex":"I go down the slide.","exTr":"Kaydıraktan kayarım."},{"w":"ball","ipa":"/bɔːl/","pos":"⚽","tr":"top","ex":"Let's play with the ball.","exTr":"Hadi topla oynayalım."},{"w":"bench","ipa":"/bentʃ/","pos":"🪑","tr":"bank","ex":"Let's sit on the bench.","exTr":"Hadi bankta oturalım."},{"w":"duck","ipa":"/dʌk/","pos":"🦆","tr":"ördek","ex":"The duck is by the tree.","exTr":"Ördek ağacın yanında."},{"w":"tree","ipa":"/triː/","pos":"🌳","tr":"ağaç","ex":"There is a big tree.","exTr":"Büyük bir ağaç var."},{"w":"dog","ipa":"/dɒɡ/","pos":"🐶","tr":"köpek","ex":"A dog runs by the bench.","exTr":"Bir köpek bankın yanında koşuyor."},{"w":"run","ipa":"/rʌn/","pos":"🏃","tr":"koşmak","ex":"Let's run to the tree!","exTr":"Hadi ağaca koşalım!"}],"chunks":[{"en":"Let's go!","tr":"Hadi gidelim!"},{"en":"Can I…?","tr":"… yapabilir miyim?"},{"en":"Be gentle.","tr":"Nazik ol."},{"en":"Look! A duck!","tr":"Bak! Bir ördek!"}],"grammar":{"point":"Let's + verb","tr":"Birlikte bir şey yapmayı önermek için 'Let's' kullanılır. 'Let's', 'Let us' demektir ve Türkçedeki 'Hadi … yapalım' gibidir. 'Let's' sonrasında fiilin yalın hali gelir.","examples":["Let's play!","Let's go to the slide.","Let's swing!","Let's run to the tree."]},"questions":[{"q":"Where are Kaan and Dad?","a":"At the park."},{"q":"What does Kaan take to the park?","a":"His ball."},{"q":"What is by the tree?","a":"A duck."}],"quiz":[{"q":"🛝 is a…","o":["slide","bench","ball"],"a":0,"why":""},{"q":"'Let's ___!' (koşmak)","o":["runs","run","running"],"a":1,"why":"'Let's' den sonra fiilin yalın hali gelir."},{"q":"🦆 is a…","o":["tree","dog","duck"],"a":2,"why":""},{"q":"Where do we sit? 🪑","o":["slide","bench","park"],"a":1,"why":""}],"drills":[{"type":"Yerine koyma","prompt":"Let's play on the slide.","cue":"run to the tree","answer":"Let's run to the tree."},{"type":"Genişletme","prompt":"I play with my ball.","cue":"add 'in the park'","answer":"I play with my ball in the park."},{"type":"Soru yap","prompt":"Let's go to the park.","cue":"make a question with 'Can we'","answer":"Can we go to the park?"}],"sounds":[{"focus":"/ɑː/","tr":"Ağzını geniş aç, dilini aşağı indir ve uzun 'a' de: 'park', 'car', 'dark'. Türkçedeki kısa 'a' gibi bitirme, sesi biraz uzat.","pairs":["park / pack","car / cat"]}],"mission":{"brief":"Oyun: Parkta ne yapmak istediğini İngilizce söyle ve arkadaşını bir şeye davet et. Claude, arkadaşın Ada olacak ve sana parkta ne oynamak istediğini soracak.","persona":"Ada, a 7-year-old who loves the park. Uses very short, simple sentences and lots of encouragement. Asks one question at a time. Hidden fact: Ada is a little scared of the big slide but loves the swings; she only admits this if the learner asks what she is afraid of.","goal":"Parkta üç şey yapmayı 'Let's…' kalıbıyla öner.","opener":"Hi! I'm Ada. Do you want to play at the park?"}},"KS1-018":{"objectives":["Duyguları İngilizce söylemek","'I'm…' kalıbıyla nasıl hissettiğini anlatmak","Duygu kelimelerini bir şarkı ritmiyle tekrar etmek"],"dialogues":[{"title":"How do you feel?","setting":"Sabah, Mert annesine nasıl hissettiğini anlatıyor.","lines":[{"s":"Mum","en":"Good morning, Mert! How are you?","tr":"Günaydın Mert! Nasılsın?"},{"s":"Mert","en":"I'm tired. I went to bed late.","tr":"Yorgunum. Geç yattım."},{"s":"Mum","en":"Oh no! Are you hungry?","tr":"Ah olamaz! Acıktın mı?"},{"s":"Mert","en":"Yes! I'm hungry. And I'm happy too!","tr":"Evet! Acıktım. Bir de mutluyum!"},{"s":"Mum","en":"Why are you happy?","tr":"Neden mutlusun?"},{"s":"Mert","en":"Because it's Saturday! I'm excited!","tr":"Çünkü bugün cumartesi! Çok heyecanlıyım!"}]},{"title":"Don't be sad","setting":"Ali'nin oyuncağı kırılınca Ada onu teselli ediyor.","lines":[{"s":"Ali","en":"I'm sad. My toy is broken.","tr":"Üzgünüm. Oyuncağım kırıldı."},{"s":"Ada","en":"Oh, sorry, Ali. Are you okay?","tr":"Ah, üzgünüm Ali. İyi misin?"},{"s":"Ali","en":"No... I'm angry too.","tr":"Hayır... Bir de kızgınım."},{"s":"Ada","en":"Don't be angry. Let's fix it together.","tr":"Kızgın olma. Birlikte tamir edelim."},{"s":"Ali","en":"Okay! Thank you, Ada.","tr":"Tamam! Teşekkürler Ada."},{"s":"Ada","en":"Now I'm happy too!","tr":"Şimdi ben de mutluyum!"}]},{"title":"Feelings song","setting":"Ritimle tekrar et, alkışla!","lines":[{"s":"Teacher","en":"Happy, sad, angry, tired!","tr":"Mutlu, üzgün, kızgın, yorgun!"},{"s":"Kids","en":"Happy, sad, angry, tired!","tr":"Mutlu, üzgün, kızgın, yorgun!"},{"s":"Teacher","en":"Scared, excited, hungry, okay!","tr":"Korkmuş, heyecanlı, aç, tamam!"},{"s":"Kids","en":"Scared, excited, hungry, okay!","tr":"Korkmuş, heyecanlı, aç, tamam!"},{"s":"Teacher","en":"How do you feel today?","tr":"Bugün nasıl hissediyorsun?"}]}],"reading":{"title":"Feelings every day","paras":[{"en":"Hi! I'm Leo. I feel happy when I play with my dog. I feel sad when it rains and I can't go out. I'm scared of the dark, but my lamp helps me. Today I'm excited because it's my birthday! Sometimes I'm tired or hungry too. How do you feel today? Are you okay?","tr":"Merhaba! Ben Leo. Köpeğimle oynarken mutlu hissederim. Yağmur yağdığında ve dışarı çıkamadığımda üzgün olurum. Karanlıktan korkarım ama lambam bana yardım eder. Bugün doğum günüm olduğu için heyecanlıyım! Bazen yorgun ya da aç da olurum. Bugün nasıl hissediyorsun? İyi misin?"}]},"vocab":[{"w":"happy","ipa":"/ˈhæpi/","pos":"😊","tr":"mutlu","ex":"I'm happy today.","exTr":"Bugün mutluyum."},{"w":"sad","ipa":"/sæd/","pos":"😢","tr":"üzgün","ex":"She's sad.","exTr":"O üzgün."},{"w":"angry","ipa":"/ˈæŋɡri/","pos":"😠","tr":"kızgın","ex":"I'm angry too.","exTr":"Ben de kızgınım."},{"w":"tired","ipa":"/ˈtaɪəd/","pos":"😴","tr":"yorgun","ex":"I'm tired.","exTr":"Yorgunum."},{"w":"scared","ipa":"/skeəd/","pos":"😨","tr":"korkmuş","ex":"I'm scared of the dark.","exTr":"Karanlıktan korkuyorum."},{"w":"excited","ipa":"/ɪkˈsaɪtɪd/","pos":"🤩","tr":"heyecanlı","ex":"I'm excited!","exTr":"Çok heyecanlıyım!"},{"w":"hungry","ipa":"/ˈhʌŋɡri/","pos":"🍽️","tr":"aç","ex":"Are you hungry?","exTr":"Acıktın mı?"},{"w":"okay","ipa":"/ˌəʊˈkeɪ/","pos":"👍","tr":"iyi, tamam","ex":"Are you okay?","exTr":"İyi misin?"}],"chunks":[{"en":"How do you feel?","tr":"Nasıl hissediyorsun?"},{"en":"I'm happy!","tr":"Mutluyum!"},{"en":"Don't be sad.","tr":"Üzülme."},{"en":"Are you okay?","tr":"İyi misin?"}],"grammar":{"point":"I'm + feeling","tr":"Bir duygunu anlatmak için 'I'm' (I am) ve bir duygu kelimesi kullanılır. Birini anlatırken 'He's' ya da 'She's' yazılır. Türkçedeki 'Ben mutluyum' cümlesi gibidir.","examples":["I'm happy today.","She's sad.","He's hungry.","Are you okay?"]},"questions":[{"q":"How does Mert feel in the morning?","a":"He's tired."},{"q":"Why is Ali sad?","a":"His toy is broken."},{"q":"How does Leo feel when it rains?","a":"He feels sad."}],"quiz":[{"q":"😢 means…","o":["happy","sad","tired"],"a":1,"why":""},{"q":"'I'm ___ of the dark.' (😨)","o":["scared","excited","hungry"],"a":0,"why":""},{"q":"Are you ___? (🍽️)","o":["tired","hungry","angry"],"a":1,"why":""},{"q":"'I'm happy' means…","o":["Ben yorgunum","Ben üzgünüm","Ben mutluyum"],"a":2,"why":""}],"drills":[{"type":"Yerine koyma","prompt":"I'm happy.","cue":"sad","answer":"I'm sad."},{"type":"Dönüştürme","prompt":"She's tired.","cue":"He","answer":"He's tired."},{"type":"Soru yap","prompt":"You are okay.","cue":"make a question","answer":"Are you okay?"}],"sounds":[{"focus":"/æ/","tr":"Ağzını geniş aç, dilini aşağı indir: 'sad', 'happy', 'angry'. Türkçedeki 'e' gibi okuma; 'a' ile 'e' arasında bir ses çıkar.","pairs":["sad / said","bad / bed"]}],"mission":{"brief":"Oyun: Bugün nasıl hissettiğini İngilizce anlat. Claude, arkadaşın Deniz olacak ve sana duygularını soracak.","persona":"Deniz, a cheerful 7-year-old who always talks about how she feels. Uses very short, simple sentences and lots of encouragement. Asks one question at a time. Hidden fact: Deniz feels a little scared because she goes to the dentist tomorrow; she only says this if the learner asks why she is quiet.","goal":"Üç farklı duyguyu İngilizce söyle ve birine 'Are you…?' diye sor.","opener":"Hi! I'm Deniz. How are you feeling today?"}},"KS1-019":{"objectives":["'I can…' ile neler yapabildiğini söylemek","'Can you…?' ile soru sormak","Hareket fiillerini tanımak ve tekrar etmek"],"dialogues":[{"title":"Watch me jump!","setting":"Parkta Zeynep ile Leo oynuyor.","lines":[{"s":"Leo","en":"Look! I can jump high!","tr":"Bak! Yüksek zıplayabiliyorum!"},{"s":"Zeynep","en":"Wow! I can jump too.","tr":"Vay! Ben de zıplayabilirim."},{"s":"Leo","en":"Can you run fast?","tr":"Hızlı koşabilir misin?"},{"s":"Zeynep","en":"Yes, I can! Let's race!","tr":"Evet, koşabilirim! Yarışalım!"},{"s":"Leo","en":"OK! One, two, three, go!","tr":"Tamam! Bir, iki, üç, başla!"},{"s":"Zeynep","en":"I'm first! I can run fast!","tr":"Birinciyim! Hızlı koşabiliyorum!"}]},{"title":"Can a bird fly?","setting":"Havuz kenarında Mia ile Leo sohbet ediyor.","lines":[{"s":"Mia","en":"I can swim! Can you swim?","tr":"Ben yüzebilirim! Sen yüzebilir misin?"},{"s":"Leo","en":"No, I can't swim. I can sing!","tr":"Hayır, yüzemem. Şarkı söyleyebilirim!"},{"s":"Mia","en":"Can a bird fly?","tr":"Kuş uçabilir mi?"},{"s":"Leo","en":"Yes! A bird can fly high.","tr":"Evet! Kuş yükseklere uçabilir."},{"s":"Mia","en":"Can a rabbit hop?","tr":"Tavşan zıplayabilir mi?"},{"s":"Leo","en":"Yes! Look, it can hop like this!","tr":"Evet! Bak, böyle sekebiliyor!"}]},{"title":"Action chant","setting":"Ritimle tekrar et, alkışla!","lines":[{"s":"Teacher","en":"I can jump, I can run!","tr":"Zıplayabilirim, koşabilirim!"},{"s":"Kids","en":"I can jump, I can run!","tr":"Zıplayabilirim, koşabilirim!"},{"s":"Teacher","en":"I can swim, I can climb!","tr":"Yüzebilirim, tırmanabilirim!"},{"s":"Kids","en":"I can swim, I can climb!","tr":"Yüzebilirim, tırmanabilirim!"},{"s":"Teacher","en":"Can you dance? Can you sing?","tr":"Dans edebilir misin? Şarkı söyleyebilir misin?"},{"s":"Kids","en":"Yes, I can! Hooray!","tr":"Evet, yapabilirim! Yaşasın!"}]}],"reading":{"title":"Mia can do it!","paras":[{"en":"Hi! I'm Mia. I'm seven years old. I can jump, run and dance. I can sing, too! I can't fly like a bird, but I can climb trees. My friend Leo can hop like a rabbit. Every day at school we play games, and I can run faster than Leo! Can you jump with me?","tr":"Merhaba! Ben Mia. Yedi yaşındayım. Zıplayabilirim, koşabilirim ve dans edebilirim. Şarkı da söyleyebilirim! Kuş gibi uçamam ama ağaçlara tırmanabilirim. Arkadaşım Leo tavşan gibi sekebilir. Her gün okulda oyunlar oynarız ve Leo'dan daha hızlı koşabilirim! Benimle zıplar mısın?"}]},"vocab":[{"w":"jump","ipa":"/dʒʌmp/","pos":"🤸","tr":"zıplamak","ex":"I can jump high.","exTr":"Yüksek zıplayabilirim."},{"w":"run","ipa":"/rʌn/","pos":"🏃","tr":"koşmak","ex":"Leo can run fast.","exTr":"Leo hızlı koşabilir."},{"w":"swim","ipa":"/swɪm/","pos":"🏊","tr":"yüzmek","ex":"Fish can swim.","exTr":"Balıklar yüzebilir."},{"w":"climb","ipa":"/klaɪm/","pos":"🧗","tr":"tırmanmak","ex":"I can climb trees.","exTr":"Ağaçlara tırmanabilirim."},{"w":"fly","ipa":"/flaɪ/","pos":"🐦","tr":"uçmak","ex":"A bird can fly.","exTr":"Bir kuş uçabilir."},{"w":"dance","ipa":"/dɑːns/","pos":"💃","tr":"dans etmek","ex":"Can you dance?","exTr":"Dans edebilir misin?"},{"w":"sing","ipa":"/sɪŋ/","pos":"🎤","tr":"şarkı söylemek","ex":"I can sing.","exTr":"Şarkı söyleyebilirim."},{"w":"hop","ipa":"/hɒp/","pos":"🐇","tr":"sekmek","ex":"The rabbit can hop.","exTr":"Tavşan sekebilir."}],"chunks":[{"en":"I can…","tr":"…yapabilirim."},{"en":"Can you…?","tr":"…yapabilir misin?"},{"en":"Yes, I can!","tr":"Evet, yapabilirim!"},{"en":"No, I can't.","tr":"Hayır, yapamam."}],"grammar":{"point":"can (ability)","tr":"'Can' bir şeyi yapabildiğini anlatır. Fiil her zaman aynı kalır: 'I can run', 'She can jump'. Soru yaparken 'Can' cümlenin başına gelir.","examples":["I can jump high.","Can you run fast?","She can swim.","I can't fly."]},"questions":[{"q":"What can Mia do?","a":"She can jump, run and dance."},{"q":"Can Mia fly?","a":"No, she can't."},{"q":"What can Leo do like a rabbit?","a":"He can hop."}],"quiz":[{"q":"Fish can…","o":["fly","swim","hop"],"a":1,"why":""},{"q":"Leo can ___ like a rabbit.","o":["hop","fly","swim"],"a":0,"why":""},{"q":"Mia can't ___.","o":["jump","run","fly"],"a":2,"why":""},{"q":"🎤 means…","o":["dance","sing","hop"],"a":1,"why":""}],"drills":[{"type":"Yerine koyma","prompt":"I can jump.","cue":"swim","answer":"I can swim."},{"type":"Soru yap","prompt":"You can dance.","cue":"Can…?","answer":"Can you dance?"},{"type":"Dönüştürme","prompt":"I can fly.","cue":"negative (can't)","answer":"I can't fly."}],"sounds":[{"focus":"/ɪ/","tr":"Kısa 'i' sesi: 'ship' ve 'swim' kelimelerinde dilini gevşek tut ve sesi kısa bitir. 'sheep' ve 'seat' gibi uzun 'i' sesiyle karıştırma.","pairs":["ship / sheep","sit / seat"]}],"mission":{"brief":"Claude, arkadaşın Leo olacak. Leo ile oyun oynarken ne yapabildiğini anlat ve onun neler yapabildiğini öğren.","persona":"Leo, a cheerful 7-year-old. Very short sentences and lots of 'Wow!'. Asks one question at a time. Hidden fact: he can sing very loudly, but he can't swim yet. He only tells this when the learner asks the right question.","goal":"Leo'ya 'Can you…?' diye en az iki soru sor ve cevap al.","opener":"Hi! I'm Leo. Let's play! What can you do?"}},"KS1-020":{"objectives":["Temel şekilleri İngilizce adlandırmak","'What shape is it?' ile soru sormak","'It's a…' kalıbıyla bir şekli tarif etmek"],"dialogues":[{"title":"What shape is it?","setting":"Leo ile Zeynep bir kâğıdın başında oturuyor.","lines":[{"s":"Leo","en":"Look! What shape is this?","tr":"Bak! Bu ne şekil?"},{"s":"Zeynep","en":"It's a circle. It's round!","tr":"Bu bir daire. Yuvarlak!"},{"s":"Leo","en":"And what shape is this one?","tr":"Peki bu ne şekil?"},{"s":"Zeynep","en":"It's a square. It has four sides.","tr":"Bu bir kare. Dört kenarı var."},{"s":"Leo","en":"Oh, and this one has three sides!","tr":"Ah, bunun da üç kenarı var!"},{"s":"Zeynep","en":"Yes! It's a triangle.","tr":"Evet! Bu bir üçgen."}]},{"title":"A red heart","setting":"Mia ile Ali sınıfta resim yapıyor.","lines":[{"s":"Mia","en":"I draw a red heart for Mum.","tr":"Annem için kırmızı bir kalp çiziyorum."},{"s":"Ali","en":"Wow, it's beautiful! Can you draw a star?","tr":"Vay, çok güzel! Bir yıldız çizebilir misin?"},{"s":"Mia","en":"Yes! Here is a star. Look!","tr":"Evet! İşte bir yıldız. Bak!"},{"s":"Ali","en":"I draw a big blue diamond.","tr":"Ben büyük, mavi bir elmas çiziyorum."},{"s":"Mia","en":"Cool! Now draw an oval, like an egg.","tr":"Harika! Şimdi bir yumurta gibi oval çiz."},{"s":"Ali","en":"Oval! Like an egg!","tr":"Oval! Yumurta gibi!"}]},{"title":"Shape chant","setting":"Ritimle tekrar et, şekilleri göster!","lines":[{"s":"Teacher","en":"Circle, circle, round and round!","tr":"Daire, daire, dönüp dur!"},{"s":"Kids","en":"Circle, circle, round and round!","tr":"Daire, daire, dönüp dur!"},{"s":"Teacher","en":"Square, triangle, up and down!","tr":"Kare, üçgen, yukarı aşağı!"},{"s":"Kids","en":"Square, triangle, up and down!","tr":"Kare, üçgen, yukarı aşağı!"},{"s":"Teacher","en":"Star and heart, can you see?","tr":"Yıldız ve kalp, görüyor musun?"},{"s":"Kids","en":"Yes, I can see! Yes, I can see!","tr":"Evet, görüyorum! Evet, görüyorum!"}]}],"reading":{"title":"Shapes everywhere","paras":[{"en":"Hi! I'm Ali. Look around my room. My clock is a circle. My window is a square. My kite is a diamond, and my cake is a heart! My cookie is a star. My egg is an oval, and my bowl is red. Shapes are everywhere! What shape is your bed?","tr":"Merhaba! Ben Ali. Odama bak. Saatim bir daire. Pencerem bir kare. Uçurtmam bir elmas, pastam ise bir kalp! Kurabiyem bir yıldız. Yumurtam oval, kasem de kırmızı. Şekiller her yerde! Senin yatağın ne şekil?"}]},"vocab":[{"w":"circle","ipa":"/ˈsɜːkl/","pos":"⭕","tr":"daire","ex":"My clock is a circle.","exTr":"Saatim bir daire."},{"w":"square","ipa":"/skweə/","pos":"🟥","tr":"kare","ex":"My window is a square.","exTr":"Pencerem bir kare."},{"w":"triangle","ipa":"/ˈtraɪæŋɡl/","pos":"🔺","tr":"üçgen","ex":"A triangle has three sides.","exTr":"Bir üçgenin üç kenarı vardır."},{"w":"star","ipa":"/stɑː/","pos":"⭐","tr":"yıldız","ex":"Look at the star!","exTr":"Yıldıza bak!"},{"w":"heart","ipa":"/hɑːt/","pos":"❤️","tr":"kalp","ex":"I drew a red heart.","exTr":"Kırmızı bir kalp çizdim."},{"w":"diamond","ipa":"/ˈdaɪəmənd/","pos":"🔷","tr":"elmas (şekil)","ex":"My kite is a diamond.","exTr":"Uçurtmam bir elmas."},{"w":"oval","ipa":"/ˈəʊvl/","pos":"🥚","tr":"oval","ex":"An egg is an oval.","exTr":"Yumurta oval bir şekildir."},{"w":"red","ipa":"/red/","pos":"🔴","tr":"kırmızı","ex":"The heart is red.","exTr":"Kalp kırmızı."}],"chunks":[{"en":"What shape is it?","tr":"Bu ne şekil?"},{"en":"It's a…","tr":"Bu bir…"},{"en":"Look at this…!","tr":"Şu … bak!"},{"en":"Can you draw a…?","tr":"Bir … çizebilir misin?"}],"grammar":{"point":"It's a / an + shape","tr":"'It's' 'It is' kısaltmasıdır ve 'Bu bir…' anlamına gelir. Şekil adı sesli harfle başlıyorsa 'a' yerine 'an' kullanılır.","examples":["It's a star.","It's an oval.","What shape is it?","Can you draw a heart?"]},"questions":[{"q":"How many sides does a triangle have?","a":"Three sides."},{"q":"What colour is Mia's heart?","a":"Red."},{"q":"What shape is Ali's cake?","a":"A heart."}],"quiz":[{"q":"🔺 is a…","o":["circle","triangle","star"],"a":1,"why":""},{"q":"My clock is a…","o":["circle","square","heart"],"a":0,"why":""},{"q":"⭐ is a…","o":["heart","diamond","star"],"a":2,"why":""},{"q":"How many sides does a triangle have?","o":["two","three","four"],"a":1,"why":""}],"drills":[{"type":"Yerine koyma","prompt":"It's a circle.","cue":"square","answer":"It's a square."},{"type":"Soru yap","prompt":"It's a triangle.","cue":"What…?","answer":"What shape is it?"},{"type":"Genişletme","prompt":"Can you draw a star?","cue":"red","answer":"Can you draw a red star?"}],"sounds":[{"focus":"/ɜː/","tr":"Dilini ağzının ortasında tut, dudaklarını hafifçe yuvarla ve sesi uzat: 'bird' ve 'circle' kelimelerinde. Türkçedeki uzun 'ö' gibi düşünebilirsin; 'bed' kelimesindeki kısa 'e' ile karıştırma.","pairs":["bird / bed","shirt / shot"]}],"mission":{"brief":"Claude, arkadaşın Ali olacak. Ali'ye bir şekil tarif et ve Ali'nin çizdiği şekli bulmaya çalış. Bunun için 'What shape is it?' diye sor.","persona":"Ali, a 7-year-old artist. Speaks in short, cheerful sentences. Hidden fact: his kite is a green diamond, not a square. He only describes it if the learner asks about its shape and colour.","goal":"Ali'nin uçurtmasının şeklini ve rengini öğren.","opener":"Hi! I drew a kite today. Can you guess its shape?"}},"KS1-021":{"objectives":["Doğum günü davetine cevap vermek","'Can I…?' ile izin istemek","Doğum günü partisiyle ilgili kelimeleri öğrenmek"],"dialogues":[{"title":"Come to my party!","setting":"Zeynep, Leo'yu doğum günü partisine davet ediyor.","lines":[{"s":"Zeynep","en":"Hi Leo! It's my birthday party on Saturday.","tr":"Merhaba Leo! Cumartesi günü doğum günü partim var."},{"s":"Leo","en":"Wow! Happy birthday! Can I come?","tr":"Vay! Doğum günün kutlu olsun! Gelebilir miyim?"},{"s":"Zeynep","en":"Yes, please! The party starts at two.","tr":"Evet, lütfen! Parti saat ikide başlıyor."},{"s":"Leo","en":"Great! Can I bring a present?","tr":"Harika! Hediye getirebilir miyim?"},{"s":"Zeynep","en":"Yes, you can! I like balloons.","tr":"Evet, getirebilirsin! Balonları severim."},{"s":"Leo","en":"OK! I'll bring a big balloon for you.","tr":"Tamam! Sana büyük bir balon getireceğim."}]},{"title":"Blow the candles!","setting":"Annesi pastayı getiriyor ve mumlar yanıyor.","lines":[{"s":"Mum","en":"Here is the cake! Look at the candles.","tr":"İşte pasta! Mumlara bak."},{"s":"Zeynep","en":"Wow! It's a big cake with five candles!","tr":"Vay! Beş mumlu büyük bir pasta!"},{"s":"Leo","en":"Make a wish, Zeynep!","tr":"Bir dilek tut, Zeynep!"},{"s":"Zeynep","en":"OK! Now I blow. Whoosh!","tr":"Tamam! Şimdi üflüyorum. Fuuu!"},{"s":"Mum","en":"Happy birthday, Zeynep!","tr":"Doğum günün kutlu olsun, Zeynep!"},{"s":"Leo","en":"Hooray! I'm so happy!","tr":"Yaşasın! Çok mutluyum!"}]},{"title":"Balloon chant","setting":"Ritimle tekrar et, balonları say!","lines":[{"s":"Teacher","en":"One balloon, two balloons, let's play!","tr":"Bir balon, iki balon, oynayalım!"},{"s":"Kids","en":"One balloon, two balloons, let's play!","tr":"Bir balon, iki balon, oynayalım!"},{"s":"Teacher","en":"Clap, clap, happy party day!","tr":"Çırp, çırp, mutlu parti günü!"},{"s":"Kids","en":"Clap, clap, happy party day!","tr":"Çırp, çırp, mutlu parti günü!"},{"s":"Teacher","en":"Sing with me and say hooray!","tr":"Benimle şarkı söyle ve yaşasın de!"},{"s":"Kids","en":"Hooray! Hooray!","tr":"Yaşasın! Yaşasın!"}]}],"reading":{"title":"Zeynep's big day","paras":[{"en":"Today is Zeynep's birthday. She has a big cake with five candles. There are red and blue balloons in the room. Her friends bring presents and sing a song together. Leo gives her a balloon. Zeynep blows the candles and says, 'Thank you, friends!' Everyone is happy at the party.","tr":"Bugün Zeynep'in doğum günü. Beş mumlu büyük bir pastası var. Odada kırmızı ve mavi balonlar var. Arkadaşları hediye getirir ve birlikte bir şarkı söyler. Leo ona bir balon verir. Zeynep mumları üfler ve 'Teşekkürler, arkadaşlar!' der. Partide herkes mutlu."}]},"vocab":[{"w":"party","ipa":"/ˈpɑːti/","pos":"🎉","tr":"parti","ex":"It's my birthday party.","exTr":"Bu benim doğum günü partim."},{"w":"cake","ipa":"/keɪk/","pos":"🎂","tr":"pasta","ex":"Mum makes a big cake.","exTr":"Annem büyük bir pasta yapıyor."},{"w":"balloon","ipa":"/bəˈluːn/","pos":"🎈","tr":"balon","ex":"I have a red balloon.","exTr":"Kırmızı bir balonum var."},{"w":"present","ipa":"/ˈpreznt/","pos":"🎁","tr":"hediye","ex":"This present is for you.","exTr":"Bu hediye senin için."},{"w":"candle","ipa":"/ˈkændl/","pos":"🕯️","tr":"mum","ex":"Five candles are on the cake.","exTr":"Pastada beş mum var."},{"w":"friend","ipa":"/frend/","pos":"👫","tr":"arkadaş","ex":"Leo is my friend.","exTr":"Leo benim arkadaşım."},{"w":"happy","ipa":"/ˈhæpi/","pos":"😊","tr":"mutlu","ex":"I am happy!","exTr":"Mutluyum!"},{"w":"blow","ipa":"/bləʊ/","pos":"💨","tr":"üflemek","ex":"Blow out the candles!","exTr":"Mumları üfle!"}],"chunks":[{"en":"Can I come?","tr":"Gelebilir miyim?"},{"en":"Happy birthday!","tr":"Doğum günün kutlu olsun!"},{"en":"Make a wish!","tr":"Bir dilek tut!"},{"en":"Thank you, friends!","tr":"Teşekkürler, arkadaşlar!"}],"grammar":{"point":"Can I…?","tr":"'Can I…?' izin istemek için kullanılır ve 'Yapabilir miyim?' anlamına gelir. Cevap olarak 'Yes, you can!' ya da 'No, you can't.' deriz.","examples":["Can I come?","Can I bring a present?","Can I blow the candles?","Can I have a balloon?"]},"questions":[{"q":"When is Zeynep's party?","a":"On Saturday."},{"q":"How many candles are on the cake?","a":"Five."},{"q":"What does Leo bring?","a":"A balloon."}],"quiz":[{"q":"🎂 means…","o":["cake","balloon","present"],"a":0,"why":""},{"q":"😊 means…","o":["sad","angry","happy"],"a":2,"why":""},{"q":"Zeynep's party is on…","o":["Monday","Saturday","Sunday"],"a":1,"why":""},{"q":"How many candles are on the cake?","o":["five","three","seven"],"a":0,"why":""}],"drills":[{"type":"Yerine koyma","prompt":"Can I bring a present?","cue":"balloon","answer":"Can I bring a balloon?"},{"type":"Yerine koyma","prompt":"Happy birthday, Zeynep!","cue":"Leo","answer":"Happy birthday, Leo!"},{"type":"Soru yap","prompt":"You can blow the candles.","cue":"Can…?","answer":"Can you blow the candles?"}],"sounds":[{"focus":"/eɪ/","tr":"Türkçedeki 'e' sesi kısa ve tektir. İngilizcede 'eɪ' bir kayma sesidir: 'cake' ve 'day' kelimelerinde sesi 'ey' gibi uzatarak söyle.","pairs":["cake / cat","day / den"]}],"mission":{"brief":"Claude, Leo olacak ve senin doğum günü partine davet edilecek. Ona partinin gününü ve saatini anlat, sonra Leo'nun ne getirmek istediğini öğren.","persona":"Leo, a 7-year-old who loves balloons. Speaks in short, happy sentences and asks one question at a time. Hidden fact: he can't come on Saturday because of swimming, but he can come on Sunday. He only says this when the learner asks when he can come.","goal":"Leo'nun hangi gün geleceğini öğren ve ona 'Can I…?' diye bir soru sor.","opener":"Hi! Is it your birthday? Can I come to your party?"}},"KS1-022":{"objectives":["Plajdaki şeyleri İngilizce söylemek","'Let's…' ile birlikte bir şey önermek","Hava ve sahil kelimelerini kısa cümlelerle kullanmak"],"dialogues":[{"title":"Let's go to the beach!","setting":"Mia'nın ailesi sahilde, Leo da onlarla birlikte.","lines":[{"s":"Mum","en":"Look, we are at the beach!","tr":"Bak, sahildeyiz!"},{"s":"Mia","en":"Wow! The sea is so big and blue!","tr":"Vay! Deniz çok büyük ve mavi!"},{"s":"Leo","en":"Let's build a castle with sand!","tr":"Hadi kumdan bir kale yapalım!"},{"s":"Mia","en":"Yes! Can you get a shell for the top?","tr":"Evet! Tepesi için bir deniz kabuğu alır mısın?"},{"s":"Leo","en":"Here it is! It's a pretty shell.","tr":"İşte! Güzel bir kabuk."},{"s":"Mum","en":"Don't forget your hat! The sun is hot.","tr":"Şapkanı unutma! Güneş çok sıcak."}]},{"title":"Ice cream, please!","setting":"Plajdaki dondurmacıda sıra bekliyorlar.","lines":[{"s":"Seller","en":"Hello! Do you want some ice cream?","tr":"Merhaba! Dondurma ister misiniz?"},{"s":"Mia","en":"Yes, please! I want chocolate.","tr":"Evet lütfen! Çikolatalı istiyorum."},{"s":"Seller","en":"Here you are! Be careful, it's cold.","tr":"Buyurun! Dikkat edin, çok soğuk."},{"s":"Leo","en":"Thank you! Let's eat it on the sand.","tr":"Teşekkürler! Hadi kumda yiyelim."},{"s":"Seller","en":"Enjoy!","tr":"Afiyet olsun!"},{"s":"Mia","en":"Mmm, it's yummy!","tr":"Mmm, çok lezzetli!"}]},{"title":"Beach chant","setting":"Ritimle tekrar et, sahil şarkısını söyle!","lines":[{"s":"Teacher","en":"Sun, sun, shining bright!","tr":"Güneş, güneş, parıl parıl!"},{"s":"Kids","en":"Sun, sun, shining bright!","tr":"Güneş, güneş, parıl parıl!"},{"s":"Teacher","en":"Sea, sea, big and blue!","tr":"Deniz, deniz, büyük ve mavi!"},{"s":"Kids","en":"Sea, sea, big and blue!","tr":"Deniz, deniz, büyük ve mavi!"},{"s":"Teacher","en":"Hat on, hat on, let's play too!","tr":"Şapkanı tak, şapkanı tak, sen de oyna!"},{"s":"Kids","en":"Hat on, hat on, let's play too!","tr":"Şapkanı tak, şapkanı tak, biz de oynayalım!"}]}],"reading":{"title":"A day at the beach","paras":[{"en":"Today we are at the beach. The sun is hot, and the sea is blue. Mia wears a red hat. Leo builds a big castle with sand. They find a pretty shell and put it on top. Then they eat ice cream. It's cold and yummy! Everyone feels happy at the beach.","tr":"Bugün sahildeyiz. Güneş çok sıcak, deniz ise mavi. Mia kırmızı bir şapka takıyor. Leo kumdan büyük bir kale yapıyor. Güzel bir deniz kabuğu bulup tepeye koyuyorlar. Sonra dondurma yiyorlar. Soğuk ve lezzetli! Sahilde herkes çok mutlu."}]},"vocab":[{"w":"beach","ipa":"/biːtʃ/","pos":"🏖️","tr":"sahil, plaj","ex":"We play at the beach.","exTr":"Sahilde oynuyoruz."},{"w":"sea","ipa":"/siː/","pos":"🌊","tr":"deniz","ex":"The sea is blue.","exTr":"Deniz mavi."},{"w":"sun","ipa":"/sʌn/","pos":"☀️","tr":"güneş","ex":"The sun is hot.","exTr":"Güneş sıcak."},{"w":"shell","ipa":"/ʃel/","pos":"🐚","tr":"deniz kabuğu","ex":"I have a pretty shell.","exTr":"Güzel bir deniz kabuğum var."},{"w":"castle","ipa":"/ˈkɑːsl/","pos":"🏰","tr":"kale","ex":"We build a castle.","exTr":"Bir kale yapıyoruz."},{"w":"hat","ipa":"/hæt/","pos":"👒","tr":"şapka","ex":"Wear your hat!","exTr":"Şapkanı tak!"},{"w":"ice cream","ipa":"/ˈaɪs kriːm/","pos":"🍦","tr":"dondurma","ex":"I want ice cream.","exTr":"Dondurma istiyorum."},{"w":"cold","ipa":"/kəʊld/","pos":"🥶","tr":"soğuk","ex":"The water is cold.","exTr":"Su soğuk."}],"chunks":[{"en":"Let's build a castle!","tr":"Hadi bir kale yapalım!"},{"en":"Don't forget your hat!","tr":"Şapkanı unutma!"},{"en":"Can you get a shell?","tr":"Bir deniz kabuğu alır mısın?"},{"en":"Be careful, it's cold.","tr":"Dikkat et, soğuk."}],"grammar":{"point":"Let's + verb","tr":"'Let's', 'let us' kısaltmasıdır ve birlikte bir şey yapmayı önerir: 'Hadi … yapalım!' 'Let's'ten sonra fiilin yalın hali gelir.","examples":["Let's go!","Let's build a castle!","Let's play in the sea!","Let's eat ice cream!"]},"questions":[{"q":"Where are Mia and Leo?","a":"At the beach."},{"q":"What do they build?","a":"A castle."},{"q":"What do they eat?","a":"Ice cream."}],"quiz":[{"q":"☀️ means…","o":["sun","shell","hat"],"a":0,"why":""},{"q":"🥶 means…","o":["hot","cold","castle"],"a":1,"why":""},{"q":"Let's ___ a castle!","o":["build","sun","hat"],"a":0,"why":""},{"q":"🍦 is…","o":["beach","shell","ice cream"],"a":2,"why":""}],"drills":[{"type":"Yerine koyma","prompt":"The sea is blue.","cue":"cold","answer":"The sea is cold."},{"type":"Soru yap","prompt":"It's very cold.","cue":"Is…?","answer":"Is it cold?"},{"type":"Genişletme","prompt":"Let's build a castle!","cue":"add 'with sand'","answer":"Let's build a castle with sand!"}],"sounds":[{"focus":"/iː/","tr":"Türkçedeki 'i' sesine benzer ama daha uzun tut: 'sea' ve 'heat' kelimelerinde dilini yukarıda tut. 'sit' ve 'hit' gibi kısa ve gevşek söylenen sesle karıştırma.","pairs":["sea / sit","heat / hit"]}],"mission":{"brief":"Claude, Leo olacak ve sahilde kum kalesi yapıyor. Ona 'Let's…' ile bir öneri yap ve Leo'nun sahilde neyi unuttuğunu öğren.","persona":"Leo, a 7-year-old at the beach building a sand castle. Speaks in short sentences. Hidden fact: he forgot his hat at home, so his head is very hot. He only admits this when the learner asks what he forgot.","goal":"Leo'nun neyi unuttuğunu öğren ve ona 'Let's…' ile bir öneri yap.","opener":"Hi! Our castle is big! Let's build a tower too!"}},"KS1-023":{"objectives":["Deniz hayvanlarının adlarını öğrenmek","'What is that?' sorusunu kullanmak","Deniz hayvanlarını kısa cümlelerle tarif etmek"],"dialogues":[{"title":"What is that?","setting":"Akvaryumda Zeynep ile Leo deniz canlılarına bakıyor.","lines":[{"s":"Leo","en":"Look! What is that?","tr":"Bak! Şu ne?"},{"s":"Zeynep","en":"It's a shark. It's very big!","tr":"Bu bir köpekbalığı. Çok büyük!"},{"s":"Leo","en":"Oh! And what is that one?","tr":"Ah! Peki şu ne?"},{"s":"Zeynep","en":"It's a dolphin. It's so friendly!","tr":"Bu bir yunus. Çok sevimli!"},{"s":"Leo","en":"Is that a whale?","tr":"Şu bir balina mı?"},{"s":"Zeynep","en":"Yes, it is! Wow!","tr":"Evet, öyle! Vay!"}]},{"title":"A crab and a turtle","setting":"Sahilde bir havuzun başında Mia ile Can deniz canlılarını izliyor.","lines":[{"s":"Mia","en":"Look at this crab! It's red.","tr":"Şu yengeca bak! Kırmızı."},{"s":"Can","en":"It can walk sideways!","tr":"Yana doğru yürüyebiliyor!"},{"s":"Mia","en":"Look! A turtle is swimming there.","tr":"Bak! Orada bir kaplumbağa yüzüyor."},{"s":"Can","en":"Turtles are slow. Can you see an octopus?","tr":"Kaplumbağalar yavaş. Bir ahtapot görebiliyor musun?"},{"s":"Mia","en":"Yes! It has eight arms.","tr":"Evet! Sekiz kolu var."},{"s":"Can","en":"I love sea animals!","tr":"Deniz hayvanlarını çok seviyorum!"}]},{"title":"Sea song","setting":"Ritimle tekrar et, deniz şarkısını söyle!","lines":[{"s":"Teacher","en":"Fish, fish, swim, swim, swim!","tr":"Balık, balık, yüz, yüz, yüz!"},{"s":"Kids","en":"Fish, fish, swim, swim, swim!","tr":"Balık, balık, yüz, yüz, yüz!"},{"s":"Teacher","en":"Crab, crab, walk to me!","tr":"Yengeç, yengeç, bana doğru yürü!"},{"s":"Kids","en":"Crab, crab, walk to me!","tr":"Yengeç, yengeç, bana doğru yürü!"},{"s":"Teacher","en":"Whale, whale, big and blue!","tr":"Balina, balina, büyük ve mavi!"},{"s":"Kids","en":"Whale, whale, big and blue!","tr":"Balina, balina, büyük ve mavi!"}]}],"reading":{"title":"Ali loves the sea","paras":[{"en":"Hi! I'm Ali. I love the sea. Fish swim fast in the blue water. A shark is big, but it is not mean. A dolphin likes to play with children. A crab walks sideways on the sand. A starfish is orange, and a turtle is very slow. Sea animals are amazing! Which one is your favourite?","tr":"Merhaba! Ben Ali. Denizi çok seviyorum. Balıklar mavi suda hızlı yüzer. Köpekbalığı büyüktür ama kötü değildir. Yunus çocuklarla oynamayı sever. Yengeç kumda yana doğru yürür. Denizyıldızı turuncudur, kaplumbağa ise çok yavaştır. Deniz hayvanları harika! Hangisi en sevdiğin?"}]},"vocab":[{"w":"fish","ipa":"/fɪʃ/","pos":"🐟","tr":"balık","ex":"The fish can swim.","exTr":"Balık yüzebilir."},{"w":"shark","ipa":"/ʃɑːk/","pos":"🦈","tr":"köpekbalığı","ex":"A shark is big.","exTr":"Köpekbalığı büyüktür."},{"w":"whale","ipa":"/weɪl/","pos":"🐳","tr":"balina","ex":"A whale is very big.","exTr":"Balina çok büyüktür."},{"w":"crab","ipa":"/kræb/","pos":"🦀","tr":"yengeç","ex":"The crab is red.","exTr":"Yengeç kırmızıdır."},{"w":"octopus","ipa":"/ˈɒktəpəs/","pos":"🐙","tr":"ahtapot","ex":"An octopus has eight arms.","exTr":"Ahtapotun sekiz kolu vardır."},{"w":"dolphin","ipa":"/ˈdɒlfɪn/","pos":"🐬","tr":"yunus","ex":"The dolphin is friendly.","exTr":"Yunus sevimlidir."},{"w":"turtle","ipa":"/ˈtɜːtl/","pos":"🐢","tr":"kaplumbağa","ex":"The turtle is slow.","exTr":"Kaplumbağa yavaştır."},{"w":"starfish","ipa":"/ˈstɑːfɪʃ/","pos":"🌟","tr":"denizyıldızı","ex":"A starfish is orange.","exTr":"Denizyıldızı turuncudur."}],"chunks":[{"en":"What is that?","tr":"Şu ne?"},{"en":"It's a…","tr":"Bu bir…"},{"en":"Look at this…!","tr":"Şu … bak!"},{"en":"Which one is your favourite?","tr":"Hangisi en sevdiğin?"}],"grammar":{"point":"This / that","tr":"'This' yakındaki, 'that' uzaktaki bir şeyi gösterir. Soru sorarken 'What is that?' (Şu ne?) deriz. Cevap verirken 'It's a…' kalıbını kullanırız.","examples":["What is that?","This is a shark.","That is a whale!","Is that a dolphin?"]},"questions":[{"q":"How does a crab move?","a":"It walks sideways."},{"q":"Is a shark mean?","a":"No, it's not mean."},{"q":"What colour is a starfish?","a":"Orange."}],"quiz":[{"q":"🦈 is a…","o":["shark","whale","dolphin"],"a":0,"why":""},{"q":"A turtle is very…","o":["fast","big","slow"],"a":2,"why":""},{"q":"🐙 has eight…","o":["legs","arms","fins"],"a":1,"why":""},{"q":"A crab walks…","o":["up","fast","sideways"],"a":2,"why":""}],"drills":[{"type":"Yerine koyma","prompt":"It's a shark.","cue":"dolphin","answer":"It's a dolphin."},{"type":"Soru yap","prompt":"That is a whale.","cue":"Is…?","answer":"Is that a whale?"},{"type":"Genişletme","prompt":"A turtle is slow.","cue":"very","answer":"A turtle is very slow."}],"sounds":[{"focus":"/θ/","tr":"Dilinin ucunu üst dişlerinin arasına koy ve hafifçe üfle. Türkçede bu ses yok; 'sin' ve 'sink' gibi 's' sesiyle söylersen anlam değişir.","pairs":["thin / sin","think / sink"]}],"mission":{"brief":"Claude, gizemli bir deniz canlısı olacak. Ona sorular sor ve kaç koluna sahip olduğunu ve nerede yaşadığını öğren.","persona":"Oscar, a friendly octopus. Speaks in short, cheerful sentences and asks the learner to guess. Hidden fact: he has eight arms and lives in a red rock by the sea. He only reveals where he lives when the learner asks 'Where…?'.","goal":"Oscar'ın kaç koluna sahip olduğunu ve nerede yaşadığını öğren.","opener":"Hi! I'm a sea animal. Guess who I am!"}},"KS1-024":{"objectives":["Ulaşım araçlarının adlarını söylemek","'by' ile nasıl gidildiğini anlatmak","'Shall we…?' ile öneri yapmak"],"dialogues":[{"title":"Let's go by train!","setting":"Zeynep ile babası gezi için karar veriyor.","lines":[{"s":"Dad","en":"Shall we go by car or by train?","tr":"Arabayla mı trenle mi gidelim?"},{"s":"Zeynep","en":"By train! I love trains!","tr":"Trenle! Trenleri çok seviyorum!"},{"s":"Dad","en":"OK. Look, here comes the train!","tr":"Tamam. Bak, tren geliyor!"},{"s":"Zeynep","en":"Choo choo! It's very long.","tr":"Tüt tüt! Çok uzun."},{"s":"Dad","en":"Let's get on!","tr":"Hadi binelim!"},{"s":"Zeynep","en":"Yay! Can I sit by the window?","tr":"Yaşasın! Pencerenin yanına oturabilir miyim?"}]},{"title":"My new bike","setting":"Parkta Leo ile Mia bisikletlerini konuşuyor.","lines":[{"s":"Leo","en":"I have a new bike! It's red.","tr":"Yeni bisikletim var! Kırmızı."},{"s":"Mia","en":"Wow! Can you ride it fast?","tr":"Vay! Hızlı sürebilir misin?"},{"s":"Leo","en":"Yes, I can! Watch me!","tr":"Evet, sürebilirim! Bana bak!"},{"s":"Mia","en":"Look at that big boat on the lake!","tr":"Göldeki şu büyük tekneye bak!"},{"s":"Leo","en":"And look at that plane in the sky!","tr":"Ve gökyüzündeki şu uçağa bak!"},{"s":"Mia","en":"Planes are fast. Bikes are fun!","tr":"Uçaklar hızlı. Bisikletler eğlenceli!"}]},{"title":"Vehicle chant","setting":"Ritimle tekrar et, araçların sesini çıkar!","lines":[{"s":"Teacher","en":"Car, car, beep, beep, beep!","tr":"Araba, araba, bip bip bip!"},{"s":"Kids","en":"Car, car, beep, beep, beep!","tr":"Araba, araba, bip bip bip!"},{"s":"Teacher","en":"Bus and truck go zoom, zoom, zoom!","tr":"Otobüs ve kamyon vınn vınn vınn!"},{"s":"Kids","en":"Bus and truck go zoom, zoom, zoom!","tr":"Otobüs ve kamyon vınn vınn vınn!"},{"s":"Teacher","en":"Boat, boat, splash, splash, splash!","tr":"Tekne, tekne, şırp şırp şırp!"},{"s":"Kids","en":"Boat, boat, splash, splash, splash!","tr":"Tekne, tekne, şırp şırp şırp!"}]}],"reading":{"title":"How we travel","paras":[{"en":"Hi! I'm Zeynep. I go to school by bus. My dad goes to work by car, and sometimes we take a taxi. My uncle rides a bike in the park. On holiday we fly by plane. The plane is very fast! My favourite is the train, because it is long and loud. Which transport do you like?","tr":"Merhaba! Ben Zeynep. Okula otobüsle giderim. Babam işe arabayla gider, bazen de taksi tutarız. Amcam parkta bisikletle gezer. Tatilde uçakla gideriz. Uçak çok hızlı! En sevdiğim tren, çünkü uzun ve gürültülü. Sen hangi ulaşımı seversin?"}]},"vocab":[{"w":"car","ipa":"/kɑː/","pos":"🚗","tr":"araba","ex":"Dad drives a car.","exTr":"Babam araba kullanır."},{"w":"bus","ipa":"/bʌs/","pos":"🚌","tr":"otobüs","ex":"I go to school by bus.","exTr":"Okula otobüsle giderim."},{"w":"train","ipa":"/treɪn/","pos":"🚆","tr":"tren","ex":"The train is long.","exTr":"Tren uzun."},{"w":"bike","ipa":"/baɪk/","pos":"🚲","tr":"bisiklet","ex":"I have a red bike.","exTr":"Kırmızı bir bisikletim var."},{"w":"plane","ipa":"/pleɪn/","pos":"✈️","tr":"uçak","ex":"We fly by plane.","exTr":"Uçakla uçarız."},{"w":"boat","ipa":"/bəʊt/","pos":"⛵","tr":"tekne","ex":"The boat is blue.","exTr":"Tekne mavi."},{"w":"truck","ipa":"/trʌk/","pos":"🚚","tr":"kamyon","ex":"The truck is big.","exTr":"Kamyon büyük."},{"w":"taxi","ipa":"/ˈtæksi/","pos":"🚕","tr":"taksi","ex":"We take a taxi.","exTr":"Taksi tutarız."}],"chunks":[{"en":"Shall we go by…?","tr":"…ile gidelim mi?"},{"en":"I go to school by bus.","tr":"Okula otobüsle giderim."},{"en":"Can you ride it fast?","tr":"Hızlı sürebilir misin?"},{"en":"Which one do you like?","tr":"Hangisini seversin?"}],"grammar":{"point":"by + vehicle","tr":"Bir aracla nasıl gittiğini 'by' ile anlatırsın: 'by bus' otobüsle demektir. 'by' den sonra 'a' ya da 'the' kullanılmaz.","examples":["I go to school by bus.","We go by train.","My dad goes to work by car.","We fly by plane."]},"questions":[{"q":"How does Zeynep go to school?","a":"By bus."},{"q":"How does her dad go to work?","a":"By car."},{"q":"Which transport is Zeynep's favourite?","a":"The train."}],"quiz":[{"q":"🚆 means…","o":["train","bus","truck"],"a":0,"why":""},{"q":"I go to school ___ bus.","o":["in","on","by"],"a":2,"why":""},{"q":"🚲 means…","o":["car","bike","boat"],"a":1,"why":""},{"q":"✈️ means…","o":["plane","boat","truck"],"a":0,"why":""}],"drills":[{"type":"Yerine koyma","prompt":"I go to school by bus.","cue":"train","answer":"I go to school by train."},{"type":"Soru yap","prompt":"We go by car.","cue":"Do you…?","answer":"Do you go by car?"},{"type":"Genişletme","prompt":"Look at that big boat!","cue":"add 'red'","answer":"Look at that big red boat!"}],"sounds":[{"focus":"/aɪ/","tr":"Türkçedeki 'ay' gibi iki ayrı hece değil, tek bir hızlı kaymadır: 'bike' kelimesini tek hece olarak söyle. 'back' kelimesindeki kısa 'a' ile karıştırma.","pairs":["bike / back","ride / rat"]}],"mission":{"brief":"Claude, arkadaşın Leo olacak ve parka gitmek istiyor. Ona 'Shall we go by…?' diye sor ve birlikte bir ulaşım aracı seçin.","persona":"Leo, a 7-year-old who wants to go to the park. Speaks in short, cheerful sentences and asks one question at a time. Hidden fact: his bike has a flat tyre, so he can't ride it today. He only tells this when the learner asks why they can't go by bike.","goal":"Leo'nun bisikletiyle neden gidemediğini öğren ve birlikte bir ulaşım aracı seç.","opener":"Hi! Let's go to the park. Shall we go by bike?"}},"KS1-025":{"objectives":["Evcil hayvanını İngilizce tanıtmak","'I have a…' kalıbını kullanmak","Hayvanları kısa sıfatlarla anlatmak"],"dialogues":[{"title":"Show me your pet","setting":"Ela, sınıf arkadaşı Deniz'e kedisinin fotoğrafını gösteriyor.","lines":[{"s":"Ela","en":"Look, Deniz! I have a pet.","tr":"Bak Deniz! Benim bir evcil hayvanım var."},{"s":"Deniz","en":"Wow! What is it?","tr":"Vay! Bu ne?"},{"s":"Ela","en":"It's a cat. Her name is Pamuk.","tr":"Bu bir kedi. Adı Pamuk."},{"s":"Deniz","en":"She's so cute! Is she white?","tr":"Çok tatlı! Beyaz mı?"},{"s":"Ela","en":"Yes, she is. She's very soft.","tr":"Evet, beyaz. Çok yumuşak."},{"s":"Deniz","en":"Can I pet her?","tr":"Onu sevebilir miyim?"},{"s":"Ela","en":"Sure! Be gentle, please.","tr":"Tabii! Lütfen nazik ol."}]},{"title":"Walk time","setting":"Akşam olmuş, baba Ela'yı köpekle yürüyüşe çıkarmaya hazırlıyor.","lines":[{"s":"Dad","en":"Ela, it's time for a walk!","tr":"Ela, yürüyüş zamanı!"},{"s":"Ela","en":"Yes! Where is Karabaş?","tr":"Evet! Karabaş nerede?"},{"s":"Dad","en":"He's under the table. He's sleeping.","tr":"Masanın altında. Uyuyor."},{"s":"Ela","en":"Karabaş, come here! Let's go to the park.","tr":"Karabaş, buraya gel! Hadi parka gidelim."},{"s":"Dad","en":"Good boy! Take the ball.","tr":"Aferin oğlum! Topu al."},{"s":"Ela","en":"He runs fast. He loves the park!","tr":"Çok hızlı koşuyor. Parkı çok seviyor!"},{"s":"Dad","en":"Let's go, everyone!","tr":"Hadi gidelim, herkes!"}]},{"title":"Pet song","setting":"Ritimle tekrar et, alkışla!","lines":[{"s":"Teacher","en":"I have a cat, a cat, a cat!","tr":"Bir kedim var, kedi, kedi, kedi!"},{"s":"Kids","en":"I have a cat, a cat, a cat!","tr":"Bir kedim var, kedi, kedi, kedi!"},{"s":"Teacher","en":"I have a dog, a dog, a dog!","tr":"Bir köpeğim var, köpek, köpek, köpek!"},{"s":"Kids","en":"I have a dog, a dog, a dog!","tr":"Bir köpeğim var, köpek, köpek, köpek!"},{"s":"Teacher","en":"Pets are fun! Clap, clap, clap!","tr":"Evcil hayvanlar çok eğlenceli! Alkışla, alkışla!"},{"s":"Kids","en":"Pets are fun! Clap, clap, clap!","tr":"Evcil hayvanlar çok eğlenceli! Alkışla, alkışla!"}]}],"reading":{"title":"Ela's pets","paras":[{"en":"Hi! I'm Ela. I have a cat. Her name is Pamuk. She is white and very soft. She likes milk and sleeps all day. I also have a fish. His name is Fino. He is orange! Every morning I give them food. Pamuk eats fast and Fino swims round and round. Pets are good friends!","tr":"Merhaba! Ben Ela. Bir kedim var. Adı Pamuk. Beyaz ve çok yumuşak. Sütü sever ve bütün gün uyur. Ayrıca bir balığım var. Adı Fino. Turuncu! Her sabah onlara yem veririm. Pamuk yemeğini hızlı yer, Fino ise küçük daireler çizerek yüzer. Evcil hayvanlar iyi arkadaştır!"}]},"vocab":[{"w":"cat","ipa":"/kæt/","pos":"🐱","tr":"kedi","ex":"The cat is sleeping.","exTr":"Kedi uyuyor."},{"w":"dog","ipa":"/dɒg/","pos":"🐶","tr":"köpek","ex":"Our dog is big.","exTr":"Köpeğimiz büyük."},{"w":"fish","ipa":"/fɪʃ/","pos":"🐟","tr":"balık","ex":"My fish is orange.","exTr":"Balığım turuncu."},{"w":"pet","ipa":"/pet/","pos":"🐾","tr":"evcil hayvan","ex":"I have a pet.","exTr":"Bir evcil hayvanım var."},{"w":"milk","ipa":"/mɪlk/","pos":"🥛","tr":"süt","ex":"The cat likes milk.","exTr":"Kedi sütü sever."},{"w":"food","ipa":"/fuːd/","pos":"🥣","tr":"yem, yiyecek","ex":"Give the dog some food.","exTr":"Köpeğe biraz yem ver."},{"w":"ball","ipa":"/bɔːl/","pos":"⚽","tr":"top","ex":"Take the ball.","exTr":"Topu al."},{"w":"park","ipa":"/pɑːk/","pos":"🌳","tr":"park","ex":"We walk in the park.","exTr":"Parkta yürüyoruz."}],"chunks":[{"en":"I have a…","tr":"Bir … var."},{"en":"What is it?","tr":"Bu ne?"},{"en":"She's so cute!","tr":"Çok tatlı!"},{"en":"Be gentle.","tr":"Nazik ol."}],"grammar":{"point":"I have a…","tr":"'I have a' bir şeye sahip olduğumuzu söyler ve Türkçedeki 'var' kelimesine benzer: 'Bir kedim var.' 'a' sözcüğü tek bir şey için kullanılır: 'a cat', 'a dog'.","examples":["I have a cat.","I have a dog.","I have a fish.","I have a pet."]},"questions":[{"q":"What is the cat's name?","a":"Her name is Pamuk."},{"q":"What colour is Fino?","a":"He is orange."},{"q":"Where is Karabaş?","a":"He's under the table."}],"quiz":[{"q":"🐱 is a…","o":["dog","cat","fish"],"a":1,"why":""},{"q":"I ___ a fish.","o":["have","is","am"],"a":0,"why":"'have' bir şeye sahip olmayı anlatır."},{"q":"Fino is…","o":["white","orange","big"],"a":1,"why":""},{"q":"Pamuk ___ milk.","o":["is","walk","likes"],"a":2,"why":""}],"drills":[{"type":"Yerine koyma","prompt":"I have a cat.","cue":"dog","answer":"I have a dog."},{"type":"Dönüştürme","prompt":"I have a dog.","cue":"two dogs","answer":"I have two dogs."},{"type":"Soru yap","prompt":"Fino is orange.","cue":"Is…?","answer":"Is Fino orange?"}],"sounds":[{"focus":"/æ/","tr":"Ağzını geniş aç, dilini aşağıda tut ve 'e' ile 'a' arasında bir ses çıkar. Türkçedeki 'kedi' kelimesindeki 'e' gibi kısa tutma; 'cat' sesi daha geniştir.","pairs":["cat / cut","bad / bed","hat / hut"]}],"mission":{"brief":"Görev: Kendi evcil hayvanını İngilizce tanıt. Claude, arkadaşın Leo olacak ve sana evcil hayvanın hakkında basit sorular soracak.","persona":"Leo, a cheerful 8-year-old who loves animals. Uses very short, simple sentences and lots of encouragement. Asks one question at a time. Hidden fact: Leo has a turtle named Tek, but he only mentions it when the learner asks what pets Leo has.","goal":"En az üç cümle kur: 'I have a…', 'It's…' ve 'Its name is…'.","opener":"Hi! I'm Leo. Do you have a pet?"}},"KS1-026":{"objectives":["Sabah rutinini İngilizce anlatmak","'Brush your teeth' gibi kısa emirleri anlamak","Kısa bir ritimle sabah cümlelerini tekrar etmek"],"dialogues":[{"title":"Good morning, Kerem!","setting":"Sabah, annesi Kerem'i uyandırıyor.","lines":[{"s":"Mum","en":"Good morning, Kerem! Time to wake up.","tr":"Günaydın Kerem! Uyanma zamanı."},{"s":"Kerem","en":"Good morning, Mum. I'm up!","tr":"Günaydın anne. Uyandım!"},{"s":"Mum","en":"Brush your teeth, please.","tr":"Lütfen dişlerini fırçala."},{"s":"Kerem","en":"OK! Then breakfast?","tr":"Tamam! Sonra kahvaltı mı?"},{"s":"Mum","en":"Yes! We have bread and eggs.","tr":"Evet! Ekmek ve yumurta var."},{"s":"Kerem","en":"Yummy! I love breakfast.","tr":"Mmm, lezzetli! Kahvaltıyı çok severim."}]},{"title":"The bus is here","setting":"Servis kapının önünde bekliyor, Ela ayakkabılarını arıyor.","lines":[{"s":"Ela","en":"Dad, where are my shoes?","tr":"Baba, ayakkabılarım nerede?"},{"s":"Dad","en":"They are under the bed.","tr":"Yatağın altında."},{"s":"Ela","en":"Got them! I'm ready.","tr":"Buldum! Hazırım."},{"s":"Dad","en":"Let's go. The bus is here!","tr":"Hadi gidelim. Servis geldi!"},{"s":"Ela","en":"Bye, Dad! Have a nice day.","tr":"Hoşça kal baba! İyi günler."},{"s":"Dad","en":"Bye, Ela. Go to school!","tr":"Hoşça kal Ela. Okula git!"}]},{"title":"Morning song","setting":"Ritimle tekrar et, alkışla!","lines":[{"s":"Teacher","en":"Wake up, wake up, it's morning!","tr":"Uyan, uyan, sabah oldu!"},{"s":"Kids","en":"Wake up, wake up, it's morning!","tr":"Uyan, uyan, sabah oldu!"},{"s":"Teacher","en":"Brush your teeth, brush your teeth!","tr":"Dişlerini fırçala, dişlerini fırçala!"},{"s":"Kids","en":"Brush your teeth, brush your teeth!","tr":"Dişlerini fırçala, dişlerini fırçala!"},{"s":"Teacher","en":"Shoes on, bus here, school time!","tr":"Ayakkabılar giyildi, servis geldi, okul zamanı!"},{"s":"Kids","en":"Shoes on, bus here, school time!","tr":"Ayakkabılar giyildi, servis geldi, okul zamanı!"}]}],"reading":{"title":"My morning","paras":[{"en":"Hi! I'm Kerem. Every morning I wake up at seven. Then I brush my teeth and wash my face. I have breakfast with my family. I like bread and honey. After that, I put on my shoes and go to the bus. The bus takes me to school. Morning is my favourite time!","tr":"Merhaba! Ben Kerem. Her sabah saat yedide uyanırım. Sonra dişlerimi fırçalar ve yüzümü yıkarım. Ailemle birlikte kahvaltı yaparım. Ekmek ve bal severim. Ondan sonra ayakkabılarımı giyer ve servise giderim. Servis beni okula götürür. Sabah en sevdiğim zamandır!"}]},"vocab":[{"w":"morning","ipa":"/ˈmɔːnɪŋ/","pos":"🌅","tr":"sabah","ex":"Good morning!","exTr":"Günaydın!"},{"w":"wake up","ipa":"/weɪk ʌp/","pos":"⏰","tr":"uyanmak","ex":"I wake up at seven.","exTr":"Saat yedide uyanırım."},{"w":"teeth","ipa":"/tiːθ/","pos":"🦷","tr":"dişler","ex":"Brush your teeth.","exTr":"Dişlerini fırçala."},{"w":"breakfast","ipa":"/ˈbrekfəst/","pos":"🥣","tr":"kahvaltı","ex":"I have breakfast with Mum.","exTr":"Annemle kahvaltı yaparım."},{"w":"bread","ipa":"/bred/","pos":"🍞","tr":"ekmek","ex":"I like bread.","exTr":"Ekmeği severim."},{"w":"shoes","ipa":"/ʃuːz/","pos":"👟","tr":"ayakkabılar","ex":"Where are my shoes?","exTr":"Ayakkabılarım nerede?"},{"w":"bus","ipa":"/bʌs/","pos":"🚌","tr":"servis, otobüs","ex":"The bus is here!","exTr":"Servis geldi!"},{"w":"school","ipa":"/skuːl/","pos":"🏫","tr":"okul","ex":"I go to school.","exTr":"Okula giderim."}],"chunks":[{"en":"Wake up!","tr":"Uyan!"},{"en":"Brush your teeth.","tr":"Dişlerini fırçala."},{"en":"Time to…","tr":"… zamanı."},{"en":"Have a nice day!","tr":"İyi günler!"}],"grammar":{"point":"I + verb (daily routine)","tr":"Her gün yaptığımız işleri anlatırken 'I' ile fiili yan yana kullanırız: 'I wake up', 'I eat'. Fiil aynı kalır ve cümlenin sonuna bir ek gelmez.","examples":["I wake up at seven.","I brush my teeth.","I eat breakfast.","I go to school."]},"questions":[{"q":"What time does Kerem wake up?","a":"At seven."},{"q":"What does Kerem have for breakfast?","a":"Bread and honey."},{"q":"What does Kerem put on after breakfast?","a":"His shoes."}],"quiz":[{"q":"🌅 is…","o":["morning","night","bus"],"a":0,"why":""},{"q":"I ___ my teeth.","o":["brush","have","go"],"a":0,"why":""},{"q":"Ela's shoes are ___ the bed.","o":["bus","under","bread"],"a":1,"why":""},{"q":"I go to ___.","o":["bread","shoes","school"],"a":2,"why":""}],"drills":[{"type":"Yerine koyma","prompt":"I wake up at seven.","cue":"eight","answer":"I wake up at eight."},{"type":"Dönüştürme","prompt":"I eat bread.","cue":"Do you…?","answer":"Do you eat bread?"},{"type":"Soru yap","prompt":"Ela's shoes are under the bed.","cue":"Where…?","answer":"Where are Ela's shoes?"}],"sounds":[{"focus":"/θ/","tr":"Dilini üst dişlerinin ucuna hafifçe koy ve yumuşakça üfle. Türkçede bu ses yok; 's' gibi söylersen 'teeth' 'tees' gibi duyulur.","pairs":["think / sink","three / free","teeth / tease"]}],"mission":{"brief":"Görev: Sabah rutinini İngilizce anlat. Claude, arkadaşın Leo olacak ve sabah ne yaptığını soracak.","persona":"Leo, a cheerful 8-year-old who wakes up very late on school days. Uses short, simple sentences and lots of encouragement. Asks one question at a time. Hidden fact: Leo goes to school by train, not by bus, but he only says so when the learner asks how he gets to school.","goal":"En az üç sabah işini 'I…' ile İngilizce anlat.","opener":"Hi! I'm Leo. What do you do in the morning?"}},"KS1-027":{"objectives":["Yatma vaktini İngilizce söylemek","'Can you…?' ile rica etmek","İyi geceler dileğini İngilizce söylemek"],"dialogues":[{"title":"Time for bed","setting":"Akşam, annesi Ela'yı yatmaya hazırlıyor.","lines":[{"s":"Mum","en":"It's time for bed, Ela.","tr":"Ela, yatma zamanı."},{"s":"Ela","en":"But I'm not tired!","tr":"Ama hiç yorgun değilim!"},{"s":"Mum","en":"Put on your pyjamas, please.","tr":"Lütfen pijamalarını giy."},{"s":"Ela","en":"OK. Where is my teddy?","tr":"Tamam. Oyuncak ayım nerede?"},{"s":"Mum","en":"He's on the bed. Here you are.","tr":"Yatakta. Buyur."},{"s":"Ela","en":"Thank you! Can you read a story?","tr":"Teşekkürler! Bana bir masal okur musun?"},{"s":"Mum","en":"Yes, one short story.","tr":"Evet, tek bir kısa masal."}]},{"title":"Good night, Ela","setting":"Baba, Ela'nın odasındaki ışığı kapatmak üzere.","lines":[{"s":"Dad","en":"Good night, my little star.","tr":"İyi geceler, küçük yıldızım."},{"s":"Ela","en":"Can you turn off the light, Dad?","tr":"Işığı kapatır mısın baba?"},{"s":"Dad","en":"Yes. The room is dark now.","tr":"Tamam. Oda artık karanlık."},{"s":"Ela","en":"I see the moon. It's big!","tr":"Ay'ı görüyorum. Çok büyük!"},{"s":"Dad","en":"Yes! The moon is shining.","tr":"Evet! Ay parlıyor."},{"s":"Ela","en":"Good night, Dad. Sweet dreams!","tr":"İyi geceler baba. Tatlı rüyalar!"},{"s":"Dad","en":"Sweet dreams, Ela. I love you!","tr":"Tatlı rüyalar Ela. Seni seviyorum!"}]},{"title":"Sleep song","setting":"Ritimle tekrar et, alkışla!","lines":[{"s":"Teacher","en":"Close your eyes, it's night!","tr":"Gözlerini kapat, gece oldu!"},{"s":"Kids","en":"Close your eyes, it's night!","tr":"Gözlerini kapat, gece oldu!"},{"s":"Teacher","en":"Teddy, teddy, sleep tight.","tr":"Oyuncak ayım, oyuncak ayım, iyi uyu."},{"s":"Kids","en":"Teddy, teddy, sleep tight.","tr":"Oyuncak ayım, oyuncak ayım, iyi uyu."},{"s":"Teacher","en":"Good night, good night, sleep tight!","tr":"İyi geceler, iyi geceler, iyi uyu!"},{"s":"Kids","en":"Good night, good night, sleep tight!","tr":"İyi geceler, iyi geceler, iyi uyu!"}]}],"reading":{"title":"Bedtime at my house","paras":[{"en":"Hi! I'm Ela. At night, I go to bed at eight. First, I put on my pyjamas. Then I brush my teeth. My teddy sleeps with me. Mum reads a short story. The room is dark, and I see the moon through the window. It is big and bright! I close my eyes and smile. Good night, everyone. Sweet dreams!","tr":"Merhaba! Ben Ela. Geceleri saat sekizde yatağa giderim. Önce pijamalarımı giyerim. Sonra dişlerimi fırçalarım. Oyuncak ayım benimle uyur. Annem kısa bir masal okur. Oda karanlık ve pencereden ayı görüyorum. Ay çok büyük ve parlak! Gözlerimi kapatır ve gülümserim. İyi geceler herkese. Tatlı rüyalar!"}]},"vocab":[{"w":"bed","ipa":"/bed/","pos":"🛏","tr":"yatak","ex":"It's time for bed.","exTr":"Yatma zamanı."},{"w":"night","ipa":"/naɪt/","pos":"🌙","tr":"gece","ex":"It's night now.","exTr":"Şimdi gece."},{"w":"pyjamas","ipa":"/pəˈdʒɑːməz/","pos":"👕","tr":"pijama","ex":"I wear my pyjamas.","exTr":"Pijamamı giyerim."},{"w":"teddy","ipa":"/ˈtedi/","pos":"🧸","tr":"oyuncak ayı","ex":"My teddy is soft.","exTr":"Oyuncak ayım yumuşak."},{"w":"story","ipa":"/ˈstɔːri/","pos":"📖","tr":"masal, hikâye","ex":"Mum reads a story.","exTr":"Annem bir masal okur."},{"w":"light","ipa":"/laɪt/","pos":"💡","tr":"ışık","ex":"Turn off the light.","exTr":"Işığı kapat."},{"w":"moon","ipa":"/muːn/","pos":"🌕","tr":"ay","ex":"The moon is big.","exTr":"Ay çok büyük."},{"w":"dark","ipa":"/dɑːk/","pos":"🌑","tr":"karanlık","ex":"The room is dark.","exTr":"Oda karanlık."}],"chunks":[{"en":"Time for bed.","tr":"Yatma zamanı."},{"en":"Sweet dreams!","tr":"Tatlı rüyalar!"},{"en":"Can you read a story?","tr":"Bana bir masal okur musun?"},{"en":"Good night!","tr":"İyi geceler!"}],"grammar":{"point":"Can you…? (asking politely)","tr":"Birinden bir şey yapmasını rica ederken 'Can you…?' kullanırız. Sonuna 'please' eklersek cümle daha nazik olur.","examples":["Can you read a story?","Can you turn off the light?","Can you help me?","Can you close the door, please?"]},"questions":[{"q":"What time does Ela go to bed?","a":"At eight."},{"q":"What does Mum read?","a":"A short story."},{"q":"What does Ela see through the window?","a":"The moon."}],"quiz":[{"q":"🌙 means…","o":["night","morning","bus"],"a":0,"why":""},{"q":"'Can you ___ the light?'","o":["teddy","turn off","pyjamas"],"a":1,"why":""},{"q":"The room is ___.","o":["dark","bread","school"],"a":0,"why":""},{"q":"Sweet ___!","o":["moon","light","dreams"],"a":2,"why":""}],"drills":[{"type":"Yerine koyma","prompt":"It's time for bed.","cue":"breakfast","answer":"It's time for breakfast."},{"type":"Dönüştürme","prompt":"Turn off the light.","cue":"Can you…?","answer":"Can you turn off the light?"},{"type":"Soru yap","prompt":"The moon is big.","cue":"Is…?","answer":"Is the moon big?"}],"sounds":[{"focus":"/aɪ/","tr":"'a' sesinden başla ve hızla 'i' sesine doğru kaydır. Türkçede iki ayrı ses gibi söylersen 'night' 'net' gibi kısa kalır; tek bir kayan ses olarak söyle.","pairs":["night / net","light / let"]}],"mission":{"brief":"Görev: Yatma saatini ve gece rutinini İngilizce anlat. Claude, arkadaşın Leo olacak ve sana gece neler yaptığını soracak.","persona":"Leo, a sleepy but friendly 8-year-old. Speaks in very short sentences and asks one question at a time. Hidden fact: Leo has a night light shaped like a dinosaur, which he only mentions when the learner asks what he can see in his room at night.","goal":"En az üç gece işini İngilizce anlat ve bir kez 'Can you…?' ile rica et.","opener":"Hi! I'm Leo. What time do you go to bed?"}},"KS1-028":{"objectives":["Dört mevsimi İngilizce söylemek","'It's…' ile hava durumunu anlatmak","Mevsimler hakkında kısa cümleler kurmak"],"dialogues":[{"title":"It's snowing!","setting":"Kış günü, Ela ve Deniz pencereden kara bakıyor.","lines":[{"s":"Deniz","en":"Look! It's snowing!","tr":"Bak! Kar yağıyor!"},{"s":"Ela","en":"It's winter now. It's very cold!","tr":"Şimdi kış. Çok soğuk!"},{"s":"Deniz","en":"Let's make a snowman!","tr":"Hadi bir kardan adam yapalım!"},{"s":"Ela","en":"Yes! Put on your hat and gloves.","tr":"Evet! Şapkanı ve eldivenlerini tak."},{"s":"Deniz","en":"I love winter!","tr":"Kışı çok seviyorum!"},{"s":"Ela","en":"Me too. But I like summer more.","tr":"Ben de. Ama yazı daha çok seviyorum."}]},{"title":"Is it going to rain?","setting":"Yaz tatilinde, bahçede bir sıcak gün.","lines":[{"s":"Mum","en":"It's very hot today!","tr":"Bugün çok sıcak!"},{"s":"Ela","en":"It's summer! Let's go to the pool.","tr":"Yaz! Havuza gidelim."},{"s":"Mum","en":"Good idea. Drink some water first.","tr":"İyi fikir. Önce biraz su iç."},{"s":"Ela","en":"Is it going to rain?","tr":"Yağmur yağacak mı?"},{"s":"Mum","en":"No, the sun is shining.","tr":"Hayır, güneş parlıyor."},{"s":"Ela","en":"Yay! Sunny days are the best.","tr":"Yaşasın! Güneşli günler en iyisi."}]},{"title":"Four seasons song","setting":"Ritimle tekrar et, alkışla!","lines":[{"s":"Teacher","en":"Spring, summer, autumn, winter!","tr":"İlkbahar, yaz, sonbahar, kış!"},{"s":"Kids","en":"Spring, summer, autumn, winter!","tr":"İlkbahar, yaz, sonbahar, kış!"},{"s":"Teacher","en":"Flowers, sun, leaves, snow!","tr":"Çiçekler, güneş, yapraklar, kar!"},{"s":"Kids","en":"Flowers, sun, leaves, snow!","tr":"Çiçekler, güneş, yapraklar, kar!"},{"s":"Teacher","en":"Four seasons, one year! Hooray!","tr":"Dört mevsim, bir yıl! Yaşasın!"},{"s":"Kids","en":"Four seasons, one year! Hooray!","tr":"Dört mevsim, bir yıl! Yaşasın!"}]}],"reading":{"title":"The four seasons","paras":[{"en":"Hi! I'm Deniz. There are four seasons in a year. In spring, flowers grow and the birds sing. In summer, it is hot and sunny. In autumn, the leaves fall from the trees. In winter, it is cold and snow falls. I love every season. Each one is special. My favourite is spring!","tr":"Merhaba! Ben Deniz. Bir yılda dört mevsim var. İlkbaharda çiçekler açar ve kuşlar öter. Yazın hava sıcak ve güneşli olur. Sonbaharda yapraklar ağaçlardan düşer. Kışın hava soğuk olur ve kar yağar. Her mevsimi seviyorum. Her biri özeldir. En sevdiğim mevsim ilkbahar!"}]},"vocab":[{"w":"spring","ipa":"/sprɪŋ/","pos":"🌷","tr":"ilkbahar","ex":"Flowers grow in spring.","exTr":"İlkbaharda çiçekler büyür."},{"w":"summer","ipa":"/ˈsʌmə/","pos":"☀️","tr":"yaz","ex":"It's hot in summer.","exTr":"Yazın hava sıcak."},{"w":"autumn","ipa":"/ˈɔːtəm/","pos":"🍂","tr":"sonbahar","ex":"Leaves fall in autumn.","exTr":"Sonbaharda yapraklar düşer."},{"w":"winter","ipa":"/ˈwɪntə/","pos":"❄️","tr":"kış","ex":"It's cold in winter.","exTr":"Kışın hava soğuk."},{"w":"rain","ipa":"/reɪn/","pos":"🌧️","tr":"yağmur","ex":"Is it going to rain?","exTr":"Yağmur yağacak mı?"},{"w":"snow","ipa":"/snəʊ/","pos":"⛄","tr":"kar","ex":"I love the snow.","exTr":"Karı çok severim."},{"w":"hot","ipa":"/hɒt/","pos":"🥵","tr":"sıcak","ex":"It's very hot today.","exTr":"Bugün çok sıcak."},{"w":"cold","ipa":"/kəʊld/","pos":"🥶","tr":"soğuk","ex":"The water is cold.","exTr":"Su soğuk."}],"chunks":[{"en":"It's snowing!","tr":"Kar yağıyor!"},{"en":"Let's make a snowman!","tr":"Hadi bir kardan adam yapalım!"},{"en":"Is it going to rain?","tr":"Yağmur yağacak mı?"},{"en":"I love…","tr":"… severim."}],"grammar":{"point":"It's + weather","tr":"Hava durumunu anlatırken cümleyi 'It's' ile başlatırız: 'It's hot' yani 'Hava sıcak'. 'It's', 'It is' kısaltmasıdır ve hava için kullanılır.","examples":["It's hot today.","It's cold in winter.","It's snowing.","It's sunny in summer."]},"questions":[{"q":"Which season is cold?","a":"Winter."},{"q":"What falls from the trees in autumn?","a":"Leaves."},{"q":"What is Deniz's favourite season?","a":"Spring."}],"quiz":[{"q":"❄️ is…","o":["summer","winter","spring"],"a":1,"why":""},{"q":"It's very ___ today! (The sun is out.)","o":["hot","cold","rain"],"a":0,"why":""},{"q":"Leaves fall in ___.","o":["spring","summer","autumn"],"a":2,"why":""},{"q":"Is it going to ___?","o":["rain","hot","spring"],"a":0,"why":""}],"drills":[{"type":"Yerine koyma","prompt":"It's hot in summer.","cue":"winter","answer":"It's cold in winter."},{"type":"Dönüştürme","prompt":"It's snowing.","cue":"rain","answer":"It's raining."},{"type":"Soru yap","prompt":"It's cold today.","cue":"Is…?","answer":"Is it cold today?"}],"sounds":[{"focus":"/ɪ/ ve /iː/","tr":"Kısa /ɪ/ sesi Türkçedeki kısa 'i'ye yakındır; dilini gevşek tut. Uzun /iː/ sesinde dudaklarını gerip sesi uzat. 'ship' ile 'sheep' arasındaki farkı bu şekilde duy.","pairs":["ship / sheep","hit / heat","sit / seat"]}],"mission":{"brief":"Görev: Bulunduğun yerdeki hava durumunu ve sevdiğin mevsimi İngilizce anlat. Claude, arkadaşın Leo olacak ve sana hava hakkında sorular soracak.","persona":"Leo, a curious 8-year-old who loves weather. Uses short sentences and asks one question at a time. Hidden fact: Leo's favourite season is autumn because he loves jumping into piles of leaves, but he only says why when the learner asks what he likes to do outside.","goal":"En az üç hava durumu ya da mevsim cümlesi kur: 'It's…' ve 'I love…'.","opener":"Hi! I'm Leo. What is the weather like today?"}},"KS1-029":{"objectives":["Ev işlerini İngilizce söylemek","'Can I help?' kalıbını kullanmak","Nazik emir cümleleri kurmak"],"dialogues":[{"title":"Can I help?","setting":"Akşam yemeği hazırlanıyor, Kerem mutfakta annesine yardım etmek istiyor.","lines":[{"s":"Kerem","en":"Mum, can I help?","tr":"Anne, yardım edebilir miyim?"},{"s":"Mum","en":"Yes, please! Set the table.","tr":"Evet lütfen! Masayı hazırla."},{"s":"Kerem","en":"OK! Where are the plates?","tr":"Tamam! Tabaklar nerede?"},{"s":"Mum","en":"They are in the kitchen.","tr":"Mutfakta."},{"s":"Kerem","en":"Got them! Here you are.","tr":"Buldum! İşte burada."},{"s":"Mum","en":"Thank you, Kerem. You are a big help!","tr":"Teşekkür ederim Kerem. Çok büyük bir yardımın oldu!"}]},{"title":"Clean the room","setting":"Cumartesi sabahı, baba Ela'ya odasını toplamasını söylüyor.","lines":[{"s":"Dad","en":"Ela, clean your room, please.","tr":"Ela, lütfen odanı temizle."},{"s":"Ela","en":"OK, Dad. There are so many toys!","tr":"Tamam baba. Çok fazla oyuncak var!"},{"s":"Dad","en":"Put the toys in the box.","tr":"Oyuncakları kutuya koy."},{"s":"Ela","en":"Can you help me?","tr":"Bana yardım eder misin?"},{"s":"Dad","en":"Yes! I'll take the books.","tr":"Evet! Kitapları ben alırım."},{"s":"Ela","en":"Thank you! Now the room is clean.","tr":"Teşekkürler! Artık oda temiz."}]},{"title":"Helping song","setting":"Ritimle tekrar et, alkışla!","lines":[{"s":"Teacher","en":"Help, help, help at home!","tr":"Yardım et, yardım et, evde yardım et!"},{"s":"Kids","en":"Help, help, help at home!","tr":"Yardım et, yardım et, evde yardım et!"},{"s":"Teacher","en":"Tidy, tidy, tidy up!","tr":"Topla, topla, toparla!"},{"s":"Kids","en":"Tidy, tidy, tidy up!","tr":"Topla, topla, toparla!"},{"s":"Teacher","en":"I can help! I can help!","tr":"Yardım edebilirim! Yardım edebilirim!"},{"s":"Kids","en":"I can help! I can help!","tr":"Yardım edebilirim! Yardım edebilirim!"}]}],"reading":{"title":"Kerem helps at home","paras":[{"en":"Hi! I'm Kerem. I help at home every day. On Monday, I set the table for dinner. On Tuesday, I put the bin outside. On Friday, I wash the dishes too. On Saturday, I clean my room and tidy up my toys. My mum says I am a big help. Helping is fun, and it makes me happy!","tr":"Merhaba! Ben Kerem. Her gün evde yardım ederim. Pazartesi günü akşam yemeği için masayı hazırlarım. Salı günü çöp kutusunu dışarı çıkarırım. Cuma günü bulaşıkları da yıkarım. Cumartesi günü odamı temizler ve oyuncaklarımı toplarım. Annem benim çok iyi bir yardımcı olduğumu söylüyor. Yardım etmek eğlenceli ve beni mutlu ediyor!"}]},"vocab":[{"w":"help","ipa":"/help/","pos":"🤝","tr":"yardım etmek","ex":"Can you help me?","exTr":"Bana yardım eder misin?"},{"w":"clean","ipa":"/kliːn/","pos":"🧹","tr":"temizlemek","ex":"I clean my room.","exTr":"Odamı temizlerim."},{"w":"dishes","ipa":"/ˈdɪʃɪz/","pos":"🍽","tr":"bulaşıklar","ex":"I wash the dishes.","exTr":"Bulaşıkları yıkarım."},{"w":"table","ipa":"/ˈteɪbl/","pos":"🪑","tr":"masa","ex":"Set the table, please.","exTr":"Lütfen masayı hazırla."},{"w":"bin","ipa":"/bɪn/","pos":"🗑","tr":"çöp kutusu","ex":"Put it in the bin.","exTr":"Onu çöp kutusuna koy."},{"w":"room","ipa":"/ruːm/","pos":"🚪","tr":"oda","ex":"My room is clean.","exTr":"Odam temiz."},{"w":"toys","ipa":"/tɔɪz/","pos":"🧸","tr":"oyuncaklar","ex":"Put the toys in the box.","exTr":"Oyuncakları kutuya koy."},{"w":"tidy","ipa":"/ˈtaɪdi/","pos":"🧺","tr":"toparlamak","ex":"Tidy up your room.","exTr":"Odanı topla."}],"chunks":[{"en":"Can I help?","tr":"Yardım edebilir miyim?"},{"en":"Can you help me?","tr":"Bana yardım eder misin?"},{"en":"Set the table, please.","tr":"Lütfen masayı hazırla."},{"en":"You are a big help!","tr":"Çok büyük bir yardımcısın!"}],"grammar":{"point":"Commands with 'please'","tr":"Birine bir şey yapmasını söylemek için cümleyi fiille başlatırız: 'Clean', 'Help', 'Set'. Nazik olmak için cümlenin sonuna 'please' ekleriz.","examples":["Clean your room.","Set the table, please.","Put the toys in the box.","Help me, please."]},"questions":[{"q":"What does Kerem do on Monday?","a":"He sets the table for dinner."},{"q":"Where does Kerem put the bin?","a":"Outside."},{"q":"What does Kerem do on Saturday?","a":"He cleans his room and tidies up his toys."}],"quiz":[{"q":"🧹 means…","o":["clean","help","table"],"a":0,"why":""},{"q":"Can you ___ me?","o":["bin","help","room"],"a":1,"why":""},{"q":"Set the ___.","o":["toys","bin","table"],"a":2,"why":""},{"q":"Put the toys in the ___.","o":["box","help","clean"],"a":0,"why":""}],"drills":[{"type":"Yerine koyma","prompt":"Set the table, please.","cue":"clean","answer":"Clean the table, please."},{"type":"Dönüştürme","prompt":"You help me.","cue":"Make it a command","answer":"Help me."},{"type":"Soru yap","prompt":"Kerem is a big help.","cue":"Is…?","answer":"Is Kerem a big help?"}],"sounds":[{"focus":"/w/ ve /v/","tr":"/w/ sesinde dudaklarını yuvarla ve hemen aç; /v/ sesinde alt dudağını üst dişlerine değdir. Türkçedeki 'v' gibi söylersen 'wet' 'vet' gibi duyulur.","pairs":["wet / vet","west / vest","wine / vine"]}],"mission":{"brief":"Görev: Evde yaptığın yardım işlerini İngilizce anlat. Claude, arkadaşın Leo olacak ve sana ev işleri hakkında sorular soracak.","persona":"Leo, a helpful 9-year-old who is always busy. Uses short sentences and asks one question at a time. Hidden fact: Leo's weekly job is feeding his fish every Sunday, which he only mentions when the learner asks about his weekly jobs.","goal":"En az üç ev işini 'I…' ile İngilizce anlat ve bir kez 'Can I help?' diye sor.","opener":"Hi! I'm Leo. Do you help at home?"}},"KS1-030":{"objectives":["En yakın arkadaşını İngilizce tanıtmak","'She likes…' kalıbını kullanmak","Arkadaşlık hakkında kısa cümleler kurmak"],"dialogues":[{"title":"Who is your best friend?","setting":"Teneffüste, Mert Ela'ya en yakın arkadaşını soruyor.","lines":[{"s":"Mert","en":"Ela, who is your best friend?","tr":"Ela, en iyi arkadaşın kim?"},{"s":"Ela","en":"My best friend is Defne. She is funny!","tr":"En iyi arkadaşım Defne. Çok komik!"},{"s":"Mert","en":"What does she like?","tr":"Neleri sever?"},{"s":"Ela","en":"She likes drawing and music. She is kind, too.","tr":"Resim yapmayı ve müziği sever. Ayrıca çok naziktir."},{"s":"Mert","en":"Is she in your class?","tr":"Senin sınıfında mı?"},{"s":"Ela","en":"Yes! We play together at break.","tr":"Evet! Teneffüste birlikte oynarız."},{"s":"Mert","en":"That's nice. I'd like to meet her!","tr":"Güzel. Onunla tanışmak isterim!"}]},{"title":"Let's share the ball","setting":"Parkta, Ela ve Defne futbol oynamaya hazırlanıyor.","lines":[{"s":"Defne","en":"Ela, let's play football!","tr":"Ela, hadi futbol oynayalım!"},{"s":"Ela","en":"Great! Let's share the ball.","tr":"Harika! Topu paylaşalım."},{"s":"Defne","en":"You are a good friend.","tr":"Sen iyi bir arkadaşsın."},{"s":"Ela","en":"So are you! You are happy and kind.","tr":"Sen de öylesin! Mutlu ve naziksin."},{"s":"Defne","en":"Thank you! Let's play again tomorrow.","tr":"Teşekkürler! Yarın yine oynayalım."},{"s":"Ela","en":"Yes, see you tomorrow!","tr":"Evet, yarın görüşürüz!"}]},{"title":"Friendship song","setting":"Ritimle tekrar et, alkışla!","lines":[{"s":"Teacher","en":"A friend is kind, a friend is fun!","tr":"Bir arkadaş naziktir, bir arkadaş eğlencelidir!"},{"s":"Kids","en":"A friend is kind, a friend is fun!","tr":"Bir arkadaş naziktir, bir arkadaş eğlencelidir!"},{"s":"Teacher","en":"Share your toys and say hi!","tr":"Oyuncaklarını paylaş ve merhaba de!"},{"s":"Kids","en":"Share your toys and say hi!","tr":"Oyuncaklarını paylaş ve merhaba de!"},{"s":"Teacher","en":"Best friends, happy friends!","tr":"En iyi arkadaşlar, mutlu arkadaşlar!"},{"s":"Kids","en":"Best friends, happy friends!","tr":"En iyi arkadaşlar, mutlu arkadaşlar!"}]}],"reading":{"title":"My best friend","paras":[{"en":"Hi! I'm Ela. My best friend is Defne. She is funny and she makes me smile. She likes drawing, and I like music. We play football at break time. She is very kind. When I am sad, she helps me. When she is happy, I am happy too. I'm lucky to have a friend like her!","tr":"Merhaba! Ben Ela. En iyi arkadaşım Defne. Çok komik ve beni güldürür. Resim yapmayı sever, ben ise müziği severim. Teneffüste birlikte futbol oynarız. Çok naziktir. Ben üzgün olduğumda bana yardım eder. O mutlu olduğunda ben de mutlu olurum. Onun gibi bir arkadaşım olduğu için şanslıyım!"}]},"vocab":[{"w":"friend","ipa":"/frend/","pos":"👫","tr":"arkadaş","ex":"She is my friend.","exTr":"O benim arkadaşım."},{"w":"best","ipa":"/best/","pos":"🏆","tr":"en iyi","ex":"Defne is my best friend.","exTr":"Defne benim en iyi arkadaşım."},{"w":"funny","ipa":"/ˈfʌni/","pos":"😂","tr":"komik","ex":"You are very funny!","exTr":"Çok komiksin!"},{"w":"play","ipa":"/pleɪ/","pos":"🎮","tr":"oynamak","ex":"We play at break time.","exTr":"Teneffüste oynarız."},{"w":"share","ipa":"/ʃeə/","pos":"🤲","tr":"paylaşmak","ex":"Let's share the ball.","exTr":"Topu paylaşalım."},{"w":"kind","ipa":"/kaɪnd/","pos":"💛","tr":"nazik","ex":"He is very kind.","exTr":"O çok nazik."},{"w":"happy","ipa":"/ˈhæpi/","pos":"😊","tr":"mutlu","ex":"I am happy today.","exTr":"Bugün mutluyum."},{"w":"sad","ipa":"/sæd/","pos":"😢","tr":"üzgün","ex":"Don't be sad.","exTr":"Üzülme."}],"chunks":[{"en":"She is my best friend.","tr":"O benim en iyi arkadaşım."},{"en":"She likes…","tr":"O … sever."},{"en":"Let's play together!","tr":"Hadi birlikte oynayalım!"},{"en":"Let's share the ball.","tr":"Topu paylaşalım."}],"grammar":{"point":"He / She + likes","tr":"Birini anlatırken (he, she) 'like' fiiline 's' ekleriz: 'likes'. 'I' ve 'you' ile 's' kullanılmaz.","examples":["She likes drawing.","He likes football.","She likes music.","My friend likes to play."]},"questions":[{"q":"Who is Ela's best friend?","a":"Defne."},{"q":"What does Ela like?","a":"Music."},{"q":"When do Ela and Defne play football?","a":"At break time."}],"quiz":[{"q":"Defne is my ___ friend.","o":["best","bus","bread"],"a":0,"why":""},{"q":"She ___ drawing.","o":["like","likes","liking"],"a":1,"why":"Üçüncü kişi için fiile 's' eklenir."},{"q":"When I am ___, she helps me.","o":["kind","sad","play"],"a":1,"why":""},{"q":"Let's ___ the ball.","o":["funny","happy","share"],"a":2,"why":""}],"drills":[{"type":"Yerine koyma","prompt":"She likes drawing.","cue":"music","answer":"She likes music."},{"type":"Dönüştürme","prompt":"Mert likes football.","cue":"Mert → He","answer":"He likes football."},{"type":"Soru yap","prompt":"She is my best friend.","cue":"Is…?","answer":"Is she your best friend?"}],"sounds":[{"focus":"/ɜː/","tr":"Dilini ağzının ortasında tut, dudakların hafif yuvarlansın ve sesi boğazında değil ağzında çıkar. Türkçedeki 'er' ile aynı değil; 'bird' ve 'her' kelimelerinde sesi uzat.","pairs":["bird / bed","her / hair"]}],"mission":{"brief":"Görev: En yakın arkadaşını İngilizce tanıt. Claude, arkadaşın Leo olacak ve senin arkadaşın hakkında sorular soracak.","persona":"Leo, a curious 9-year-old who loves making new friends. Uses short sentences and asks one question at a time. Hidden fact: Leo's best friend is a girl named Mia who moved to another city last year, and he only mentions her when the learner asks about someone who makes him happy.","goal":"En az üç cümle kur: 'My best friend is…', 'She likes…' ve 'We play…'.","opener":"Hi! I'm Leo. Do you have a best friend?"}},"KS1-031":{"objectives":["Deniz canlılarının adlarını söylemek","'Look at the…' ve 'Is it a…?' kalıplarını kullanmak","Renkleri ve büyüklükleri kısaca anlatmak"],"dialogues":[{"title":"A blue fish","setting":"Ali ve Ela denizin kıyısında, suya bakıyorlar.","lines":[{"s":"Ali","en":"Look! A blue fish!","tr":"Bak! Mavi bir balık!"},{"s":"Ela","en":"It can swim fast!","tr":"Çok hızlı yüzebiliyor!"},{"s":"Ali","en":"Is it a shark?","tr":"Köpekbalığı mı?"},{"s":"Ela","en":"No, it's a crab. It's red!","tr":"Hayır, bu bir yengeç. Kırmızı!"},{"s":"Ali","en":"Hello, crab! Hello, fish!","tr":"Merhaba, yengeç! Merhaba, balık!"},{"s":"Ela","en":"I love the sea!","tr":"Denizi çok seviyorum!"}]},{"title":"A big whale","setting":"Deniz kenarında, suyun içinde büyük bir hayvan var.","lines":[{"s":"Ela","en":"Look at the whale! It's big!","tr":"Balinaya bak! Çok büyük!"},{"s":"Ali","en":"Wow! Whales are very big.","tr":"Vay! Balinalar çok büyük."},{"s":"Ela","en":"Look at the octopus! It's pink!","tr":"Ahtapota bak! Pembe!"},{"s":"Ali","en":"Octopuses have eight arms.","tr":"Ahtapotların sekiz kolu var."},{"s":"Ela","en":"Can you see a starfish too?","tr":"Bir denizyıldızı da görebiliyor musun?"},{"s":"Ali","en":"Yes! It's yellow.","tr":"Evet! Sarı."}]},{"title":"Let's swim","setting":"Ali ve Ela suya giriyorlar.","lines":[{"s":"Ali","en":"Let's swim!","tr":"Hadi yüzelim!"},{"s":"Ela","en":"Yes! I swim like a fish.","tr":"Evet! Balık gibi yüzüyorum."},{"s":"Ali","en":"Look at the crab!","tr":"Yengece bak!"},{"s":"Ela","en":"It's small and red.","tr":"Küçük ve kırmızı."},{"s":"Ali","en":"Bye, crab! Bye, fish!","tr":"Hoşça kal, yengeç! Hoşça kal, balık!"},{"s":"Ela","en":"Let's swim again!","tr":"Tekrar yüzelim!"}]}],"reading":{"title":"A day at the sea","paras":[{"en":"Ali and Ela are at the sea. They see a fish, a crab and a big whale. The fish is blue and it swims fast. The crab is red. The octopus is pink! Ali sees a starfish too. It is yellow. Ela says, 'The sea is fun!' Then they swim in the warm water. What a fun day!","tr":"Ali ve Ela denizde. Bir balık, bir yengeç ve büyük bir balina görüyorlar. Balık mavi ve hızlı yüzüyor. Yengeç kırmızı. Ahtapot pembe! Ali ayrıca bir denizyıldızı görüyor. O sarı. Ela, 'Deniz çok eğlenceli!' diyor. Sonra ılık suda yüzüyorlar. Ne eğlenceli bir gün!"}]},"vocab":[{"w":"fish","ipa":"/fɪʃ/","pos":"🐟","tr":"balık","ex":"The fish is blue.","exTr":"Balık mavi."},{"w":"shark","ipa":"/ʃɑːk/","pos":"🦈","tr":"köpekbalığı","ex":"Is it a shark?","exTr":"Köpekbalığı mı?"},{"w":"whale","ipa":"/weɪl/","pos":"🐳","tr":"balina","ex":"The whale is very big.","exTr":"Balina çok büyük."},{"w":"crab","ipa":"/kræb/","pos":"🦀","tr":"yengeç","ex":"The crab is red.","exTr":"Yengeç kırmızı."},{"w":"octopus","ipa":"/ˈɒktəpəs/","pos":"🐙","tr":"ahtapot","ex":"The octopus is pink.","exTr":"Ahtapot pembe."},{"w":"starfish","ipa":"/ˈstɑːfɪʃ/","pos":"⭐","tr":"denizyıldızı","ex":"Look at the starfish!","exTr":"Denizyıldızına bak!"},{"w":"sea","ipa":"/siː/","pos":"🌊","tr":"deniz","ex":"I love the sea.","exTr":"Denizi çok seviyorum."},{"w":"swim","ipa":"/swɪm/","pos":"🏊","tr":"yüzmek","ex":"Let's swim!","exTr":"Hadi yüzelim!"}],"chunks":[{"en":"Look at the…!","tr":"…'e bak!"},{"en":"Is it a…?","tr":"… mı?"},{"en":"Let's swim!","tr":"Hadi yüzelim!"},{"en":"I love the sea!","tr":"Denizi çok seviyorum!"}],"grammar":{"point":"It's a… / It's + color","tr":"Bir hayvanı tanıtmak için 'It's a…' kullanırız, Türkçedeki 'Bu bir…' ile aynıdır. Renk ya da büyüklük söylerken 'a' kullanılmaz: 'It's red.'","examples":["It's a fish.","It's a big shark.","It's red.","It's a starfish."]},"questions":[{"q":"What colour is the fish?","a":"It's blue."},{"q":"Is the whale small?","a":"No, it's big."},{"q":"What colour is the starfish?","a":"It's yellow."}],"quiz":[{"q":"🦈 is a…","o":["fish","shark","crab"],"a":1,"why":""},{"q":"The crab is…","o":["red","pink","yellow"],"a":0,"why":""},{"q":"Which one is the whale?","o":["🐙","🦀","🐳"],"a":2,"why":""},{"q":"Ela says the sea is…","o":["sad","fun","hot"],"a":1,"why":""}],"drills":[{"type":"Yerine koyma","prompt":"The fish is blue.","cue":"pink","answer":"The fish is pink."},{"type":"Soru yap","prompt":"The whale is big.","cue":"Is…?","answer":"Is the whale big?"},{"type":"Genişletme","prompt":"The fish swims fast.","cue":"very","answer":"The fish swims very fast."}],"sounds":[{"focus":"/ʃ/","tr":"Türkçedeki 'ş' sesiyle aynıdır. 'sh' yazısını görünce 's' gibi değil 'ş' gibi oku: 'shark', 'fish'.","pairs":["ship / sip","shell / sell","dish / disk"]}],"mission":{"brief":"Denizde gezdiğini arkadaşın Ali'ye anlatacaksın. Claude, Ali olacak ve denizdeki hayvanlar hakkında sorular soracak. Her soruya İngilizce cevap ver ve en az üç deniz canlısını tarif et.","persona":"Ali, a friendly 7-year-old who loves the sea. Uses very short sentences and lots of 'Wow!'. Hidden fact: his favourite sea animal is the octopus, because it has eight arms. He reveals it only when the learner asks a clear question about his favourite sea animal.","goal":"Ali'nin en sevdiği deniz hayvanını öğren.","opener":"Hi! I'm Ali. Do you like the sea? Tell me about the animals you saw!"}},"KS1-032":{"objectives":["Masal karakterlerinin adlarını söylemek","'There is a…' kalıbını kullanmak","Kısa bir masal şarkısını ritimle tekrar etmek"],"dialogues":[{"title":"Once upon a time","setting":"Mina ve Kerem masal kitabına bakıyorlar.","lines":[{"s":"Mina","en":"Look! A castle!","tr":"Bak! Bir kale!"},{"s":"Kerem","en":"Wow! Who lives there?","tr":"Vay! Orada kim yaşıyor?"},{"s":"Mina","en":"There is a princess. She is kind.","tr":"Orada bir prenses var. Nazik."},{"s":"Kerem","en":"Is there a dragon too?","tr":"Peki bir ejderha da var mı?"},{"s":"Mina","en":"Yes! The dragon is big and red.","tr":"Evet! Ejderha büyük ve kırmızı."},{"s":"Kerem","en":"I want a horse, too!","tr":"Ben de bir at istiyorum!"}]},{"title":"The prince and the sword","setting":"Kerem ile Mina bahçede oyun oynuyorlar.","lines":[{"s":"Kerem","en":"I am a prince. I have a sword!","tr":"Ben bir prensim. Bir kılıcım var!"},{"s":"Mina","en":"I am a princess! I have magic!","tr":"Ben bir prensesim! Sihrim var!"},{"s":"Kerem","en":"Oh no! A wizard!","tr":"Aman! Bir büyücü!"},{"s":"Mina","en":"Don't worry. The wizard is friendly.","tr":"Merak etme. Büyücü dost canlısı."},{"s":"Kerem","en":"Hello, wizard! Do you like the castle?","tr":"Merhaba büyücü! Kaleyi sever misin?"},{"s":"Mina","en":"Yes! Let's play again!","tr":"Evet! Tekrar oynayalım!"}]},{"title":"Fairy tale song","setting":"Ritimle tekrar et, alkışla!","lines":[{"s":"Teacher","en":"Castle, castle, up so high!","tr":"Kale, kale, çok yüksek!"},{"s":"Kids","en":"Castle, castle, up so high!","tr":"Kale, kale, çok yüksek!"},{"s":"Teacher","en":"Dragon, dragon, fly, fly, fly!","tr":"Ejderha, ejderha, uç, uç, uç!"},{"s":"Kids","en":"Dragon, dragon, fly, fly, fly!","tr":"Ejderha, ejderha, uç, uç, uç!"},{"s":"Teacher","en":"Magic, magic, clap your hands!","tr":"Sihir, sihir, ellerini çırp!"},{"s":"Kids","en":"Magic, magic, clap your hands!","tr":"Sihir, sihir, ellerini çırp!"}]}],"reading":{"title":"Lila and the wizard","paras":[{"en":"Once upon a time, there was a princess named Lila. She lived in a big castle with a dragon. The dragon was not scary. He was kind and he liked to fly. One day, a wizard came to the castle. He had a magic hat. 'Hello, princess!' he said. Lila smiled. They played all day!","tr":"Bir zamanlar Lila adında bir prenses vardı. Büyük bir kalede bir ejderhayla yaşıyordu. Ejderha korkutucu değildi. Nazikti ve uçmayı severdi. Bir gün kaleye bir büyücü geldi. Sihirli bir şapkası vardı. 'Merhaba, prenses!' dedi. Lila gülümsedi. Bütün gün birlikte oynadılar!"}]},"vocab":[{"w":"prince","ipa":"/prɪns/","pos":"🤴","tr":"prens","ex":"The prince is kind.","exTr":"Prens nazik."},{"w":"princess","ipa":"/ˌprɪnˈses/","pos":"👸","tr":"prenses","ex":"I am a princess!","exTr":"Ben bir prensesim!"},{"w":"castle","ipa":"/ˈkɑːsl/","pos":"🏰","tr":"kale","ex":"The castle is big.","exTr":"Kale büyük."},{"w":"dragon","ipa":"/ˈdræɡən/","pos":"🐉","tr":"ejderha","ex":"The dragon can fly.","exTr":"Ejderha uçabilir."},{"w":"horse","ipa":"/hɔːs/","pos":"🐴","tr":"at","ex":"I want a horse.","exTr":"Bir at istiyorum."},{"w":"sword","ipa":"/sɔːd/","pos":"🗡️","tr":"kılıç","ex":"The prince has a sword.","exTr":"Prensin bir kılıcı var."},{"w":"magic","ipa":"/ˈmædʒɪk/","pos":"✨","tr":"sihir","ex":"The wizard has magic.","exTr":"Büyücünün sihri var."},{"w":"wizard","ipa":"/ˈwɪzəd/","pos":"🧙","tr":"büyücü","ex":"The wizard has a magic hat.","exTr":"Büyücünün sihirli bir şapkası var."}],"chunks":[{"en":"Once upon a time…","tr":"Bir zamanlar…"},{"en":"I am a princess!","tr":"Ben bir prensesim!"},{"en":"Let's play again!","tr":"Tekrar oynayalım!"},{"en":"Don't worry.","tr":"Merak etme."}],"grammar":{"point":"There is a…","tr":"Bir yerde bir şey olduğunu söylemek için 'There is a…' kullanılır. Türkçedeki 'Orada bir … var' cümlesine benzer.","examples":["There is a castle.","There is a dragon.","There is a wizard.","There is a horse."]},"questions":[{"q":"Who lives in the castle?","a":"A princess and a dragon."},{"q":"Is the dragon scary?","a":"No, he is kind."},{"q":"What does the wizard have?","a":"A magic hat."}],"quiz":[{"q":"🐉 is a…","o":["dragon","horse","wizard"],"a":0,"why":""},{"q":"The ___ has a sword. (🤴)","o":["castle","prince","magic"],"a":1,"why":""},{"q":"The castle is…","o":["small","kind","big"],"a":2,"why":""},{"q":"The wizard has a…","o":["horse","magic hat","castle"],"a":1,"why":""}],"drills":[{"type":"Yerine koyma","prompt":"I am a princess!","cue":"prince","answer":"I am a prince!"},{"type":"Soru yap","prompt":"The castle is big.","cue":"Is…?","answer":"Is the castle big?"},{"type":"Genişletme","prompt":"I want a horse.","cue":"and a sword","answer":"I want a horse and a sword."}],"sounds":[{"focus":"/æ/","tr":"Ağzını geniş aç, dilini alt dişlere yaslayarak 'e' ile 'a' arası bir ses çıkar. Türkçede bu ses yok; 'a' gibi değil, 'e' gibi başlayıp 'a' gibi bitir: 'hat', 'dragon'.","pairs":["hat / hut","bad / bed","cat / cut"]}],"mission":{"brief":"Masal kalesinin kapısı kapalı ve bekçi seni içeri almıyor. Claude, bekçi Sam olacak. Ejderhanın adını öğrenirsen kapıyı açacak, bu yüzden ona sorular sor.","persona":"Sam, a friendly castle guard who speaks in short, simple sentences. He is kind and playful. Hidden fact: the dragon's name is Fizz, and Sam tells it only when the learner asks a clear question about the dragon's name.","goal":"Bekçiden ejderhanın adını öğren.","opener":"Hello! I am the castle guard. Who are you?"}},"KS1-033":{"objectives":["Hayvanların adlarını söylemek","'I can see a…' kalıbını kullanmak","Kısa bir hayvan şarkısını ritimle tekrar etmek"],"dialogues":[{"title":"At the zoo gate","setting":"Hayvanat bahçesinin girişinde, heyecanlı bir gün.","lines":[{"s":"Ece","en":"Look, Tom! The zoo!","tr":"Bak Tom! Hayvanat bahçesi!"},{"s":"Tom","en":"Yes! Can you see a lion?","tr":"Evet! Bir aslan görebiliyor musun?"},{"s":"Ece","en":"Yes, I can! It is big and yellow.","tr":"Evet, görebiliyorum! Büyük ve sarı."},{"s":"Tom","en":"Let's go! Hello, lion!","tr":"Hadi gidelim! Merhaba aslan!"},{"s":"Ece","en":"Oh, a tiger too!","tr":"Aa, bir kaplan da var!"},{"s":"Tom","en":"Wow, it has stripes!","tr":"Vay, çizgileri var!"}]},{"title":"The monkey and the banana","setting":"Hayvanat bahçesinde, bir maymunun önünde.","lines":[{"s":"Tom","en":"Look at the monkey!","tr":"Maymuna bak!"},{"s":"Ece","en":"It is eating a banana. Yum!","tr":"Muz yiyor. Hmm, lezzetli!"},{"s":"Tom","en":"I can see a giraffe!","tr":"Bir zürafa görebiliyorum!"},{"s":"Ece","en":"Giraffes are very tall.","tr":"Zürafalar çok uzun."},{"s":"Tom","en":"And the elephant is big!","tr":"Ve fil çok büyük!"},{"s":"Ece","en":"Hello, elephant! I love the zoo!","tr":"Merhaba fil! Hayvanat bahçesini çok seviyorum!"}]},{"title":"Animal song","setting":"Ritimle tekrar et, alkışla!","lines":[{"s":"Teacher","en":"Lion, lion, roar, roar, roar!","tr":"Aslan, aslan, kükre, kükre, kükre!"},{"s":"Kids","en":"Lion, lion, roar, roar, roar!","tr":"Aslan, aslan, kükre, kükre, kükre!"},{"s":"Teacher","en":"Bear, bear, big and brown!","tr":"Ayı, ayı, büyük ve kahverengi!"},{"s":"Kids","en":"Bear, bear, big and brown!","tr":"Ayı, ayı, büyük ve kahverengi!"},{"s":"Teacher","en":"Monkey, monkey, jump up high!","tr":"Maymun, maymun, yukarı zıpla!"},{"s":"Kids","en":"Monkey, monkey, jump up high!","tr":"Maymun, maymun, yukarı zıpla!"}]}],"reading":{"title":"A trip to the zoo","paras":[{"en":"Today Ece and Tom go to the zoo. First they see a lion. The lion is big and it roars. Then they see a monkey eating a banana. A giraffe is very tall. A zebra has black and white stripes. Ece likes the parrot best. It can say 'hello'! 'I love the zoo,' says Tom. They have a lot of fun.","tr":"Bugün Ece ve Tom hayvanat bahçesine gidiyor. Önce bir aslan görüyorlar. Aslan büyük ve kükrüyor. Sonra muz yiyen bir maymun görüyorlar. Zürafa çok uzun. Zebranın siyah beyaz çizgileri var. Ece en çok papağanı seviyor. Papağan 'merhaba' diyebiliyor! 'Hayvanat bahçesini seviyorum,' diyor Tom. Çok eğleniyorlar."}]},"vocab":[{"w":"lion","ipa":"/ˈlaɪən/","pos":"🦁","tr":"aslan","ex":"The lion is big.","exTr":"Aslan büyük."},{"w":"elephant","ipa":"/ˈelɪfənt/","pos":"🐘","tr":"fil","ex":"The elephant is grey.","exTr":"Fil gri."},{"w":"monkey","ipa":"/ˈmʌŋki/","pos":"🐵","tr":"maymun","ex":"The monkey eats a banana.","exTr":"Maymun muz yer."},{"w":"giraffe","ipa":"/dʒɪˈrɑːf/","pos":"🦒","tr":"zürafa","ex":"The giraffe is very tall.","exTr":"Zürafa çok uzun."},{"w":"zebra","ipa":"/ˈzebrə/","pos":"🦓","tr":"zebra","ex":"The zebra has stripes.","exTr":"Zebranın çizgileri var."},{"w":"tiger","ipa":"/ˈtaɪɡə/","pos":"🐯","tr":"kaplan","ex":"The tiger is orange.","exTr":"Kaplan turuncu."},{"w":"bear","ipa":"/beə/","pos":"🐻","tr":"ayı","ex":"The bear is brown.","exTr":"Ayı kahverengi."},{"w":"parrot","ipa":"/ˈpærət/","pos":"🦜","tr":"papağan","ex":"The parrot can talk.","exTr":"Papağan konuşabilir."}],"chunks":[{"en":"Look at the…!","tr":"…'e bak!"},{"en":"Can you see a…?","tr":"Bir … görebiliyor musun?"},{"en":"Let's go!","tr":"Hadi gidelim!"},{"en":"I love the zoo!","tr":"Hayvanat bahçesini seviyorum!"}],"grammar":{"point":"I can see a…","tr":"Bir şeyi görebildiğini söylemek için 'I can see a…' kullanılır. Türkçedeki 'Bir … görebiliyorum' cümlesine benzer. Soru yapmak için 'can' başa gelir: 'Can you see a…?'","examples":["I can see a lion.","Can you see a zebra?","I can see a tiger.","We can see a bear."]},"questions":[{"q":"What is the monkey eating?","a":"A banana."},{"q":"What does the zebra have?","a":"Black and white stripes."},{"q":"What can the parrot say?","a":"Hello."}],"quiz":[{"q":"🦒 is a…","o":["zebra","tiger","giraffe"],"a":2,"why":""},{"q":"The monkey eats a…","o":["banana","fish","ball"],"a":0,"why":""},{"q":"Which animal is very tall?","o":["lion","giraffe","bear"],"a":1,"why":""},{"q":"What can the parrot say?","o":["Banana.","Hello.","Stripes."],"a":1,"why":""}],"drills":[{"type":"Yerine koyma","prompt":"The lion is big.","cue":"small","answer":"The lion is small."},{"type":"Soru yap","prompt":"The zebra has stripes.","cue":"Does…?","answer":"Does the zebra have stripes?"},{"type":"Genişletme","prompt":"I can see a bear.","cue":"and a parrot","answer":"I can see a bear and a parrot."}],"sounds":[{"focus":"/z/","tr":"Türkçedeki 'z' ile aynıdır. Kelimenin sonunda ya da ortasında sesi titret, 's' gibi sert okuma: 'zoo', 'zebra'.","pairs":["zoo / sue","zip / sip","buzz / bus"]}],"mission":{"brief":"Hayvanat bahçesine gitmek üzeresin ve arkadaşın Tom'a hangi hayvanları göreceğini söylemen gerekiyor. Claude, Tom olacak ve en sevdiğin hayvanı soracak. En az üç hayvan adını İngilizce söyle.","persona":"Tom, a friendly 8-year-old boy who loves animals. Uses short sentences and lots of questions. Hidden fact: his favourite animal is the penguin, but he feels shy about it and only says so when the learner asks what his favourite animal is.","goal":"Tom'un en sevdiği hayvanı öğren.","opener":"Hi! Which animal do you like best at the zoo?"}},"KS1-034":{"objectives":["Bahçedeki bitki ve böceklerin adlarını söylemek","'The … is…' kalıbıyla bir şeyi tanımlamak","Nazik bir şekilde yardım istemek ve teşekkür etmek"],"dialogues":[{"title":"Our garden","setting":"Defne ve Jack, Defne'nin bahçesinde.","lines":[{"s":"Defne","en":"Welcome to my garden, Jack!","tr":"Bahçeme hoş geldin, Jack!"},{"s":"Jack","en":"Wow! Beautiful flowers!","tr":"Vay! Güzel çiçekler!"},{"s":"Defne","en":"Look, a big tree!","tr":"Bak, büyük bir ağaç!"},{"s":"Jack","en":"The sun is hot today.","tr":"Bugün güneş çok sıcak."},{"s":"Defne","en":"Let's sit under the tree.","tr":"Hadi ağacın altına oturalım."},{"s":"Jack","en":"Yes, good idea!","tr":"Evet, güzel fikir!"}]},{"title":"A busy bee","setting":"Bahçede, çiçeklerin arasında.","lines":[{"s":"Jack","en":"Look! A bee!","tr":"Bak! Bir arı!"},{"s":"Defne","en":"Don't worry. The bee is busy, not angry.","tr":"Merak etme. Arı meşgul, kızgın değil."},{"s":"Jack","en":"Now I see a butterfly!","tr":"Şimdi bir kelebek görüyorum!"},{"s":"Defne","en":"It's very pretty! Blue and yellow.","tr":"Çok güzel! Mavi ve sarı."},{"s":"Jack","en":"And a ladybird on that leaf!","tr":"Ve şu yaprağın üstünde bir uğur böceği!"},{"s":"Defne","en":"Ladybirds are red with black dots.","tr":"Uğur böcekleri kırmızı, siyah noktalı olur."}]},{"title":"Water the plants","setting":"Defne bitkileri suluyor.","lines":[{"s":"Defne","en":"Now, let's water the flowers!","tr":"Şimdi çiçekleri sulayalım!"},{"s":"Jack","en":"Yes! Where is the water?","tr":"Evet! Su nerede?"},{"s":"Defne","en":"Here is the watering can.","tr":"İşte sulama kabı."},{"s":"Jack","en":"Water, water, flowers grow!","tr":"Su, su, çiçekler büyüsün!"},{"s":"Defne","en":"Thank you, sun!","tr":"Teşekkürler, güneş!"},{"s":"Jack","en":"The garden is happy!","tr":"Bahçe mutlu!"}]}],"reading":{"title":"Defne's garden","paras":[{"en":"Defne has a small garden. In her garden there are red flowers, a big tree and green grass. Every morning Defne waters the flowers with a watering can. The sun is hot, but the flowers are happy. A busy bee flies from flower to flower. A pretty butterfly sits on a leaf. Jack says, 'Your garden is beautiful!' Defne smiles.","tr":"Defne'nin küçük bir bahçesi var. Bahçesinde kırmızı çiçekler, büyük bir ağaç ve yeşil çimenler var. Her sabah Defne çiçekleri sulama kabıyla suluyor. Güneş sıcak ama çiçekler mutlu. Çalışkan bir arı bir çiçekten diğerine uçuyor. Güzel bir kelebek bir yaprağın üstüne konuyor. Jack, 'Bahçen çok güzel!' diyor. Defne gülümsüyor."}]},"vocab":[{"w":"garden","ipa":"/ˈɡɑːdn/","pos":"🏡","tr":"bahçe","ex":"I have a garden.","exTr":"Bir bahçem var."},{"w":"flower","ipa":"/ˈflaʊə/","pos":"🌸","tr":"çiçek","ex":"The flower is pink.","exTr":"Çiçek pembe."},{"w":"tree","ipa":"/triː/","pos":"🌳","tr":"ağaç","ex":"The tree is big.","exTr":"Ağaç büyük."},{"w":"bee","ipa":"/biː/","pos":"🐝","tr":"arı","ex":"The bee is busy.","exTr":"Arı meşgul."},{"w":"butterfly","ipa":"/ˈbʌtəflaɪ/","pos":"🦋","tr":"kelebek","ex":"The butterfly is pretty.","exTr":"Kelebek çok güzel."},{"w":"sun","ipa":"/sʌn/","pos":"☀️","tr":"güneş","ex":"The sun is hot.","exTr":"Güneş sıcak."},{"w":"ladybird","ipa":"/ˈleɪdibɜːd/","pos":"🐞","tr":"uğur böceği","ex":"The ladybird is red.","exTr":"Uğur böceği kırmızı."},{"w":"water","ipa":"/ˈwɔːtə/","pos":"💧","tr":"su","ex":"Water the flowers, please.","exTr":"Çiçekleri sula, lütfen."}],"chunks":[{"en":"Welcome to my garden!","tr":"Bahçeme hoş geldin!"},{"en":"Let's sit under the tree.","tr":"Hadi ağacın altına oturalım."},{"en":"Don't worry.","tr":"Merak etme."},{"en":"Thank you, sun!","tr":"Teşekkürler, güneş!"}],"grammar":{"point":"The … is + adjective","tr":"Bir şeyin nasıl olduğunu söylemek için 'is' ve bir sıfat kullanılır: 'The sun is hot.' Türkçede 'Güneş sıcak' demektir. Sıfat, 'is'ten sonra gelir.","examples":["The flower is pink.","The tree is big.","The sun is hot.","The bee is busy."]},"questions":[{"q":"What is in Defne's garden?","a":"Red flowers, a big tree and green grass."},{"q":"What does Defne water the flowers with?","a":"A watering can."},{"q":"What sits on the leaf?","a":"A butterfly."}],"quiz":[{"q":"🌸 is a…","o":["flower","tree","sun"],"a":0,"why":""},{"q":"The sun is…","o":["cold","hot","blue"],"a":1,"why":""},{"q":"Which one has red dots?","o":["bee","ladybird","garden"],"a":1,"why":""},{"q":"Defne waters the flowers with a…","o":["bee","sun","watering can"],"a":2,"why":""}],"drills":[{"type":"Yerine koyma","prompt":"The butterfly is pretty.","cue":"ladybird","answer":"The ladybird is pretty."},{"type":"Soru yap","prompt":"The garden is beautiful.","cue":"Is…?","answer":"Is the garden beautiful?"},{"type":"Genişletme","prompt":"I see a bee.","cue":"and a butterfly","answer":"I see a bee and a butterfly."}],"sounds":[{"focus":"/w/","tr":"Türkçede 'w' sesi yok, 'v' gibi okunmaz. Dudaklarını yuvarlak ve öne doğru tut, sesi çıkarmadan önce dudakları yuvarla: 'water', 'wet'.","pairs":["wet / vet","west / vest","wine / vine"]}],"mission":{"brief":"Dedenin bahçesindeki bitkilerin suya ihtiyacı var ama hangisinin olduğunu bilmiyorsun. Claude, bahçıvan Jack olacak. Ona bahçedeki bitkiler hakkında sorular sor ve hangi bitkiyi sulaman gerektiğini öğren.","persona":"Jack, a friendly gardener aged 8. Speaks in short, simple sentences and loves plants. Hidden fact: the one plant that needs water today is the small tree near the fence. He tells the learner only when they ask which plant needs water.","goal":"Jack'ten hangi bitkinin suya ihtiyacı olduğunu öğren.","opener":"Hi! I need help in the garden. Can you water the plants?"}},"KS1-035":{"objectives":["1'den 10'a kadar sayıları İngilizce saymak","'Let's…' kalıbıyla birlikte bir şey önermek","Bir şeyin ne kadar olduğunu sormak"],"dialogues":[{"title":"At the shop","setting":"Okulun yanındaki markette, öğle arasında.","lines":[{"s":"Sara","en":"Let's go to the shop!","tr":"Hadi markete gidelim!"},{"s":"Mert","en":"Good! I have some money.","tr":"Harika! Biraz param var."},{"s":"Sara","en":"How many coins do you have?","tr":"Kaç madeni paran var?"},{"s":"Mert","en":"I have five coins. Look!","tr":"Beş madeni param var. Bak!"},{"s":"Sara","en":"Let's count: one, two, three…","tr":"Sayalım: bir, iki, üç…"},{"s":"Mert","en":"…four, five. Five coins!","tr":"…dört, beş. Beş madeni para!"}]},{"title":"How much is it?","setting":"Kasada, kekin yanında.","lines":[{"s":"Mert","en":"How much is this cake?","tr":"Bu kek ne kadar?"},{"s":"Shopkeeper","en":"It's ten coins. Here you are.","tr":"On madeni para. Buyurun."},{"s":"Sara","en":"Oh no! We have only six.","tr":"Aman! Sadece altı tane var."},{"s":"Mert","en":"Then let's buy a cookie.","tr":"O zaman bir kurabiye alalım."},{"s":"Shopkeeper","en":"A cookie is one coin. Thank you!","tr":"Bir kurabiye bir madeni para. Teşekkürler!"},{"s":"Sara","en":"Thank you! Bye!","tr":"Teşekkürler! Hoşça kal!"}]},{"title":"Counting song","setting":"Ritimle tekrar et, alkışla!","lines":[{"s":"Teacher","en":"One, two, let's buy a cake!","tr":"Bir, iki, bir kek alalım!"},{"s":"Kids","en":"One, two, let's buy a cake!","tr":"Bir, iki, bir kek alalım!"},{"s":"Teacher","en":"Three, four, five coins more!","tr":"Üç, dört, beş madeni para daha!"},{"s":"Kids","en":"Three, four, five coins more!","tr":"Üç, dört, beş madeni para daha!"},{"s":"Teacher","en":"Nine, ten, we are done!","tr":"Dokuz, on, işimiz bitti!"},{"s":"Kids","en":"Nine, ten, we are done!","tr":"Dokuz, on, işimiz bitti!"}]}],"reading":{"title":"Mert and Sara at the shop","paras":[{"en":"Mert and Sara are at the shop. Mert has five coins. Sara has one coin. They count the money together: one, two, three, four, five, six. Six coins! The cake costs ten coins, so they can't buy it. They buy a cookie with the six coins. They smile. 'We can buy a cookie!' says Sara. 'Counting is fun!' says Mert.","tr":"Mert ve Sara markette. Mert'in beş madeni parası var. Sara'nın bir madeni parası var. Parayı birlikte sayıyorlar: bir, iki, üç, dört, beş, altı. Altı madeni para! Kek on madeni para, bu yüzden alamıyorlar. Altı parayla bir kurabiye alıyorlar. Gülümsüyorlar. 'Bir kurabiye alabiliriz!' diyor Sara. 'Saymak eğlenceli!' diyor Mert."}]},"vocab":[{"w":"money","ipa":"/ˈmʌni/","pos":"💰","tr":"para","ex":"I have some money.","exTr":"Biraz param var."},{"w":"coin","ipa":"/kɔɪn/","pos":"🪙","tr":"madeni para","ex":"This coin is shiny.","exTr":"Bu madeni para parlak."},{"w":"one","ipa":"/wʌn/","pos":"1️⃣","tr":"bir","ex":"I have one coin.","exTr":"Bir madeni param var."},{"w":"five","ipa":"/faɪv/","pos":"5️⃣","tr":"beş","ex":"Five coins, please.","exTr":"Beş madeni para, lütfen."},{"w":"ten","ipa":"/ten/","pos":"🔟","tr":"on","ex":"The cake is ten coins.","exTr":"Kek on madeni para."},{"w":"shop","ipa":"/ʃɒp/","pos":"🏪","tr":"market, dükkân","ex":"The shop is near school.","exTr":"Market okulun yanında."},{"w":"buy","ipa":"/baɪ/","pos":"🛍️","tr":"satın almak","ex":"Let's buy a cake!","exTr":"Bir kek alalım!"},{"w":"cake","ipa":"/keɪk/","pos":"🎂","tr":"kek","ex":"I love cake.","exTr":"Keki çok severim."}],"chunks":[{"en":"How much is it?","tr":"Ne kadar?"},{"en":"Let's count!","tr":"Sayalım!"},{"en":"Let's buy…!","tr":"… alalım!"},{"en":"Here you are.","tr":"Buyurun."}],"grammar":{"point":"Let's + verb","tr":"'Let's' 'hadi … yapalım' anlamına gelir. Let's'ten sonra fiil gelir ve kelime değişmez: 'Let's count!' Hadi sayalım!","examples":["Let's count the coins.","Let's buy a cake.","Let's go to the shop.","Let's play!"]},"questions":[{"q":"How many coins does Mert have?","a":"Five."},{"q":"How many coins do they have together?","a":"Six."},{"q":"Can they buy the cake?","a":"No, they can't."}],"quiz":[{"q":"Mert has ___ coins.","o":["ten","five","one"],"a":1,"why":""},{"q":"The cake costs…","o":["one coin","six coins","ten coins"],"a":2,"why":""},{"q":"Mert and Sara together have…","o":["five","six","ten"],"a":1,"why":""},{"q":"Let's ___ a cake!","o":["count","one","buy"],"a":2,"why":""}],"drills":[{"type":"Yerine koyma","prompt":"I have five coins.","cue":"ten","answer":"I have ten coins."},{"type":"Soru yap","prompt":"The shop is near school.","cue":"Is…?","answer":"Is the shop near school?"},{"type":"Genişletme","prompt":"Let's buy a cake.","cue":"and a cookie","answer":"Let's buy a cake and a cookie."}],"sounds":[{"focus":"/ʌ/","tr":"Kısa ve orta açık bir ses: 'a' ile 'ı' arası. Ağzını çok açma, 'a' gibi uzatma: 'one', 'money'.","pairs":["cup / cap","luck / lack","run / ran"]}],"mission":{"brief":"Markette alışveriş yapıyorsun ve kaç madeni paran olduğunu kasiyere söylemen gerekiyor. Claude, kasiyer Mr. Lee olacak. Ona kaç paran olduğunu İngilizce söyle, fiyatı sor ve bir şey satın al.","persona":"Mr. Lee, a cheerful shopkeeper who speaks in short, simple sentences. Hidden fact: today cookies are on a special price of four coins, but he only mentions it when the learner asks if there is a special price today.","goal":"Kasiyerden kurabiyenin özel fiyatını öğren.","opener":"Hello! What can I get for you today?"}},"KS1-036":{"objectives":["Selamlaşma ve veda ifadelerini söylemek","'Thank you', 'please' ve 'sorry' kelimelerini doğru yerde kullanmak","Kısa bir şarkıyla kibar sözleri tekrar etmek"],"dialogues":[{"title":"Good morning","setting":"Sabah, okul bahçesinde.","lines":[{"s":"Ben","en":"Good morning, Ceren!","tr":"Günaydın, Ceren!"},{"s":"Ceren","en":"Hello, Ben! How are you?","tr":"Merhaba, Ben! Nasılsın?"},{"s":"Ben","en":"I'm happy. Thank you!","tr":"Mutluyum. Teşekkürler!"},{"s":"Ceren","en":"Please sit next to me.","tr":"Lütfen yanıma otur."},{"s":"Ben","en":"Yes! You are my friend.","tr":"Evet! Sen benim arkadaşımsın."}]},{"title":"Saying sorry","setting":"Sınıfta, oyun saatinde.","lines":[{"s":"Ben","en":"Oops! Sorry, Ceren.","tr":"Ops! Özür dilerim, Ceren."},{"s":"Ceren","en":"That's OK, Ben.","tr":"Sorun değil, Ben."},{"s":"Ben","en":"Can I have the red ball, please?","tr":"Kırmızı topu alabilir miyim, lütfen?"},{"s":"Ceren","en":"Of course. Here you are.","tr":"Tabii. Buyur."},{"s":"Ben","en":"Thank you very much!","tr":"Çok teşekkür ederim!"},{"s":"Ceren","en":"You're welcome!","tr":"Rica ederim!"}]},{"title":"Goodbye song","setting":"Ritimle tekrar et, el salla!","lines":[{"s":"Teacher","en":"Hello, hello, how are you?","tr":"Merhaba, merhaba, nasılsın?"},{"s":"Kids","en":"Hello, hello, I'm fine, thank you!","tr":"Merhaba, merhaba, iyiyim, teşekkürler!"},{"s":"Teacher","en":"Goodbye, goodbye, see you soon!","tr":"Hoşça kal, hoşça kal, yakında görüşürüz!"},{"s":"Kids","en":"Goodbye, goodbye, see you soon!","tr":"Hoşça kal, hoşça kal, yakında görüşürüz!"},{"s":"Teacher","en":"Good night, friends! Good night!","tr":"İyi geceler, arkadaşlar! İyi geceler!"},{"s":"Kids","en":"Good night, friends! Good night!","tr":"İyi geceler, arkadaşlar! İyi geceler!"}]}],"reading":{"title":"Ben and Ceren's day","paras":[{"en":"Every day, Ben and Ceren say hello to their teacher. 'Good morning!' says Ben with a smile. At lunch, they say 'please' and 'thank you'. When Ben steps on Ceren's foot, he says 'Sorry!' She says, 'That's OK.' At the end of the day, they wave and say 'Goodbye!' 'Good night, friend!' says Ceren at home.","tr":"Her gün Ben ve Ceren öğretmenlerine merhaba derler. 'Günaydın!' diyor Ben gülümseyerek. Öğle yemeğinde 'lütfen' ve 'teşekkürler' derler. Ben Ceren'in ayağına basınca 'Özür dilerim!' der. Ceren, 'Sorun değil,' der. Günün sonunda el sallayıp 'Hoşça kal!' derler. Evde Ceren, 'İyi geceler, arkadaşım!' diyor."}]},"vocab":[{"w":"hello","ipa":"/həˈləʊ/","pos":"👋","tr":"merhaba","ex":"Hello, Mum!","exTr":"Merhaba, anne!"},{"w":"goodbye","ipa":"/ˌɡʊdˈbaɪ/","pos":"🖐️","tr":"hoşça kal","ex":"Goodbye, see you!","exTr":"Hoşça kal, görüşürüz!"},{"w":"thank you","ipa":"/ˈθæŋk juː/","pos":"😊","tr":"teşekkürler","ex":"Thank you for the ball.","exTr":"Top için teşekkürler."},{"w":"please","ipa":"/pliːz/","pos":"🙏","tr":"lütfen","ex":"Please sit down.","exTr":"Lütfen otur."},{"w":"sorry","ipa":"/ˈsɒri/","pos":"😢","tr":"özür dilerim","ex":"Sorry, I'm late.","exTr":"Özür dilerim, geciktim."},{"w":"friend","ipa":"/frend/","pos":"🤝","tr":"arkadaş","ex":"You are my friend.","exTr":"Sen benim arkadaşımsın."},{"w":"morning","ipa":"/ˈmɔːnɪŋ/","pos":"🌅","tr":"sabah","ex":"Good morning, Ben!","exTr":"Günaydın, Ben!"},{"w":"night","ipa":"/naɪt/","pos":"🌙","tr":"gece","ex":"Good night, friend!","exTr":"İyi geceler, arkadaşım!"}],"chunks":[{"en":"Good morning!","tr":"Günaydın!"},{"en":"Thank you!","tr":"Teşekkürler!"},{"en":"You're welcome!","tr":"Rica ederim!"},{"en":"See you soon!","tr":"Yakında görüşürüz!"}],"grammar":{"point":"I'm / You're","tr":"'I'm' 'ben … im' ve 'You're' 'sen … sin' anlamına gelir. Bu kısa biçimler günlük konuşmada çok kullanılır.","examples":["I'm happy.","You're my friend.","I'm new here.","You're welcome!"]},"questions":[{"q":"What does Ben say when he steps on Ceren's foot?","a":"Sorry!"},{"q":"What do they say at the end of the day?","a":"Goodbye!"},{"q":"What does Ceren say at home?","a":"Good night, friend!"}],"quiz":[{"q":"When you hurt someone, you say…","o":["Sorry","Please","Hello"],"a":0,"why":""},{"q":"It's 8 in the morning. You say…","o":["Good night","Good morning","Goodbye"],"a":1,"why":""},{"q":"Someone gives you a present. You say…","o":["Thank you","Sorry","Night"],"a":0,"why":""},{"q":"Ask nicely: 'Can I have the ball, ___?'","o":["hello","friend","please"],"a":2,"why":""}],"drills":[{"type":"Yerine koyma","prompt":"Good morning, Ben!","cue":"night","answer":"Good night, Ben!"},{"type":"Soru yap","prompt":"You are my friend.","cue":"Are…?","answer":"Are you my friend?"},{"type":"Genişletme","prompt":"Thank you!","cue":"very much","answer":"Thank you very much!"}],"sounds":[{"focus":"/θ/","tr":"Dilinin ucunu üst dişlerinin arasına koy ve hafifçe üfle. Türkçede 'th' sesi yok; 't' gibi okuma: 'thank' 'tank' olmasın.","pairs":["thank / tank","think / sink","three / free"]}],"mission":{"brief":"Yeni bir arkadaşınla ilk kez tanışıyorsun ve sınıfta ona kibar davranman gerekiyor. Claude, yeni arkadaş Mia olacak. Ona günaydın de, teşekkür et ve özür dilemen gerekirse kibarca özür dile.","persona":"Mia, a shy 8-year-old who has just joined the class. Speaks in short, simple sentences and is very polite. Hidden fact: her birthday is on Friday, and she tells only if the learner asks a clear question about a special day or her birthday.","goal":"Mia'nın doğum gününün ne zaman olduğunu öğren.","opener":"Hi! I'm Mia. I'm new here. Good morning!"}}};